    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Goretusk Snouts", sourceKind = "collect", uiMapID = 1436, x = 0.5042, y = 0.2935, coordFrame = "era", continentID = 0, worldX = -10084.8332355, worldY = 1251.967, questID = 38, objectiveIndex = 3, itemID = 731, itemName = "Goretusk Snout", count = 3, questTitle = "Westfall Stew", kind = "complete", text = "Collect Goretusk Snout ×3 — Westfall Stew", detail = "Sources: Young Goretusk, Goretusk.\n\nYoung Goretusks root in the fields along the road south from Saldean's to Sentinel Hill: take their snouts on the way.", index = 51},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Sentinel Hill's tower and Thor", sourceKind = "turnin", races = {"Human"}, uiMapID = 1436, x = 0.5633, y = 0.4752, coordFrame = "era", continentID = 0, worldX = -10508.7998416, worldY = 1045.117, worldZ = 60.7, questID = 109, npcID = 234, npcName = "Gryan Stoutmantle", questTitle = "Report to Gryan Stoutmantle", kind = "turnin", text = "Turn in: Report to Gryan Stoutmantle", detail = "Talk to Gryan Stoutmantle.\n\nGryan Stoutmantle and Captain Danuvin stand at the top of the stone tower, Quartermaster Lewis inside it, Thor the gryphon master on the south side of the hill with Scout Galiaan beside him. Thor gives you Lewis' note for Osric Strang with a free flight to Stormwind: take it now. In Stormwind, Morgan Pestle's shop is in the Trade District by the gryphons, Osric's shop, Limited Immunity, in Old Town; Baros Alexston stands in Cathedral Square on the way back to Dungar Longdrink, the gryphon master.", index = 52},
