    {id = "b0024g01", blockID = 24, sourceBlock = 24, sourceGoal = 1, blockTitle = "Molsen Farm: kill these as you meet them", sourceKind = "kill", uiMapID = 1436, x = 0.5156, y = 0.4664, coordFrame = "era", continentID = 0, worldX = -10488.2665112, worldY = 1212.067, worldZ = 67.2, questID = 12, objectiveIndex = 2, npcID = 95, count = 15, questTitle = "The People's Militia", kind = "complete", text = "Kill Defias Smuggler ×15 — The People's Militia", detail = "Defias Trappers and Smugglers camp in the fields between Sentinel Hill and Molsen Farm.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, Okra and sometimes a Precessive Autocognition Assembly. Foe Reaper 4000, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew.", index = 78},
