    {id = "b0024g09", blockID = 24, sourceBlock = 24, sourceGoal = 9, blockTitle = "Molsen Farm: kill these as you meet them", sourceKind = "collect", races = {"Dwarf", "Gnome", "NightElf", "Skyborne"}, uiMapID = 1436, x = 0.461, y = 0.382, coordFrame = "era", continentID = 0, worldX = -10291.333206, worldY = 1403.167, questID = 92742, objectiveIndex = 2, itemID = 254547, itemName = "Molsen Farm Water Sample", count = 1, questTitle = "Testing the Wells", kind = "complete", text = "Collect Molsen Farm Water Sample ×1 — Testing the Wells", detail = "From Molsen Farm Water Well.\n\nDefias Trappers and Smugglers camp in the fields between Sentinel Hill and Molsen Farm.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, Okra and sometimes a Precessive Autocognition Assembly. Foe Reaper 4000, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew.\n\nFill the vial at the farm's well", index = 86},
    {id = "b0024g10", blockID = 24, sourceBlock = 24, sourceGoal = 10, blockTitle = "Molsen Farm: kill these as you meet them", sourceKind = "collect", uiMapID = 1436, x = 0.4397, y = 0.3963, coordFrame = "era", continentID = 0, worldX = -10324.6998679, worldY = 1477.717, questID = 22, objectiveIndex = 1, itemID = 723, itemName = "Goretusk Liver", count = 8, questTitle = "Goretusk Liver Pie", kind = "complete", text = "Collect Goretusk Liver ×8 — Goretusk Liver Pie", detail = "Sources: Goretusk, Great Goretusk, Young Goretusk.\n\nDefias Trappers and Smugglers camp in the fields between Sentinel Hill and Molsen Farm.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, Okra and sometimes a Precessive Autocognition Assembly. Foe Reaper 4000, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew.", index = 87},
    {id = "b0024g11", blockID = 24, sourceBlock = 24, sourceGoal = 11, blockTitle = "Molsen Farm: kill these as you meet them", sourceKind = "collect", uiMapID = 1436, x = 0.4394, y = 0.4204, coordFrame = "era", continentID = 0, worldX = -10380.9331932, worldY = 1478.767, questID = 38, objectiveIndex = 1, itemID = 729, itemName = "Stringy Vulture Meat", count = 3, questTitle = "Westfall Stew", kind = "complete", text = "Collect Stringy Vulture Meat ×3 — Westfall Stew", detail = "Sources: Fleshripper, Greater Fleshripper, Vultros, Young Fleshripper.\n\nDefias Trappers and Smugglers camp in the fields between Sentinel Hill and Molsen Farm.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, Okra and sometimes a Precessive Autocognition Assembly. Foe Reaper 4000, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew.\n\nStringy Vulture Meat: Fleshrippers", index = 88},
    {id = "b0025g01", blockID = 25, sourceBlock = 25, sourceGoal = 1, blockTitle = "Furlbrow's Pumpkin Farm: kill these as you meet them", sourceKind = "collect", uiMapID = 1436, x = 0.447, y = 0.146, coordFrame = "era", continentID = 0, worldX = -9740.666618, worldY = 1452.167, questID = 102, objectiveIndex = 1, itemID = 725, itemName = "Gnoll Paw", count = 8, questTitle = "Patrolling Westfall", kind = "complete", text = "Collect Gnoll Paw ×8 — Patrolling Westfall", detail = "Sources: Riverpaw Gnoll, Riverpaw Scout, Riverpaw Shaman.\n\nRiverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above Jangolode Mine east to the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the Jansen Stead. Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both.\n\nGnoll Paws", index = 89},
    {id = "b0025g02", blockID = 25, sourceBlock = 25, sourceGoal = 2, blockTitle = "Furlbrow's Pumpkin Farm: kill these as you meet them", sourceKind = "collect", races = {"Dwarf", "Gnome", "NightElf", "Skyborne"}, uiMapID = 1436, x = 0.435, y = 0.092, coordFrame = "live", questID = 92744, objectiveIndex = 1, itemID = 254548, itemName = "Longshore Murloc Gill", count = 7, questTitle = "Murloc Gills", kind = "complete", text = "Collect Longshore Murloc Gill ×7 — Murloc Gills", detail = "Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above Jangolode Mine east to the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the Jansen Stead. Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both.\n\nLongshore Murloc Gills", index = 90},
    {id = "b0025g03", blockID = 25, sourceBlock = 25, sourceGoal = 3, blockTitle = "Furlbrow's Pumpkin Farm: kill these as you meet them", sourceKind = "collect", uiMapID = 1436, x = 0.435, y = 0.092, coordFrame = "era", continentID = 0, worldX = -9614.666636, worldY = 1494.167, questID = 38, objectiveIndex = 2, itemID = 730, itemName = "Murloc Eye", count = 3, questTitle = "Westfall Stew", kind = "complete", text = "Collect Murloc Eye ×3 — Westfall Stew", detail = "Sources: Murloc Minor Oracle, Murloc Coastrunner, Murloc Netter.\n\nRiverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above Jangolode Mine east to the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the Jansen Stead. Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both.", index = 91},
    {id = "b0025g04", blockID = 25, sourceBlock = 25, sourceGoal = 4, blockTitle = "Furlbrow's Pumpkin Farm: kill these as you meet them", sourceKind = "collect", uiMapID = 1436, x = 0.4933, y = 0.1928, coordFrame = "era", continentID = 0, worldX = -9849.8666024, worldY = 1290.117, questID = 64, objectiveIndex = 1, itemID = 841, itemName = "Furlbrow's Pocket Watch", count = 1, questTitle = "The Forgotten Heirloom", kind = "complete", text = "Collect Furlbrow's Pocket Watch ×1 — The Forgotten Heirloom", detail = "From Furlbrow's Wardrobe.\n\nRiverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above Jangolode Mine east to the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the Jansen Stead. Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both.\n\nFurlbrow's Wardrobe; inside", index = 92},
