    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Trial of the Lake", sourceKind = "turnin", races = {"NightElf"}, classes = {"DRUID"}, uiMapID = 1450, x = 0.5621, y = 0.3064, coordFrame = "era", continentID = 1, worldX = 8019.9377688, worldY = -2678.7639793, worldZ = 524.5, questID = 26, npcID = 11802, npcName = "Dendrite Starblaze", questTitle = "A Lesson to Learn", kind = "turnin", text = "Turn in: A Lesson to Learn", detail = "Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of Lake Elune'ara, below Nighthaven: take one to the Shrine of Remulos in the north-west, use it there and speak to Tajarri. Trial of the Lake runs on a timer: no teleport or Hearthstone until Tajarri has it. Then fly back to Auberdine from Nighthaven.\n\nTalk to Dendrite Starblaze.\n\nCast Teleport: Moonglade. Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of Lake Elune'ara, below Nighthaven: take one to the Shrine of Remulos in the north-west, use it there and speak to Tajarri. Then fly back to Auberdine from Nighthaven.", index = 81},
