    {id = "b0033g01", blockID = 33, sourceBlock = 33, sourceGoal = 1, blockTitle = "The northern Blackwood camp", sourceKind = "collect", uiMapID = 1439, x = 0.5183, y = 0.335, coordFrame = "era", continentID = 1, worldX = 6870.49989, worldY = -453.198, itemID = 12343, itemName = "Blackwood Nut Sample", kind = "note", manual = true, text = "Collect Blackwood Nut Sample ×1", detail = "The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the Filled Cleansing Bowl in your bags (the Empty Cleansing Bowl is filled at the Auberdine Moonwell), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the Talisman of Corruption lies in his Demon Bag.", index = 129},
    {id = "b0033g02", blockID = 33, sourceBlock = 33, sourceGoal = 2, blockTitle = "The northern Blackwood camp", sourceKind = "collect", uiMapID = 1439, x = 0.5286, y = 0.3342, coordFrame = "era", continentID = 1, worldX = 6873.9932228, worldY = -520.663, itemID = 12341, itemName = "Blackwood Fruit Sample", kind = "note", manual = true, text = "Collect Blackwood Fruit Sample ×1", detail = "The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the Filled Cleansing Bowl in your bags (the Empty Cleansing Bowl is filled at the Auberdine Moonwell), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the Talisman of Corruption lies in his Demon Bag.", index = 130},
