    {id = "b0033g04", blockID = 33, sourceBlock = 33, sourceGoal = 4, blockTitle = "The northern Blackwood camp", sourceKind = "use", uiMapID = 1439, x = 0.525, y = 0.334, coordFrame = "era", continentID = 1, worldX = 6874.866556, worldY = -497.083, questID = 4763, objectiveIndex = 1, itemID = 12347, itemName = "Filled Cleansing Bowl", questTitle = "The Blackwood Corrupted", kind = "complete", text = "Use Filled Cleansing Bowl — The Blackwood Corrupted", detail = "The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the Filled Cleansing Bowl in your bags (the Empty Cleansing Bowl is filled at the Auberdine Moonwell), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the Talisman of Corruption lies in his Demon Bag.\n\nBy the bonfire closest to the river: summons Xabraxxis", index = 132},
