    {id = "b0034g01", blockID = 34, sourceBlock = 34, sourceGoal = 1, blockTitle = "The cave and the Den Mother", sourceKind = "kill", uiMapID = 1439, x = 0.5148, y = 0.3826, coordFrame = "era", continentID = 1, worldX = 6662.6465884, worldY = -430.273, worldZ = 75.2, questID = 2139, objectiveIndex = 1, npcID = 6788, count = 1, questTitle = "Tharnariun's Hope", kind = "complete", text = "Kill Den Mother ×1 — Tharnariun's Hope", detail = "Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time.\n\nDen Mother, below ground", index = 134},
