    {id = "b0004g01", blockID = 4, sourceBlock = 4, sourceGoal = 1, blockTitle = "Lunar Fungus and Earthroot", sourceKind = "collect", races = {"NightElf"}, classes = {"DRUID"}, uiMapID = 1439, x = 0.4259, y = 0.7193, coordFrame = "era", continentID = 1, worldX = 5192.3901462, worldY = 152.022, questID = 6123, objectiveIndex = 1, itemID = 2449, itemName = "Earthroot", count = 5, questTitle = "Gathering the Cure", kind = "complete", text = "Collect Earthroot ×5 — Gathering the Cure", detail = "The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of Auberdine; the moonkin there are irritable. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else brings it from Stormwind (Maria Lumere) or the Auction House.", index = 9},
