    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "The loch", sourceKind = "accept", uiMapID = 1432, x = 0.4806, y = 0.397, coordFrame = "era", continentID = 0, worldX = -5217.814451, worldY = -3319.4048398, questID = 86614, objectID = 665289, objectName = "Discarded Fishing Toolbox", minLevel = 13, questTitle = "Silver of the Waves", kind = "accept", text = "Accept: Silver of the Waves", detail = "South along the west shore. The Discarded Fishing Toolbox lies on the loch bed at one of several places: east of Thelsamar (48.1,39.7), a little south-west of there (45.7,43.4), or at the south end of the loch (48.7,54.4 or 50.6,53.3). If it isn't at the arrow, try the next place. Click it for the quest; the Monogrammed Silver Hair Clip comes with it.\n\nInteract with Discarded Fishing Toolbox.\n\nSouth along the west shore. A Discarded Fishing Toolbox lies on the loch bed east of Thelsamar (it moves between several spots): open it for the Monogrammed Silver Hair Clip, which starts the quest.\n\nDiscarded Fishing Toolbox; underwater", index = 12},
    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Thelsamar", sourceKind = "turnin", uiMapID = 1432, x = 0.4028, y = 0.3928, coordFrame = "era", continentID = 0, worldX = -5210.0882024, worldY = -3104.8065324, worldZ = 303.2, questID = 86614, npcID = 1684, npcName = "Khara Deepwater", questTitle = "Silver of the Waves", kind = "turnin", text = "Turn in: Silver of the Waves", detail = "Talk to Khara Deepwater.\n\nKhara Deepwater stands on the shore north-east of town, Jern Hornhelm by the inn.", index = 13},
