    {id = "b0012g02", blockID = 12, sourceBlock = 12, sourceGoal = 2, blockTitle = "Ironband's Excavation", sourceKind = "accept", uiMapID = 1432, x = 0.649, y = 0.6666, coordFrame = "era", continentID = 0, worldX = -5713.7660278, worldY = -3783.908117, worldZ = 323, questID = 297, npcID = 1345, npcName = "Magmar Fellhew", minLevel = 13, questTitle = "Gathering Idols", kind = "accept", text = "Accept: Gathering Idols", detail = "Talk to Magmar Fellhew.\n\nRound the south end of the loch and head east to the dig. Magmar Fellhew and Prospector Ironband stand together at its west edge.", index = 16},
