    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "The dig site", sourceKind = "collect", uiMapID = 1432, x = 0.663, y = 0.667, coordFrame = "era", continentID = 0, worldX = -5714.501861, worldY = -3822.524779, itemID = 278049, itemName = "Excavation Tools", count = 1, kind = "note", manual = true, text = "Collect Excavation Tools ×1", detail = "Stonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a Carved Stone Idol. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start Excavation Tools, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health.\n\nExcavation Tools: open a pile at the dig", index = 18},
    {id = "b0013g02", blockID = 13, sourceBlock = 13, sourceGoal = 2, blockTitle = "The dig site", sourceKind = "accept", questID = 86613, itemID = 278049, itemName = "Excavation Tools", minLevel = 13, questTitle = "Excavation Tools", kind = "accept", text = "Accept: Excavation Tools", detail = "Use Excavation Tools to start this quest.\n\nStonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a Carved Stone Idol. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start Excavation Tools, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health.\n\nRight-click the Excavation Tools", index = 19},
