    {id = "b0035g01", blockID = 35, sourceBlock = 35, sourceGoal = 1, blockTitle = "Sunken Chest", sourceKind = "collect", uiMapID = 1433, x = 0.3643, y = 0.5466, coordFrame = "live", questID = 125, objectiveIndex = 1, itemID = 1309, itemName = "Oslow's Toolbox", count = 1, questTitle = "The Lost Tools", kind = "complete", text = "Collect Oslow's Toolbox ×1 — The Lost Tools", detail = "From Sunken Chest.\n\nBack toward town, swim east from the bridge into Lake Everstill; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a Spotted Sunfish.\n\nOslow's Toolbox; underwater", index = 74},
