    {id = "b0046g01", blockID = 46, sourceBlock = 46, sourceGoal = 1, blockTitle = "The Defias Messenger", sourceKind = "collect", uiMapID = 1436, x = 0.451, y = 0.6933, coordFrame = "era", continentID = 0, worldX = -11017.6997689, worldY = 1438.167, questID = 142, objectiveIndex = 1, itemID = 1381, itemName = "A Mysterious Message", count = 1, questTitle = "The Defias Brotherhood", kind = "complete", text = "Collect A Mysterious Message ×1 — The Defias Brotherhood", detail = "From Defias Messenger.\n\nSouth along the road to Moonbrook. The Defias Messenger starts in front of the Moonbrook smithy and walks north to the Gold Coast Quarry and the back of the Jangolode Mine, then back: look along his road. Slow him when he runs at 30% health.\n\nA Mysterious Message: the Defias Messenger", index = 101},
