    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Three Corners", sourceKind = "goto", uiMapID = 1433, x = 0.153, y = 0.715, coordFrame = "era", continentID = 0, worldX = -9610.25994, worldY = -1902.970602, kind = "goto", text = "Go to Three Corners", detail = "The road east through Elwynn crosses into Redridge at Three Corners, where the roads to Redridge, Duskwood and Elwynn meet: south to Duskwood first.", index = 17},
