    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Darkshire", sourceKind = "getfp", uiMapID = 1431, x = 0.7749, y = 0.4429, coordFrame = "era", continentID = 0, worldX = -10513.886, worldY = -1258.897, worldZ = 41.5, npcID = 2409, npcName = "Felicia Maline", location = "Darkshire", nodeID = 12, kind = "flight", mode = "learn", text = "Learn the flight path at Darkshire", manual = true, detail = "Follow the road south from Three Corners into Duskwood; Darkshire lies on the east side of the forest.\nNo Bronze Tube for Look to the Stars? Herble Baubbletump sells it in the house beside Viktori, in limited stock; Neal Allen in Menethil Harbor sells it too.\nViktori's house stands at the east end of town. Herble Baubbletump sells engineering goods in the house beside it.\n\nFelicia Maline, at the north end of town", index = 19},
