    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Tranquil Gardens Cemetery: kill these as you meet them", sourceKind = "collect", uiMapID = 1431, x = 0.7977, y = 0.6605, coordFrame = "era", continentID = 0, worldX = -10905.566, worldY = -1320.457, questID = 101, objectiveIndex = 3, itemID = 2378, itemName = "Skeleton Finger", count = 10, questTitle = "The Totem of Infliction", kind = "complete", text = "Collect Skeleton Finger ×10 — The Totem of Infliction", detail = "Sources: Skeletal Mage, Skeletal Warrior.\n\nSkeletal Warriors and Skeletal Mages walk among the graves south-east of Darkshire, below Blind Mary's house on the hill. Every skeleton in Duskwood can drop a Skeleton Finger.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once.", index = 33},
