    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "The Hushed Bank: kill these as you meet them", sourceKind = "kill", uiMapID = 1431, x = 0.1102, y = 0.3227, coordFrame = "era", continentID = 0, worldX = -10297.526, worldY = 535.793, worldZ = 41.9, questID = 226, objectiveIndex = 2, npcID = 565, count = 8, questTitle = "Wolves at Our Heels", kind = "complete", text = "Kill Rabid Dire Wolf ×8 — Wolves at Our Heels", detail = "Rabid Dire Wolves roam the woods around the cemetery and Abercrombie, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the Hushed Bank west of Raven Hill, fewer up north towards Sven's camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the Westfall border, so pull with care.", index = 43},
