    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Lake Everstill's murlocs: kill these as you meet them", sourceKind = "collect", uiMapID = 1433, x = 0.307, y = 0.5646, coordFrame = "live", questID = 150, objectiveIndex = 1, itemID = 1468, itemName = "Murloc Fin", count = 8, questTitle = "Murloc Poachers", kind = "complete", text = "Collect Murloc Fin ×8 — Murloc Poachers", detail = "Sources: Squiddic, Murloc Nightcrawler, Murloc Tidecaller, Murloc Scout, Murloc Flesheater.\n\nMurloc Flesheaters and Tidecallers line the south shore of Lake Everstill, just east of the gryphons and the bridge. Any of them can carry a fin.", index = 67},
