    {id = "b0031g01", blockID = 31, sourceBlock = 31, sourceGoal = 1, blockTitle = "Martie Jainrose", sourceKind = "turnin", uiMapID = 1433, x = 0.1677, y = 0.4633, coordFrame = "live", worldZ = 77.2, questID = 34, npcID = 342, npcName = "Martie Jainrose", questTitle = "An Unwelcome Guest", kind = "turnin", text = "Turn in: An Unwelcome Guest", detail = "Talk to Martie Jainrose.\n\nMartie's garden is at the west end of town.", index = 74},
    {id = "b0032g01", blockID = 32, sourceBlock = 32, sourceGoal = 1, blockTitle = "Lakeshire", sourceKind = "accept", uiMapID = 1433, x = 0.2453, y = 0.4616, coordFrame = "live", worldZ = 67.6, questID = 169, objectID = 60, objectName = "Wanted: Gath'Ilzogg", minLevel = 15, optional = true, questTitle = "WANTED: Gath'Ilzogg", kind = "accept", text = "Accept: WANTED: Gath'Ilzogg", detail = "Interact with Wanted: Gath'Ilzogg.\n\nBack east through town from Martie's garden: two Wanted posters hang on the town hall doorway.\n\nThe Wanted poster on the town hall doorway", index = 75},
    {id = "b0032g02", blockID = 32, sourceBlock = 32, sourceGoal = 2, blockTitle = "Lakeshire", sourceKind = "accept", uiMapID = 1433, x = 0.2429, y = 0.4618, coordFrame = "live", questID = 95999, objectID = 649051, objectName = "Wanted: Incinerator Gar'im", minLevel = 16, optional = true, questTitle = "WANTED: Incinerator Gar'im", kind = "accept", text = "Accept: WANTED: Incinerator Gar'im", detail = "Interact with Wanted: Incinerator Gar'im.\n\nBack east through town from Martie's garden: two Wanted posters hang on the town hall doorway.\n\nThe Wanted poster beside it", index = 76},
    {id = "b0032g03", blockID = 32, sourceBlock = 32, sourceGoal = 3, blockTitle = "Lakeshire", sourceKind = "vendor", optional = true, kind = "vendor", mode = "supplies", text = "Sell unwanted items, repair and restock", manual = true, detail = "Back east through town from Martie's garden: two Wanted posters hang on the town hall doorway.", index = 77},
    {id = "b0033g01", blockID = 33, sourceBlock = 33, sourceGoal = 1, blockTitle = "Lake Everstill: kill these as you meet them", sourceKind = "kill", uiMapID = 1433, x = 0.4274, y = 0.3846, coordFrame = "live", worldZ = 115, questID = 98386, objectiveIndex = 1, npcID = 505, count = 12, questTitle = "Alther's Mill", kind = "complete", text = "Kill Greater Tarantula ×12 — Alther's Mill", detail = "Greater Tarantulas crawl on the slopes around the mill north-east of the lake.", index = 78},
    {id = "b0034g01", blockID = 34, sourceBlock = 34, sourceGoal = 1, blockTitle = "Blackrock camps", sourceKind = "collect", uiMapID = 1433, x = 0.71, y = 0.705, coordFrame = "live", questID = 20, objectiveIndex = 1, itemID = 3014, itemName = "Battleworn Axe", count = 10, questTitle = "Blackrock Menace", kind = "complete", text = "Collect Battleworn Axe ×10 — Blackrock Menace", detail = "Sources: Blackrock Renegade, Blackrock Outrunner, Blackrock Grunt, Blackrock Summoner.\n\nSouth-east from the mill, west of Galardell Valley's gnolls, to the Blackrock camps east of Stonewatch Keep. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies.", index = 79},
    {id = "b0034g02", blockID = 34, sourceBlock = 34, sourceGoal = 2, blockTitle = "Blackrock camps", sourceKind = "collect", uiMapID = 1433, x = 0.683, y = 0.794, coordFrame = "live", questID = 98387, objectiveIndex = 1, itemID = 280841, itemName = "Stolen Weapon", count = 8, questTitle = "Blackrock Blockade", kind = "complete", text = "Collect Stolen Weapon ×8 — Blackrock Blockade", detail = "From Weapon Rack.\n\nSouth-east from the mill, west of Galardell Valley's gnolls, to the Blackrock camps east of Stonewatch Keep. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies.\n\nStolen Weapon: weapon racks and swords on the ground", index = 80},
    {id = "b0034g03", blockID = 34, sourceBlock = 34, sourceGoal = 3, blockTitle = "Blackrock camps", sourceKind = "collect", uiMapID = 1433, x = 0.674, y = 0.789, coordFrame = "live", questID = 98387, objectiveIndex = 2, itemID = 280839, itemName = "Blackrock Supplies", count = 10, questTitle = "Blackrock Blockade", kind = "complete", text = "Collect Blackrock Supplies ×10 — Blackrock Blockade", detail = "From Blackrock Supplies.\n\nSouth-east from the mill, west of Galardell Valley's gnolls, to the Blackrock camps east of Stonewatch Keep. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies.\n\nBlackrock Supplies: meat haunches, grain sacks, water barrels", index = 81},
    {id = "b0035g01", blockID = 35, sourceBlock = 35, sourceGoal = 1, blockTitle = "Incinerator Gar'im", sourceKind = "collect", uiMapID = 1433, x = 0.7282, y = 0.8633, coordFrame = "live", questID = 95999, objectiveIndex = 1, itemID = 271872, itemName = "Broken Staff of Incinerator Gar'im", count = 1, optional = true, group = {kind = "elite", rank = 1}, questTitle = "WANTED: Incinerator Gar'im", kind = "complete", text = "Collect Broken Staff of Incinerator Gar'im ×1 — WANTED: Incinerator Gar'im", detail = "East past the mill, then south-east to the Blackrock camps east of Stonewatch Keep: Gar'im keeps to the cave at their south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast. He drops a Midnight Orb too.\n\nFrom Incinerator Gar'im.\n\nGar'im keeps to the cave at the camps' south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast.", index = 82},
    {id = "b0036g01", blockID = 36, sourceBlock = 36, sourceGoal = 1, blockTitle = "Galardell Valley", sourceKind = "collect", uiMapID = 1433, x = 0.7771, y = 0.5927, coordFrame = "live", questID = 91, objectiveIndex = 1, itemID = 1075, itemName = "Shadowhide Pendant", count = 10, questTitle = "Solomon's Law", kind = "complete", text = "Collect Shadowhide Pendant ×10 — Solomon's Law", detail = "Sources: Shadowhide Slayer, Shadowhide Darkweaver, Shadowhide Brute, Shadowhide Gnoll, Rabid Shadowhide Gnoll.\n\nNorth up the valley's east side. Shadowhide gnolls fill it; Lieutenant Fangore (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of Stonewatch Keep to the west until the watch tower: its orcs are elite.\n\nShadowhide Pendant: any Shadowhide gnoll", index = 83},
    {id = "b0036g02", blockID = 36, sourceBlock = 36, sourceGoal = 2, blockTitle = "Galardell Valley", sourceKind = "collect", uiMapID = 1433, x = 0.7509, y = 0.3706, coordFrame = "live", questID = 180, objectiveIndex = 1, itemID = 3632, itemName = "Fangore's Paw", count = 1, questTitle = "WANTED: Lieutenant Fangore", kind = "complete", text = "Collect Fangore's Paw ×1 — WANTED: Lieutenant Fangore", detail = "North-east to the gnolls' eastern camp in Galardell Valley. Fangore has two guards linked to him: clear the gnolls around him first and fight at full health.\n\nFrom Lieutenant Fangore.\n\nNorth up the valley's east side. Shadowhide gnolls fill it; Lieutenant Fangore (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of Stonewatch Keep to the west until the watch tower: its orcs are elite.", index = 84},
    {id = "b0037g01", blockID = 37, sourceBlock = 37, sourceGoal = 1, blockTitle = "A Watchful Eye", sourceKind = "turnin", uiMapID = 1433, x = 0.794, y = 0.4683, coordFrame = "live", worldZ = 104.3, questID = 94, objectID = 31, objectName = "Old Lion Statue", questTitle = "A Watchful Eye", kind = "turnin", text = "Turn in: A Watchful Eye", detail = "Interact with Old Lion Statue.\n\nThe Old Lion Statue stands at the valley's east edge.", index = 85},
    {id = "b0037g02", blockID = 37, sourceBlock = 37, sourceGoal = 2, blockTitle = "A Watchful Eye", sourceKind = "accept", uiMapID = 1433, x = 0.794, y = 0.4683, coordFrame = "live", worldZ = 104.3, questID = 248, objectID = 31, objectName = "Old Lion Statue", minLevel = 20, requiresAny = {94}, prerequisiteTitles = {["94"] = "A Watchful Eye"}, questTitle = "Looking Further", kind = "accept", text = "Accept: Looking Further", detail = "Interact with Old Lion Statue.\n\nThe Old Lion Statue stands at the valley's east edge.", index = 86},
    {id = "b0038g01", blockID = 38, sourceBlock = 38, sourceGoal = 1, blockTitle = "Looking Further", sourceKind = "turnin", uiMapID = 1433, x = 0.5816, y = 0.4984, coordFrame = "live", worldZ = 164.8, questID = 248, objectID = 76, objectName = "An Empty Jar", questTitle = "Looking Further", kind = "turnin", text = "Turn in: Looking Further", detail = "Interact with An Empty Jar.\n\nWest to the intact watch tower beside Stonewatch Keep: climb it and leave the Glyph in the empty jar at the top.", index = 87},
    {id = "b0039g01", blockID = 39, sourceBlock = 39, sourceGoal = 1, blockTitle = "Stonewatch Keep", sourceKind = "collect", uiMapID = 1433, x = 0.6452, y = 0.5579, coordFrame = "live", questID = 169, objectiveIndex = 1, itemID = 3633, itemName = "Head of Gath'Ilzogg", count = 1, optional = true, group = {kind = "elite", rank = 1}, questTitle = "WANTED: Gath'Ilzogg", kind = "complete", text = "Collect Head of Gath'Ilzogg ×1 — WANTED: Gath'Ilzogg", detail = "From Gath'Ilzogg.\n\nThe keep stands beside the tower. Gath'Ilzogg (elite) waits in the keep's top room with two guards and a dragon; Blackrock Shadowcasters (elite) and Sentries stand on its west side, so pull one at a time on the way in, and hug the right wall as you enter his room so you don't pull him at once. Elite: group up if you can.", index = 88},
    {id = "b0040g01", blockID = 40, sourceBlock = 40, sourceGoal = 1, blockTitle = "Render's Valley", sourceKind = "kill", uiMapID = 1433, x = 0.3061, y = 0.0765, coordFrame = "live", worldZ = 157, questID = 128, objectiveIndex = 1, npcID = 435, count = 15, questTitle = "Blackrock Bounty", kind = "complete", text = "Kill Blackrock Champion ×15 — Blackrock Bounty", detail = "From the keep head back west along the lake's north shore and north up the Redridge Canyons to Render's Valley; Lakeshire's hand-ins wait for Keeshan's escort, which ends there. Blackrock Champions camp in the valley.\n\nBlackrock Champion, below ground", index = 89},
    {id = "b0041g01", blockID = 41, sourceBlock = 41, sourceGoal = 1, blockTitle = "Corporal Keeshan", sourceKind = "accept", uiMapID = 1433, x = 0.233, y = 0.1255, coordFrame = "live", worldZ = 140, questID = 219, npcID = 349, npcName = "Corporal Keeshan", minLevel = 19, escort = true, questTitle = "Missing In Action", kind = "accept", text = "Accept: Missing In Action", detail = "Talk to Corporal Keeshan.\n\nKeeshan hides at the very north end of the valley, by the Burning Steppes border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way.\n\nCorporal Keeshan, below ground", index = 90},
    {id = "b0041g02", blockID = 41, sourceBlock = 41, sourceGoal = 2, blockTitle = "Corporal Keeshan", sourceKind = "complete", questID = 219, escort = true, questTitle = "Missing In Action", kind = "complete", text = "Complete: Missing In Action", detail = "Escort Corporal Keeshan back to Redridge.\n\nKeeshan hides at the very north end of the valley, by the Burning Steppes border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way.", index = 91, objectiveTargets = {{kind = "complete", questID = 219, questTitle = "Missing In Action", objectiveIndex = 1, blockTitle = "Corporal Keeshan", sourceKind = "event", text = "Complete: Missing In Action", uiMapID = 1433, x = 0.28300000000000003, y = 0.48700000000000004, coordFrame = "live", navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
    {id = "b0042g01", blockID = 42, sourceBlock = 42, sourceGoal = 1, blockTitle = "Back to Lakeshire", sourceKind = "turnin", uiMapID = 1433, x = 0.2463, y = 0.4426, coordFrame = "live", worldZ = 66.5, questID = 91, npcID = 900, npcName = "Bailiff Conacher", questTitle = "Solomon's Law", kind = "turnin", text = "Turn in: Solomon's Law", detail = "Talk to Bailiff Conacher.\n\nInto Lakeshire from the north with Keeshan: Bailiff Conacher and Magistrate Solomon in the town hall, Marshal Marris and Foreman Oslow at the north end of the bridge, then over the bridge to Guard Howe and the gryphons.\n\nBailiff Conacher, in the town hall", index = 92},
    {id = "b0042g02", blockID = 42, sourceBlock = 42, sourceGoal = 2, blockTitle = "Back to Lakeshire", sourceKind = "turnin", uiMapID = 1433, x = 0.249, y = 0.4445, coordFrame = "live", worldZ = 67.6, questID = 180, npcID = 344, npcName = "Magistrate Solomon", questTitle = "WANTED: Lieutenant Fangore", kind = "turnin", text = "Turn in: WANTED: Lieutenant Fangore", detail = "Talk to Magistrate Solomon.\n\nInto Lakeshire from the north with Keeshan: Bailiff Conacher and Magistrate Solomon in the town hall, Marshal Marris and Foreman Oslow at the north end of the bridge, then over the bridge to Guard Howe and the gryphons.\n\nMagistrate Solomon, in the town hall", index = 93},
