    {id = "b0042g05", blockID = 42, sourceBlock = 42, sourceGoal = 5, blockTitle = "Back to Lakeshire", sourceKind = "turnin", uiMapID = 1433, x = 0.2841, y = 0.4897, coordFrame = "live", worldZ = 67.6, questID = 219, npcID = 382, npcName = "Marshal Marris", questTitle = "Missing In Action", kind = "turnin", text = "Turn in: Missing In Action", detail = "Talk to Marshal Marris.\n\nInto Lakeshire from the north with Keeshan: Bailiff Conacher and Magistrate Solomon in the town hall, Marshal Marris and Foreman Oslow at the north end of the bridge, then over the bridge to Guard Howe and the gryphons.", index = 96, objectiveTargets = {{kind = "complete", questID = 219, questTitle = "Missing In Action", objectiveIndex = 1, blockTitle = "Corporal Keeshan", sourceKind = "event", text = "Complete: Missing In Action", uiMapID = 1433, x = 0.28300000000000003, y = 0.48700000000000004, coordFrame = "live", navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
