    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Stonetalon Mountains", sourceKind = "goto", uiMapID = 1442, x = 0.719, y = 0.6, coordFrame = "era", continentID = 1, worldX = 962.917, worldY = -265.283427, kind = "goto", text = "Go to Stonetalon Mountains", detail = "Head south past Mystral Lake into the Talondeep Path tunnel; it comes out in Stonetalon's Windshear Crag, by the Windshear Mine.", index = 37},
    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Piznik", sourceKind = "accept", uiMapID = 1442, x = 0.7187, y = 0.6, coordFrame = "era", continentID = 1, worldX = 962.917, worldY = -263.8184271, worldZ = -5.3, questID = 1090, npcID = 4276, npcName = "Piznik", minLevel = 17, questTitle = "Gerenzo's Orders", kind = "accept", text = "Accept: Gerenzo's Orders", detail = "Piznik's defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone. Piznik mines at the bottom of the Windshear Mine, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.\n\nTalk to Piznik.\n\nPiznik mines in the Windshear Mine at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended.\n\nBelow ground", index = 38},
