    {id = "b0033g01", blockID = 33, sourceBlock = 33, sourceGoal = 1, blockTitle = "Auberdine", sourceKind = "turnin", uiMapID = 1439, x = 0.374, y = 0.4013, coordFrame = "era", continentID = 1, worldX = 6580.9899342, worldY = 491.967, worldZ = 8.3, questID = 97926, npcID = 3649, npcName = "Thundris Windweaver", optional = true, questTitle = "Making Do", kind = "turnin", text = "Turn in: Making Do", detail = "Talk to Thundris Windweaver.\n\nThundris Windweaver stands at the north end of Auberdine, Terenthis and Sentinel Selarin by the flight master.\n\nThundris Windweaver: Alexston's reply, if you took it in Stormwind", index = 86},
