    {id = "b0033g03", blockID = 33, sourceBlock = 33, sourceGoal = 3, blockTitle = "Auberdine", sourceKind = "accept", uiMapID = 1439, x = 0.3928, y = 0.4346, coordFrame = "era", continentID = 1, worldX = 6435.5799564, worldY = 368.827, questID = 990, npcID = 3694, npcName = "Sentinel Selarin", minLevel = 15, requiresAny = {}, prerequisiteTitles = {["994"] = "Escape Through Force", ["995"] = "Escape Through Stealth"}, questTitle = "Trek to Ashenvale", kind = "accept", text = "Accept: Trek to Ashenvale", detail = "From the dock, up to the north end of the village first (Thundris Windweaver, Alanndarian Nightsong by the moonwell, Archaeologist Hollee), then down the main street: the WANTED poster outside the inn, Terenthis at its east end, where the road leaves south. Sentinel Selarin stands beside Terenthis by the flight master; if she isn't there, she has been killed and respawns shortly: wait a moment.\n\nTalk to Sentinel Selarin.\n\nThundris Windweaver stands at the north end of Auberdine, Terenthis and Sentinel Selarin by the flight master.\n\nSentinel Selarin: for Raene Wolfrunner in Astranaar", index = 88},
