    {id = "b0045g01", blockID = 45, sourceBlock = 45, sourceGoal = 1, blockTitle = "The Dor'Danil Barrow Den: kill these as you meet them", sourceKind = "collect", uiMapID = 1440, x = 0.7826, y = 0.6458, coordFrame = "era", continentID = 1, worldX = 2190.62325, worldY = -2812.9935942, questID = 1027, objectiveIndex = 1, itemID = 5519, itemName = "Iron Pommel", count = 1, questTitle = "Raene's Cleansing", kind = "complete", text = "Collect Iron Pommel ×1 — Raene's Cleansing", detail = "From Rusty Chest.\n\nThe Forsaken's camp lies in the woods south of Forest Song.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together.", index = 108},
    {id = "b0045g02", blockID = 45, sourceBlock = 45, sourceGoal = 2, blockTitle = "The Dor'Danil Barrow Den: kill these as you meet them", sourceKind = "collect", uiMapID = 1440, x = 0.7527, y = 0.718, coordFrame = "era", continentID = 1, worldX = 1913.1045, worldY = -2640.5702509, questID = 1011, objectiveIndex = 1, itemID = 5440, itemName = "Bottle of Disease", count = 1, questTitle = "Forsaken Diseases", kind = "complete", text = "Collect Bottle of Disease ×1 — Forsaken Diseases", detail = "From Bottle of Disease.\n\nThe Forsaken's camp lies in the woods south of Forest Song.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together.", index = 109},
    {id = "b0046g01", blockID = 46, sourceBlock = 46, sourceGoal = 1, blockTitle = "Fallen Sky Lake", sourceKind = "collect", uiMapID = 1440, x = 0.6666, y = 0.8217, coordFrame = "era", continentID = 1, worldX = 1514.507625, worldY = -2144.0602222, questID = 1035, objectiveIndex = 1, itemID = 5508, itemName = "Fallen Moonstone", count = 1, questTitle = "Fallen Sky Lake", kind = "complete", text = "Collect Fallen Moonstone ×1 — Fallen Sky Lake", detail = "From Shadethicket Oracle.\n\nThe Shadethicket Oracle walks the shore of Fallen Sky Lake, south-west of the chests; the Gleaming Crescent Pendant lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle.", index = 110},
    {id = "b0046g02", blockID = 46, sourceBlock = 46, sourceGoal = 2, blockTitle = "Fallen Sky Lake", sourceKind = "accept", uiMapID = 1440, x = 0.6299, y = 0.7154, coordFrame = "era", continentID = 1, worldX = 1923.09825, worldY = -1932.4235433, questID = 98027, objectID = 669176, objectName = "Gleaming Crescent Pendant", minLevel = 22, questTitle = "Gleaming Crescent Necklace", kind = "accept", text = "Accept: Gleaming Crescent Necklace", detail = "Interact with Gleaming Crescent Pendant.\n\nThe Shadethicket Oracle walks the shore of Fallen Sky Lake, south-west of the chests; the Gleaming Crescent Pendant lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle.\n\nGleaming Crescent Pendant: for Maliynn in Astranaar", index = 111},
    {id = "b0047g01", blockID = 47, sourceBlock = 47, sourceGoal = 1, blockTitle = "Kayneth Stillwind", sourceKind = "turnin", uiMapID = 1440, x = 0.8524, y = 0.4471, coordFrame = "era", continentID = 1, worldX = 2954.376375, worldY = -3215.5069508, worldZ = 169.2, questID = 1011, npcID = 3848, npcName = "Kayneth Stillwind", questTitle = "Forsaken Diseases", kind = "turnin", text = "Turn in: Forsaken Diseases", detail = "Talk to Kayneth Stillwind.", index = 112},
    {id = "b0047g02", blockID = 47, sourceBlock = 47, sourceGoal = 2, blockTitle = "Kayneth Stillwind", sourceKind = "accept", uiMapID = 1440, x = 0.8524, y = 0.4471, coordFrame = "era", continentID = 1, worldX = 2954.376375, worldY = -3215.5069508, worldZ = 169.2, questID = 1012, npcID = 3848, npcName = "Kayneth Stillwind", minLevel = 24, requiresAny = {1011}, prerequisiteTitles = {["1011"] = "Forsaken Diseases"}, questTitle = "Insane Druids", kind = "accept", text = "Accept: Insane Druids", detail = "Talk to Kayneth Stillwind.", index = 113},
    {id = "b0048g01", blockID = 48, sourceBlock = 48, sourceGoal = 1, blockTitle = "Insane druids", sourceKind = "kill", uiMapID = 1440, x = 0.7718, y = 0.7399, coordFrame = "era", continentID = 1, worldX = 1828.926375, worldY = -2750.7135906, worldZ = 83.1, questID = 1012, objectiveIndex = 1, npcID = 3940, count = 1, questTitle = "Insane Druids", kind = "complete", text = "Kill Taneel Darkwood ×1 — Insane Druids", detail = "The three druids are inside The Dor'Danil Barrow Den, apart from each other: go in at its mouth, south of the Forsaken camp, not over the hill above them. Taneel Darkwood is in the eastern halls, Uthil Mooncall deepest down at the north-east end and Mavoris Cloudsbreak at the western end.\n\nThe three druids stand together at the Forsaken camp south of Forest Song.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight.\n\nTaneel Darkwood, inside The Dor'Danil Barrow Den", index = 114},
