    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Raven Hill Cemetery: kill these as you meet them", sourceKind = "kill", uiMapID = 1431, x = 0.2631, y = 0.342, coordFrame = "era", continentID = 0, worldX = -10332.266, worldY = 122.963, worldZ = 3, questID = 58, objectiveIndex = 1, npcID = 604, count = 20, questTitle = "The Night Watch", kind = "complete", text = "Kill Plague Spreader ×20 — The Night Watch", detail = "The Plague Spreaders walk the northern half of the Raven Hill Cemetery. Mor'Ladim, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of Sven's camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs.", index = 30},
