D.routes["forever/alliance/30-40/01-hillsbrad-foothills"] = {id = "forever/alliance/30-40/01-hillsbrad-foothills", title = "Wetlands & Hillsbrad Foothills", faction = "Alliance", startLevel = 30, endLevel = 32, zone = 1437, zoneName = "Wetlands", source = "Polestar", sourceCommit = "e978e136279cf075eff34718f3ad5fd3dacba623", next = "forever/alliance/30-40/03-ashenvale", stepCount = 116, steps = {
    {id = "b0001g01", blockID = 1, sourceBlock = 1, sourceGoal = 1, blockTitle = "To Deepwater Tavern", sourceKind = "goto", uiMapID = 1437, x = 0.107, y = 0.61, coordFrame = "era", continentID = 0, worldX = -3829.2295, worldY = -832.072619, kind = "goto", text = "Go to Deepwater Tavern", index = 1},
    {id = "b0002g01", blockID = 2, sourceBlock = 2, sourceGoal = 1, blockTitle = "Angerfang Encampment", sourceKind = "turnin", uiMapID = 1437, x = 0.4745, y = 0.4702, coordFrame = "era", continentID = 0, worldX = -3443.90575, worldY = -2351.8383665, questID = 465, objectID = 630696, objectName = "Dragonmaw Catapult", questTitle = "Nek'rosh's Gambit", kind = "turnin", text = "Turn in: Nek'rosh's Gambit", detail = "Interact with Dragonmaw Catapult.\n\nSouth-east from Menethil to the Dragonmaw's Angerfang Encampment: the first catapult stands on the way, and the Tattered Spellbook lies in the camp.", index = 2},
    {id = "b0003g01", blockID = 3, sourceBlock = 3, sourceGoal = 1, blockTitle = "Angerfang Encampment", sourceKind = "accept", uiMapID = 1437, x = 0.4745, y = 0.4702, coordFrame = "era", continentID = 0, worldX = -3443.90575, worldY = -2351.8383665, conditions = {{k = "group", q = 474}}, questID = 474, objectID = 630696, objectName = "Dragonmaw Catapult", minLevel = 23, requiresAny = {465}, prerequisiteTitles = {["465"] = "Nek'rosh's Gambit"}, questTitle = "Defeat Nek'rosh", kind = "accept", text = "Accept: Defeat Nek'rosh", detail = "Interact with Dragonmaw Catapult.", index = 3},
    {id = "b0004g01", blockID = 4, sourceBlock = 4, sourceGoal = 1, blockTitle = "Angerfang Encampment", sourceKind = "note", kind = "note", manual = true, text = "The next step, Defeat Nek'rosh, pits you against an elite chieftain: skip it.", index = 4},
    {id = "b0004g02", blockID = 4, sourceBlock = 4, sourceGoal = 2, blockTitle = "Angerfang Encampment", sourceKind = "accept", uiMapID = 1437, x = 0.5348, y = 0.5453, coordFrame = "era", continentID = 0, worldX = -3650.900125, worldY = -2601.2040116, questID = 98223, objectID = 671518, objectName = "Tattered Spellbook", minLevel = 23, questTitle = "Old Habits", kind = "accept", text = "Accept: Old Habits", detail = "Interact with Tattered Spellbook.\n\nTattered Spellbook: for Captain Stoutfist", index = 5},
    {id = "b0005g01", blockID = 5, sourceBlock = 5, sourceGoal = 1, blockTitle = "Defeat Nek'rosh", sourceKind = "collect", uiMapID = 1437, x = 0.535, y = 0.547, coordFrame = "era", continentID = 0, worldX = -3655.58575, worldY = -2602.031095, conditions = {{k = "group", q = 474}}, questID = 474, objectiveIndex = 1, itemID = 3625, itemName = "Nek'rosh's Head", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Defeat Nek'rosh", kind = "complete", text = "Collect Nek'rosh's Head ×1 — Defeat Nek'rosh", detail = "From Chieftain Nek'rosh.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Chieftain Nek'rosh is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents.", index = 6},
    {id = "b0006g01", blockID = 6, sourceBlock = 6, sourceGoal = 1, blockTitle = "Golm", sourceKind = "collect", uiMapID = 1437, x = 0.6446, y = 0.6275, coordFrame = "era", continentID = 0, worldX = -3877.463875, worldY = -3055.2727982, conditions = {{k = "group", q = 98310}}, questID = 98310, objectiveIndex = 3, itemID = 280397, itemName = "Heart of Golm", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Gleaning Our Future", kind = "complete", text = "Collect Heart of Golm ×1 — Gleaning Our Future", detail = "From Golm.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Golm, Ados, Neru and Modr are level 32 elites, each called up by using the Goaz Stone beside it. Skip them if you are alone. Golm stands in the south-eastern hills.", index = 7},
    {id = "b0007g01", blockID = 7, sourceBlock = 7, sourceGoal = 1, blockTitle = "Ados", sourceKind = "collect", uiMapID = 1437, x = 0.751, y = 0.4825, coordFrame = "era", continentID = 0, worldX = -3477.807625, worldY = -3495.281167, conditions = {{k = "group", q = 98310}}, questID = 98310, objectiveIndex = 1, itemID = 280395, itemName = "Heart of Ados", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Gleaning Our Future", kind = "complete", text = "Collect Heart of Ados ×1 — Gleaning Our Future", detail = "From Ados.\n\nNorth-east to the Dragonmaw Gates: Ados stands at the gates (use the Goaz Stone).", index = 8},
    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Dragonmaw Gates: kill these as you meet them", sourceKind = "collect", uiMapID = 1437, x = 0.716, y = 0.4743, coordFrame = "era", continentID = 0, worldX = -3455.206375, worldY = -3350.541572, questID = 98072, objectiveIndex = 1, itemID = 279385, itemName = "Pristine Crimson Scale", count = 8, questTitle = "Crocs of the Sky", kind = "complete", text = "Collect Pristine Crimson Scale ×8 — Crocs of the Sky", detail = "Sources: Flamesnorting Whelp, Red Whelp, Lost Whelp, Crimson Whelp.\n\nThe whelps nest in the hills north-east of the Angerfang Encampment; Carnage prowls further north, and the Razormaw raptors hunt the highlands on the way north to Dun Modr.\nCarnage is elite: grouping up is advised.", index = 9},
    {id = "b0008g02", blockID = 8, sourceBlock = 8, sourceGoal = 2, blockTitle = "Dragonmaw Gates: kill these as you meet them", sourceKind = "collect", uiMapID = 1437, x = 0.6955, y = 0.3032, coordFrame = "era", continentID = 0, worldX = -2983.612, worldY = -3265.7655235, questID = 98283, objectiveIndex = 2, itemID = 280330, itemName = "Carnage's Head", count = 1, optional = true, group = {kind = "elite", rank = 1}, questTitle = "Carnage", kind = "complete", text = "Collect Carnage's Head ×1 — Carnage", detail = "From Carnage.\n\nThe whelps nest in the hills north-east of the Angerfang Encampment; Carnage prowls further north, and the Razormaw raptors hunt the highlands on the way north to Dun Modr.\nCarnage is elite: grouping up is advised.", index = 10},
    {id = "b0008g03", blockID = 8, sourceBlock = 8, sourceGoal = 3, blockTitle = "Dragonmaw Gates: kill these as you meet them", sourceKind = "collect", uiMapID = 1437, x = 0.6968, y = 0.3037, coordFrame = "era", continentID = 0, worldX = -2984.990125, worldY = -3271.1415656, questID = 98245, objectiveIndex = 1, itemID = 280103, itemName = "Razormaw Incisor", count = 10, questTitle = "Razormaw Needling", kind = "complete", text = "Collect Razormaw Incisor ×10 — Razormaw Needling", detail = "Sources: Highland Razormaw, Elder Razormaw.\n\nThe whelps nest in the hills north-east of the Angerfang Encampment; Carnage prowls further north, and the Razormaw raptors hunt the highlands on the way north to Dun Modr.\nCarnage is elite: grouping up is advised.", index = 11},
    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "Neru", sourceKind = "collect", uiMapID = 1437, x = 0.6046, y = 0.2669, coordFrame = "era", continentID = 0, worldX = -2883.560125, worldY = -2889.8561182, conditions = {{k = "group", q = 98310}}, questID = 98310, objectiveIndex = 4, itemID = 280398, itemName = "Heart of Neru", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Gleaning Our Future", kind = "complete", text = "Collect Heart of Neru ×1 — Gleaning Our Future", detail = "From Neru.\n\nNeru stands in the hills between the Dragonmaw Gates and Dun Modr (use the Goaz Stone).", index = 12},
    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "The Green Belt", sourceKind = "collect", uiMapID = 1437, x = 0.5984, y = 0.2664, coordFrame = "era", continentID = 0, worldX = -2882.182, worldY = -2864.2165328, conditions = {{k = "onquest", q = {98283}}}, questID = 98283, objectiveIndex = 1, itemID = 280331, itemName = "Malignant Rotclaw Flesh", count = 1, optional = true, questTitle = "Carnage", kind = "complete", text = "Collect Malignant Rotclaw Flesh ×1 — Carnage", detail = "From Maddened Rotclaw.\n\nMaddened Rotclaws roam the Green Belt around Rethiel.", index = 13},
    {id = "b0010g02", blockID = 10, sourceBlock = 10, sourceGoal = 2, blockTitle = "The Green Belt", sourceKind = "turnin", uiMapID = 1437, x = 0.5637, y = 0.404, coordFrame = "era", continentID = 0, worldX = -3261.442, worldY = -2720.7175629, worldZ = 9.5, conditions = {{k = "onquest", q = {98283}}}, questID = 98283, npcID = 1244, npcName = "Rethiel the Greenwarden", optional = true, questTitle = "Carnage", kind = "turnin", text = "Turn in: Carnage", detail = "Talk to Rethiel the Greenwarden.\n\nMaddened Rotclaws roam the Green Belt around Rethiel.", index = 14},
    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Dun Modr", sourceKind = "turnin", uiMapID = 1437, x = 0.498, y = 0.1826, coordFrame = "era", continentID = 0, worldX = -2651.20825, worldY = -2449.020666, worldZ = 80.1, questID = 472, npcID = 1071, npcName = "Longbraid the Grim", questTitle = "Fall of Dun Modr", kind = "turnin", text = "Turn in: Fall of Dun Modr", detail = "Talk to Longbraid the Grim.\n\nNorth along the road to Dun Modr. Longbraid the Grim, Rhag Garmason and Roggo Harlbarrow stand together in the dwarves' camp; the Captive Fire Elemental is held on the west side: lead it out to Roggo.", index = 15},
    {id = "b0011g02", blockID = 11, sourceBlock = 11, sourceGoal = 2, blockTitle = "Dun Modr", sourceKind = "accept", uiMapID = 1437, x = 0.499, y = 0.1824, coordFrame = "era", continentID = 0, worldX = -2650.657, worldY = -2453.156083, worldZ = 80.2, questID = 631, npcID = 1075, npcName = "Rhag Garmason", minLevel = 26, questTitle = "The Thandol Span", kind = "accept", text = "Accept: The Thandol Span", detail = "Talk to Rhag Garmason.\n\nNorth along the road to Dun Modr. Longbraid the Grim, Rhag Garmason and Roggo Harlbarrow stand together in the dwarves' camp; the Captive Fire Elemental is held on the west side: lead it out to Roggo.", index = 16},
    {id = "b0011g03", blockID = 11, sourceBlock = 11, sourceGoal = 3, blockTitle = "Dun Modr", sourceKind = "accept", uiMapID = 1437, x = 0.4567, y = 0.1666, coordFrame = "era", continentID = 0, worldX = -2607.10825, worldY = -2278.2279439, questID = 87491, npcID = 271481, npcName = "Captive Fire Elemental", minLevel = 25, escort = true, questTitle = "Spark of Freedom", kind = "accept", text = "Accept: Spark of Freedom", detail = "These are elite mobs: grouping up is encouraged, look for people to do it with. The Captive Fire Elemental is held at the far west end of the Dark Iron ruins, past level 27-30 elite dwarves, and Balgaras the Foul (34, elite) can be among them. Lead it east out of the ruins, then hand it in to Roggo Harlbarrow in the camp. Skip it if you are alone.\n\nTalk to Captive Fire Elemental.\n\nNorth along the road to Dun Modr. Longbraid the Grim, Rhag Garmason and Roggo Harlbarrow stand together in the dwarves' camp; the Captive Fire Elemental is held on the west side: lead it out to Roggo.", index = 17},
    {id = "b0011g04", blockID = 11, sourceBlock = 11, sourceGoal = 4, blockTitle = "Dun Modr", sourceKind = "turnin", uiMapID = 1437, x = 0.4985, y = 0.1809, coordFrame = "era", continentID = 0, worldX = -2646.522625, worldY = -2451.0883745, worldZ = 80.5, questID = 87491, npcID = 1072, npcName = "Roggo Harlbarrow", questTitle = "Spark of Freedom", kind = "turnin", text = "Turn in: Spark of Freedom", detail = "Talk to Roggo Harlbarrow.\n\nNorth along the road to Dun Modr. Longbraid the Grim, Rhag Garmason and Roggo Harlbarrow stand together in the dwarves' camp; the Captive Fire Elemental is held on the west side: lead it out to Roggo.", index = 18},
    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Modr", sourceKind = "collect", uiMapID = 1437, x = 0.5025, y = 0.182, coordFrame = "era", continentID = 0, worldX = -2649.5545, worldY = -2467.6300425, conditions = {{k = "group", q = 98310}}, questID = 98310, objectiveIndex = 2, itemID = 280396, itemName = "Heart of Modr", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Gleaning Our Future", kind = "complete", text = "Collect Heart of Modr ×1 — Gleaning Our Future", detail = "From Modr.\n\nModr stands in the ruins of Dun Modr (use the Goaz Stone).", index = 19},
    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "The Villards", sourceKind = "accept", uiMapID = 1437, x = 0.4993, y = 0.1255, coordFrame = "era", continentID = 0, worldX = -2493.826375, worldY = -2454.3967081, worldZ = 79.3, questID = 87318, npcID = 5683, npcName = "Corma Villard", minLevel = 28, questTitle = "Hearts of the Lost", kind = "accept", text = "Accept: Hearts of the Lost", detail = "Corma Villard may not offer Hearts of the Lost yet: if she doesn't, skip it.\n\nTalk to Corma Villard.\n\nComar Villard waits on the road north of Dun Modr, towards the Thandol Span; Essene a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to Rhag.\n\nComar Villard", index = 20},
    {id = "b0013g02", blockID = 13, sourceBlock = 13, sourceGoal = 2, blockTitle = "The Villards", sourceKind = "turnin", uiMapID = 1437, x = 0.5154, y = 0.0902, coordFrame = "era", continentID = 0, worldX = -2396.53075, worldY = -2520.9769218, questID = 87318, npcID = 271322, npcName = "Essene Villard", questTitle = "Hearts of the Lost", kind = "turnin", text = "Turn in: Hearts of the Lost", detail = "Talk to Essene Villard.\n\nComar Villard waits on the road north of Dun Modr, towards the Thandol Span; Essene a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to Rhag.", index = 21},
    {id = "b0013g03", blockID = 13, sourceBlock = 13, sourceGoal = 3, blockTitle = "The Villards", sourceKind = "turnin", uiMapID = 1437, x = 0.5128, y = 0.0795, coordFrame = "era", continentID = 0, worldX = -2367.038875, worldY = -2510.2248376, worldZ = 75.3, questID = 631, objectID = 2652, objectName = "Ebenezer Rustlocke's Corpse", questTitle = "The Thandol Span", kind = "turnin", text = "Turn in: The Thandol Span", detail = "Two elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out.\n\nInteract with Ebenezer Rustlocke's Corpse.\n\nComar Villard waits on the road north of Dun Modr, towards the Thandol Span; Essene a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to Rhag.\n\nEbenezer Rustlocke's Corpse, inside", index = 22},
    {id = "b0013g04", blockID = 13, sourceBlock = 13, sourceGoal = 4, blockTitle = "The Villards", sourceKind = "accept", uiMapID = 1437, x = 0.5128, y = 0.0795, coordFrame = "era", continentID = 0, worldX = -2367.038875, worldY = -2510.2248376, worldZ = 75.3, questID = 632, objectID = 2652, objectName = "Ebenezer Rustlocke's Corpse", minLevel = 26, requiresAny = {631}, prerequisiteTitles = {["631"] = "The Thandol Span"}, questTitle = "The Thandol Span", kind = "accept", text = "Accept: The Thandol Span", detail = "Interact with Ebenezer Rustlocke's Corpse.\n\nComar Villard waits on the road north of Dun Modr, towards the Thandol Span; Essene a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to Rhag.\n\nthe same corpse", index = 23},
    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Rhag Garmason", sourceKind = "turnin", uiMapID = 1437, x = 0.499, y = 0.1824, coordFrame = "era", continentID = 0, worldX = -2650.657, worldY = -2453.156083, worldZ = 80.2, questID = 632, npcID = 1075, npcName = "Rhag Garmason", questTitle = "The Thandol Span", kind = "turnin", text = "Turn in: The Thandol Span", detail = "Talk to Rhag Garmason.\n\nBack down the road to Dun Modr: Rhag wants the Dark Iron explosives under the far end of the span destroyed.", index = 24},
