    {id = "b0016g01", blockID = 16, sourceBlock = 16, sourceGoal = 1, blockTitle = "Foggy MacKreel", sourceKind = "accept", races = {"Dwarf", "Gnome", "NightElf", "Skyborne"}, uiMapID = 1417, x = 0.4324, y = 0.9264, coordFrame = "era", continentID = 0, worldX = -2356.693, worldY = -2423.307, worldZ = 74.9, questID = 647, npcID = 2696, npcName = "Foggy MacKreel", minLevel = 28, questTitle = "MacKreel's Moonshine", kind = "accept", text = "Accept: MacKreel's Moonshine", detail = "South-west from Kor'gresh's cave to the Thandol Span: Foggy MacKreel stands on a broken section of the bridge; jump down to him from its north end. MacKreel's Moonshine must reach Brewmeister Bilger in Southshore within 15 minutes: go straight back to Refuge Pointe and fly to Southshore.\n\nTalk to Foggy MacKreel.", index = 27},
