    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Level 30.8", sourceKind = "goto", uiMapID = 1437, x = 0.123, y = 0.649, coordFrame = "era", continentID = 0, worldX = -3936.72325, worldY = -898.239291, conditions = {{k = "group", neg = true, q = 474}, {frac = 0.8, k = "level", n = 30, op = "<"}}, kind = "goto", text = "Go to Bluegill Raider", detail = "Skipped Defeat Nek'rosh and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the Gnomeregan dungeon or the Scarlet Monastery dungeon (Graveyard) instead.", index = 37},
