    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "Southshore", sourceKind = "accept", uiMapID = 1424, x = 0.5035, y = 0.5905, coordFrame = "era", continentID = 0, worldX = -859.7331365, worldY = -544.533, worldZ = 10.1, questID = 659, npcID = 2711, npcName = "Phin Odelic", minLevel = 30, questTitle = "Hints of a New Plague?", kind = "accept", text = "Accept: Hints of a New Plague?", detail = "Talk to Phin Odelic.\n\nOff the boat, walk up the pier into town: Phin Odelic and Lieutenant Farren stand by the inn, Brewmeister Bilger below it and Chef Jessen upstairs, Darren Malvew east of it; the flight master is at the north end, Micha Yance and Bartolo Ginsetti between her and the inn, Maleb in the town hall at the west side.\n\nPhin Odelic: his trail leads to Arathi", index = 41},
    {id = "b0026g02", blockID = 26, sourceBlock = 26, sourceGoal = 2, blockTitle = "Southshore", sourceKind = "turnin", uiMapID = 1424, x = 0.5146, y = 0.5839, coordFrame = "era", continentID = 0, worldX = -845.6531387, worldY = -580.053, worldZ = 11.7, questID = 98219, npcID = 2228, npcName = "Lieutenant Farren Orinelle", questTitle = "The Shamed Lieutenant", kind = "turnin", text = "Turn in: The Shamed Lieutenant", detail = "Talk to Lieutenant Farren Orinelle.\n\nOff the boat, walk up the pier into town: Phin Odelic and Lieutenant Farren stand by the inn, Brewmeister Bilger below it and Chef Jessen upstairs, Darren Malvew east of it; the flight master is at the north end, Micha Yance and Bartolo Ginsetti between her and the inn, Maleb in the town hall at the west side.\n\nLieutenant Farren Orinelle, inside", index = 42},
