    {id = "b0026g05", blockID = 26, sourceBlock = 26, sourceGoal = 5, blockTitle = "Southshore", sourceKind = "accept", uiMapID = 1424, x = 0.5157, y = 0.5857, coordFrame = "era", continentID = 0, worldX = -849.4931381, worldY = -583.573, worldZ = 11.7, questID = 98463, npcID = 2366, npcName = "Barkeep Kelly", minLevel = 28, questTitle = "Talk of the Town", kind = "accept", text = "Accept: Talk of the Town", detail = "Barkeep Kelly may not offer Talk of the Town on Forever: if she doesn't, skip it.\n\nTalk to Barkeep Kelly.\n\nOff the boat, walk up the pier into town: Phin Odelic and Lieutenant Farren stand by the inn, Brewmeister Bilger below it and Chef Jessen upstairs, Darren Malvew east of it; the flight master is at the north end, Micha Yance and Bartolo Ginsetti between her and the inn, Maleb in the town hall at the west side.\n\nBarkeep Kelly, in the inn: for Booty Bay (04-stranglethorn-vale)", index = 45},
