    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Tyranis and the Seer", sourceKind = "collect", uiMapID = 1443, x = 0.5301, y = 0.2908, coordFrame = "era", continentID = 1, worldX = -419.7109728, worldY = 1850.0919267, questID = 1439, objectiveIndex = 1, itemID = 6767, itemName = "Tyranis' Pendant", count = 1, questTitle = "Search for Tyranis", kind = "complete", text = "Collect Tyranis' Pendant ×1 — Search for Tyranis", detail = "From Tyranis Malem.\n\nHer brother Tyranis (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The Burning Blade Seer keeps the sceptre in the fortress's main building.\n\nTyranis' Pendant; inside", index = 18},
    {id = "b0008g02", blockID = 8, sourceBlock = 8, sourceGoal = 2, blockTitle = "Tyranis and the Seer", sourceKind = "collect", uiMapID = 1443, x = 0.5517, y = 0.3015, coordFrame = "era", continentID = 1, worldX = -451.788674, worldY = 1752.9819339, questID = 5741, objectiveIndex = 1, itemID = 15750, itemName = "Sceptre of Light", count = 1, questTitle = "Sceptre of Light", kind = "complete", text = "Collect Sceptre of Light ×1 — Sceptre of Light", detail = "From Burning Blade Seer.\n\nHer brother Tyranis (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The Burning Blade Seer keeps the sceptre in the fortress's main building.\n\nSceptre of Light; on the top floor", index = 19},
