    {id = "b0009g03", blockID = 9, sourceBlock = 9, sourceGoal = 3, blockTitle = "Escort Dalinda", sourceKind = "goto", uiMapID = 1443, x = 0.583, y = 0.309, coordFrame = "era", continentID = 1, worldX = -474.273044, worldY = 1612.262361, kind = "goto", text = "Go to Out of Thunder Axe Fortress", index = 22},
    {id = "b0009g04", blockID = 9, sourceBlock = 9, sourceGoal = 4, blockTitle = "Escort Dalinda", sourceKind = "note", kind = "note", manual = true, text = "Lead Dalinda out of the fortress; she walks off once you are clear of it. Vahlarriel takes the turn-in at Nijel's Point at the end of the guide.", index = 23},
