    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "Smeed Scrabblescrew", sourceKind = "accept", uiMapID = 1443, x = 0.6086, y = 0.6186, coordFrame = "era", continentID = 1, worldX = -1402.4278376, worldY = 1497.1690362, worldZ = 61.4, questID = 5561, npcID = 11596, npcName = "Smeed Scrabblescrew", minLevel = 30, questTitle = "Kodo Roundup", kind = "accept", text = "Accept: Kodo Roundup", detail = "Talk to Smeed Scrabblescrew.\n\nSmeed's camp is on the road south of Kolkar Village, by the Kodo Graveyard.", index = 25},
    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Kodo Graveyard", sourceKind = "goto", uiMapID = 1443, x = 0.517, y = 0.567, coordFrame = "era", continentID = 1, worldX = -1247.735372, worldY = 1908.987339, kind = "goto", text = "Go to Kodo Graveyard", detail = "Use Smeed's Kodo Kombobulator on an Aged Kodo and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom.", index = 26},
    {id = "b0011g02", blockID = 11, sourceBlock = 11, sourceGoal = 2, blockTitle = "Kodo Graveyard", sourceKind = "kill", uiMapID = 1443, x = 0.5195, y = 0.561, coordFrame = "era", continentID = 1, worldX = -1229.747876, worldY = 1897.7477565, worldZ = 60.2, questID = 5561, objectiveIndex = 1, npcID = 4700, count = 5, questTitle = "Kodo Roundup", kind = "complete", text = "Kill Aged Kodo ×5 — Kodo Roundup", detail = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo: it becomes a tamed kodo that follows you. Walk it back to Smeed's camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom.\n\nUse Smeed's Kodo Kombobulator on an Aged Kodo and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom.", index = 27},
    {id = "b0011g03", blockID = 11, sourceBlock = 11, sourceGoal = 3, blockTitle = "Kodo Graveyard", sourceKind = "collect", uiMapID = 1443, x = 0.5195, y = 0.561, coordFrame = "era", continentID = 1, worldX = -1229.747876, worldY = 1897.7477565, questID = 1459, objectiveIndex = 2, itemID = 6249, itemName = "Aged Kodo Hide", count = 3, questTitle = "Reagents for Reclaimers Inc.", kind = "complete", text = "Collect Aged Kodo Hide ×3 — Reagents for Reclaimers Inc.", detail = "From Aged Kodo.\n\nUse Smeed's Kodo Kombobulator on an Aged Kodo and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom.", index = 28},
