    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Level 34", sourceKind = "goto", uiMapID = 1434, x = 0.332, y = 0.187, coordFrame = "era", continentID = 0, worldX = -11964.279042, worldY = 102.258, conditions = {{k = "level", n = 34, op = "<"}}, kind = "goto", text = "Go to Elder Stranglethorn Tiger", detail = "The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.", index = 34},
    {id = "b0015g02", blockID = 15, sourceBlock = 15, sourceGoal = 2, blockTitle = "Level 34", sourceKind = "level", conditions = {{k = "level", n = 34, op = "<"}}, kind = "level", level = 34, levelFraction = 0, text = "Reach level 34", detail = "The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.\n\ngrind on Elder Stranglethorn Tiger", index = 35},
