    {id = "b0027g03", blockID = 27, sourceBlock = 27, sourceGoal = 3, blockTitle = "Witherbark Village", sourceKind = "collect", uiMapID = 1417, x = 0.6629, y = 0.8048, coordFrame = "era", continentID = 0, worldX = -2064.853, worldY = -3253.107, questID = 691, objectiveIndex = 3, itemID = 5040, itemName = "Shadow Hunter Knife", count = 1, questTitle = "Worth Its Weight in Gold", kind = "complete", text = "Collect Shadow Hunter Knife ×1 — Worth Its Weight in Gold", detail = "From Witherbark Shadow Hunter.\n\nSouth-east from Northfold to the Witherbark trolls in the hills south of Go'Shek Farm; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley. Every troll here can drop a tusk.\n\nShadow Hunter Knife; below ground", index = 63},
    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Shards of Myzrael", sourceKind = "turnin", uiMapID = 1417, x = 0.625, y = 0.3373, coordFrame = "era", continentID = 0, worldX = -942.853, worldY = -3116.667, worldZ = 48.4, questID = 635, objectID = 138492, objectName = "Shards of Myzrael", optional = true, questTitle = "Crystal in the Mountains", kind = "turnin", text = "Turn in: Crystal in the Mountains", detail = "Interact with Shards of Myzrael.\n\nHead north past Go'Shek Farm; the shards glitter on the hill by the Circle of East Binding.\n\nOnly if Gluggle gave you the pendant in Stranglethorn", index = 64},
    {id = "b0028g02", blockID = 28, sourceBlock = 28, sourceGoal = 2, blockTitle = "Shards of Myzrael", sourceKind = "accept", uiMapID = 1417, x = 0.625, y = 0.3373, coordFrame = "era", continentID = 0, worldX = -942.853, worldY = -3116.667, worldZ = 48.4, questID = 642, objectID = 138492, objectName = "Shards of Myzrael", minLevel = 30, questTitle = "The Princess Trapped", kind = "accept", text = "Accept: The Princess Trapped", detail = "Interact with Shards of Myzrael.\n\nHead north past Go'Shek Farm; the shards glitter on the hill by the Circle of East Binding.", index = 65},
    {id = "b0029g01", blockID = 29, sourceBlock = 29, sourceGoal = 1, blockTitle = "Drywhisker Gorge: kill these as you meet them", sourceKind = "collect", uiMapID = 1417, x = 0.8281, y = 0.3353, coordFrame = "era", continentID = 0, worldX = -938.053, worldY = -3847.827, questID = 627, objectiveIndex = 1, itemID = 4278, itemName = "Lesser Bloodstone Ore", count = 4, questTitle = "Favor for Krazek", kind = "complete", text = "Collect Lesser Bloodstone Ore ×4 — Favor for Krazek", detail = "From Lesser Bloodstone Deposit.\n\nThe Drywhisker kobolds dig in the gorge east of Hammerfall (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", index = 66},
    {id = "b0029g02", blockID = 29, sourceBlock = 29, sourceGoal = 2, blockTitle = "Drywhisker Gorge: kill these as you meet them", sourceKind = "collect", uiMapID = 1417, x = 0.8307, y = 0.3303, coordFrame = "era", continentID = 0, worldX = -926.053, worldY = -3857.187, questID = 642, objectiveIndex = 1, itemID = 4435, itemName = "Mote of Myzrael", count = 12, questTitle = "The Princess Trapped", kind = "complete", text = "Collect Mote of Myzrael ×12 — The Princess Trapped", detail = "From Drywhisker Kobold.\n\nThe Drywhisker kobolds dig in the gorge east of Hammerfall (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.\n\nMote of Myzrael from Drywhisker Kobold, Drywhisker Surveyor and Drywhisker Digger, by this stop", index = 67},
    {id = "b0030g01", blockID = 30, sourceBlock = 30, sourceGoal = 1, blockTitle = "Iridescent Shards", sourceKind = "turnin", uiMapID = 1417, x = 0.8431, y = 0.3095, coordFrame = "era", continentID = 0, worldX = -876.133, worldY = -3901.827, worldZ = 143.1, questID = 642, objectID = 2701, objectName = "Iridescent Shards", questTitle = "The Princess Trapped", kind = "turnin", text = "Turn in: The Princess Trapped", detail = "Interact with Iridescent Shards.\n\nThe shards lie at the far end of Drywhisker Gorge.\n\nBelow ground", index = 68},
    {id = "b0030g02", blockID = 30, sourceBlock = 30, sourceGoal = 2, blockTitle = "Iridescent Shards", sourceKind = "accept", uiMapID = 1417, x = 0.8431, y = 0.3095, coordFrame = "era", continentID = 0, worldX = -876.133, worldY = -3901.827, worldZ = 143.1, questID = 651, objectID = 2701, objectName = "Iridescent Shards", minLevel = 30, requiresAny = {642}, prerequisiteTitles = {["642"] = "The Princess Trapped"}, questTitle = "Stones of Binding", kind = "accept", text = "Accept: Stones of Binding", detail = "Interact with Iridescent Shards.\n\nThe shards lie at the far end of Drywhisker Gorge.", index = 69},
    {id = "b0031g01", blockID = 31, sourceBlock = 31, sourceGoal = 1, blockTitle = "Stones of Binding", sourceKind = "collect", uiMapID = 1417, x = 0.667, y = 0.2972, coordFrame = "era", continentID = 0, worldX = -846.613, worldY = -3267.867, questID = 651, objectiveIndex = 2, itemID = 4484, itemName = "Cresting Key", count = 1, questTitle = "Stones of Binding", kind = "complete", text = "Collect Cresting Key ×1 — Stones of Binding", detail = "From Stone of East Binding.\n\nEach key lies at one of the Highlands' standing-stone circles: east of the shards, near Refuge Pointe and in the west. The Stone of Inner Binding stands west of Refuge Pointe.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.\n\nCresting Key: Stone of East Binding", index = 70},
