    {id = "b0049g01", blockID = 49, sourceBlock = 49, sourceGoal = 1, blockTitle = "Gavin's Naze", sourceKind = "kill", uiMapID = 1416, x = 0.442, y = 0.767, coordFrame = "era", continentID = 0, worldX = 68.266411, worldY = -454.267, worldZ = 141.7, questID = 564, objectiveIndex = 2, npcID = 2407, count = 10, questTitle = "Costly Menace", kind = "complete", text = "Kill Hulking Mountain Lion ×10 — Costly Menace", detail = "Follow the road north out of Southshore into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings, and Baron Vardus walks the manor grounds on the north side of town.", index = 116},
    {id = "b0049g02", blockID = 49, sourceBlock = 49, sourceGoal = 2, blockTitle = "Gavin's Naze", sourceKind = "kill", uiMapID = 1416, x = 0.321, y = 0.828, coordFrame = "era", continentID = 0, worldX = -45.600276, worldY = -115.467, worldZ = 132, questID = 564, objectiveIndex = 1, npcID = 2406, count = 8, questTitle = "Costly Menace", kind = "complete", text = "Kill Mountain Lion ×8 — Costly Menace", detail = "Follow the road north out of Southshore into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings, and Baron Vardus walks the manor grounds on the north side of town.", index = 117},
    {id = "b0050g01", blockID = 50, sourceBlock = 50, sourceGoal = 1, blockTitle = "Ruins of Alterac: kill these as you meet them", sourceKind = "collect", uiMapID = 1416, x = 0.4492, y = 0.602, coordFrame = "era", continentID = 0, worldX = 376.266466, worldY = -474.427, questID = 540, objectiveIndex = 1, itemID = 3658, itemName = "Recovered Tome", count = 5, questTitle = "Preserving Knowledge", kind = "complete", text = "Collect Recovered Tome ×5 — Preserving Knowledge", detail = "The Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up.\n\nSources: Crushridge Ogre, Crushridge Brute.\n\nThe tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\n\nRecovered Tome: Crushridge ogres", index = 118},
    {id = "b0050g02", blockID = 50, sourceBlock = 50, sourceGoal = 2, blockTitle = "Ruins of Alterac: kill these as you meet them", sourceKind = "collect", uiMapID = 1416, x = 0.3842, y = 0.4638, coordFrame = "era", continentID = 0, worldX = 634.2398454, worldY = -292.427, questID = 540, objectiveIndex = 2, itemID = 3659, itemName = "Worn Leather Book", count = 1, questTitle = "Preserving Knowledge", kind = "complete", text = "Collect Worn Leather Book ×1 — Preserving Knowledge", detail = "From Weathered Bookcase.\n\nThe tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\n\nWorn Leather Book: the Weathered Bookcase; inside", index = 119},
    {id = "b0051g01", blockID = 51, sourceBlock = 51, sourceGoal = 1, blockTitle = "Ruins of Alterac: kill these as you meet them", sourceKind = "collect", uiMapID = 1416, x = 0.356, y = 0.544, coordFrame = "era", continentID = 0, worldX = 484.533152, worldY = -213.467, conditions = {{k = "group", q = 543}}, questID = 543, objectiveIndex = 1, itemID = 3684, itemName = "Perenolde Tiara", count = 1, group = {kind = "elite", rank = 1}, questTitle = "The Perenolde Tiara", kind = "complete", text = "Collect Perenolde Tiara ×1 — The Perenolde Tiara", detail = "From Grel'borg the Miser.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Grel'borg the Miser is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.", index = 120},
    {id = "b0052g01", blockID = 52, sourceBlock = 52, sourceGoal = 1, blockTitle = "Strahnbrad: kill these as you meet them", sourceKind = "collect", uiMapID = 1416, x = 0.3832, y = 0.2246, coordFrame = "era", continentID = 0, worldX = 1080.7465918, worldY = -289.627, questID = 512, objectiveIndex = 1, itemID = 3505, itemName = "Alterac Signet Ring", count = 7, questTitle = "Noble Deaths", kind = "complete", text = "Collect Alterac Signet Ring ×7 — Noble Deaths", detail = "From Syndicate Spy.\n\nCareful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside Nagaz's house. Nagaz does not join when they are pulled, and a ranged attack through the doorway brings him out by himself.", index = 121},
    {id = "b0052g02", blockID = 52, sourceBlock = 52, sourceGoal = 2, blockTitle = "Strahnbrad: kill these as you meet them", sourceKind = "kill", uiMapID = 1416, x = 0.4779, y = 0.1745, coordFrame = "era", continentID = 0, worldX = 1174.2666085, worldY = -554.787, worldZ = 71.1, questID = 537, objectiveIndex = 1, npcID = 2318, count = 4, questTitle = "Dark Council", kind = "complete", text = "Kill Argus Shadow Mage ×4 — Dark Council", detail = "Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside Nagaz's house. Nagaz does not join when they are pulled, and a ranged attack through the doorway brings him out by himself.", index = 122},
    {id = "b0052g03", blockID = 52, sourceBlock = 52, sourceGoal = 3, blockTitle = "Strahnbrad: kill these as you meet them", sourceKind = "collect", uiMapID = 1416, x = 0.4783, y = 0.1711, coordFrame = "era", continentID = 0, worldX = 1180.6132763, worldY = -555.907, questID = 523, objectiveIndex = 1, itemID = 3626, itemName = "Head of Baron Vardus", count = 1, questTitle = "Baron's Demise", kind = "complete", text = "Collect Head of Baron Vardus ×1 — Baron's Demise", detail = "From Baron Vardus.\n\nCareful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside Nagaz's house. Nagaz does not join when they are pulled, and a ranged attack through the doorway brings him out by himself.", index = 123},
    {id = "b0053g01", blockID = 53, sourceBlock = 53, sourceGoal = 1, blockTitle = "Crushridge ogres", sourceKind = "collect", uiMapID = 1416, x = 0.4518, y = 0.2941, coordFrame = "era", continentID = 0, worldX = 951.0132353, worldY = -481.707, questID = 500, objectiveIndex = 1, itemID = 2843, itemName = "Dirty Knucklebones", count = 9, questTitle = "Crushridge Bounty", kind = "complete", text = "Collect Dirty Knucklebones ×9 — Crushridge Bounty", detail = "The Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up.\n\nSources: Crushridge Ogre, Crushridge Brute.\n\nThe Crushridge ogres hold the hills north of Strahnbrad. Farther north, a worn wooden chest holds the Ensorcelled Parchment; Nagaz of the Dark Council stands right by it.", index = 124},
