    {id = "b0053g04", blockID = 53, sourceBlock = 53, sourceGoal = 4, blockTitle = "Crushridge ogres", sourceKind = "collect", uiMapID = 1416, x = 0.3922, y = 0.1431, coordFrame = "era", continentID = 0, worldX = 1232.8799523, worldY = -314.827, questID = 537, objectiveIndex = 2, itemID = 3672, itemName = "Head of Nagaz", count = 1, questTitle = "Dark Council", kind = "complete", text = "Collect Head of Nagaz ×1 — Dark Council", detail = "From Nagaz.\n\nThe Crushridge ogres hold the hills north of Strahnbrad. Farther north, a worn wooden chest holds the Ensorcelled Parchment; Nagaz of the Dark Council stands right by it.", index = 127},
