    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Agmond's End", sourceKind = "turnin", uiMapID = 1418, x = 0.5089, y = 0.624, coordFrame = "era", continentID = 0, worldX = -6924.383416, worldY = -3345.05575, worldZ = 243.5, questID = 738, objectID = 2875, objectName = "Battered Dwarven Skeleton", questTitle = "Find Agmond", kind = "turnin", text = "Turn in: Find Agmond", detail = "Interact with Battered Dwarven Skeleton.\n\nThe battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south.", index = 19},
