    {id = "b0027g01", blockID = 27, sourceBlock = 27, sourceGoal = 1, blockTitle = "Kodo Graveyard", sourceKind = "collect", uiMapID = 1443, x = 0.5389, y = 0.5812, coordFrame = "era", continentID = 1, worldX = -1290.3057792, worldY = 1810.5285963, questID = 5501, objectiveIndex = 1, itemID = 13703, itemName = "Kodo Bone", count = 10, questTitle = "Bone Collector", kind = "complete", text = "Collect Kodo Bone ×10 — Bone Collector", detail = "From Kodo Bones.\n\nHornizz stands at the edge of the Kodo Graveyard, south-west of Kormek's Hut; Kodo Bones lie among the skeletons. A Flesh Picker crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off.", index = 61},
    {id = "b0027g02", blockID = 27, sourceBlock = 27, sourceGoal = 2, blockTitle = "Kodo Graveyard", sourceKind = "kill", uiMapID = 1443, x = 0.4994, y = 0.604, coordFrame = "era", continentID = 1, worldX = -1358.658264, worldY = 1988.1139998, npcID = 217590, kind = "note", manual = true, text = "Kill Flesh Picker ×1", detail = "Hornizz stands at the edge of the Kodo Graveyard, south-west of Kormek's Hut; Kodo Bones lie among the skeletons. A Flesh Picker crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off.\n\nFlesh Picker: catch it, for My Little Friends", index = 62},
    {id = "b0027g03", blockID = 27, sourceBlock = 27, sourceGoal = 3, blockTitle = "Kodo Graveyard", sourceKind = "accept", uiMapID = 1443, x = 0.4783, y = 0.6183, coordFrame = "era", continentID = 1, worldX = -1401.5284628, worldY = 2082.9760761, worldZ = 61.9, questID = 6134, npcID = 6019, npcName = "Hornizz Brimbuzzle", minLevel = 34, questTitle = "Ghost-o-plasm Round Up", kind = "accept", text = "Accept: Ghost-o-plasm Round Up", detail = "Talk to Hornizz Brimbuzzle.\n\nHornizz stands at the edge of the Kodo Graveyard, south-west of Kormek's Hut; Kodo Bones lie among the skeletons. A Flesh Picker crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off.", index = 63},
    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Maraudine centaurs", sourceKind = "collect", uiMapID = 1443, x = 0.3971, y = 0.6141, coordFrame = "era", continentID = 1, worldX = -1388.9372156, worldY = 2448.0377157, questID = 93224, objectiveIndex = 1, itemID = 254432, itemName = "Carved Centaur Totem", count = 5, questTitle = "Carved Centaur Totems", kind = "complete", text = "Collect Carved Centaur Totem ×5 — Carved Centaur Totems", detail = "Sources: Maraudine Wrangler, Maraudine Scout, Maraudine Mauler, Maraudine Windchaser, Maraudine Marauder.\n\nThe Maraudine centaurs hold the Valley of Spears west of the graveyard; every kind drops the totems.", index = 64},
    {id = "b0029g01", blockID = 29, sourceBlock = 29, sourceGoal = 1, blockTitle = "Melizza Brimbuzzle", sourceKind = "accept", uiMapID = 1443, x = 0.3395, y = 0.535, coordFrame = "era", continentID = 1, worldX = -1151.80206, worldY = 2706.9976965, worldZ = 111.2, questID = 6132, npcID = 12277, npcName = "Melizza Brimbuzzle", minLevel = 34, escort = true, questTitle = "Get Me Out of Here!", kind = "accept", text = "Accept: Get Me Out of Here!", detail = "Talk to Melizza Brimbuzzle.\n\nMelizza is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.", index = 65},
    {id = "b0029g02", blockID = 29, sourceBlock = 29, sourceGoal = 2, blockTitle = "Melizza Brimbuzzle", sourceKind = "complete", uiMapID = 1443, x = 0.401, y = 0.616, coordFrame = "era", continentID = 1, worldX = -1394.633256, worldY = 2430.503967, questID = 6132, escort = true, questTitle = "Get Me Out of Here!", kind = "complete", text = "Complete: Get Me Out of Here!", detail = "Melizza Brimbuzzle escorted to safety.\n\nMelizza is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.\n\nescort Melizza back toward the graveyard", index = 66},
    {id = "b0030g01", blockID = 30, sourceBlock = 30, sourceGoal = 1, blockTitle = "Mannoroc Coven", sourceKind = "collect", uiMapID = 1443, x = 0.5036, y = 0.7145, coordFrame = "era", continentID = 1, worldX = -1689.927982, worldY = 1969.2315012, questID = 1466, objectiveIndex = 2, itemID = 6251, itemName = "Nether Wing", count = 10, questTitle = "Reagents for Reclaimers Inc.", kind = "complete", text = "Collect Nether Wing ×10 — Reagents for Reclaimers Inc.", detail = "From Nether Maiden.\n\nThe demons gather at the Mannoroc Coven in southern Desolace: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs.", index = 67},
