    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Elwynn Forest", sourceKind = "goto", races = {"Human"}, uiMapID = 1429, x = 0.846, y = 0.645, coordFrame = "era", continentID = 0, worldX = -9432.489035, worldY = -1400.908564, conditions = {{k = "level", n = 40, op = ">="}}, kind = "goto", text = "Go to Elwynn Forest", index = 56},
    {id = "b0024g01", blockID = 24, sourceBlock = 24, sourceGoal = 1, blockTitle = "Riding at 40", sourceKind = "train", races = {"Human"}, uiMapID = 1429, x = 0.8432, y = 0.6487, coordFrame = "era", continentID = 0, worldX = -9441.0529921, worldY = -1391.1902288, worldZ = 46.9, conditions = {{k = "level", n = 40, op = ">="}}, npcID = 4732, npcName = "Randal Hunter", optional = true, kind = "train", text = "Train available abilities", manual = true, detail = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Randal Hunter teaches Humans at Eastvale Logging Camp in eastern Elwynn Forest, beside Katie Hunter's horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.", index = 57},
    {id = "b0024g02", blockID = 24, sourceBlock = 24, sourceGoal = 2, blockTitle = "Riding at 40", sourceKind = "vendor", races = {"Human"}, uiMapID = 1429, x = 0.8415, y = 0.6549, coordFrame = "era", continentID = 0, worldX = -9455.4034067, worldY = -1385.289811, worldZ = 47.2, conditions = {{k = "level", n = 40, op = ">="}}, npcID = 384, npcName = "Katie Hunter", optional = true, kind = "vendor", mode = "supplies", text = "Sell unwanted items, repair and restock", manual = true, detail = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Randal Hunter teaches Humans at Eastvale Logging Camp in eastern Elwynn Forest, beside Katie Hunter's horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.\n\nKatie Hunter: other colours, 20g", index = 58},
    {id = "b0025g01", blockID = 25, sourceBlock = 25, sourceGoal = 1, blockTitle = "Riding at 40", sourceKind = "note", races = {"Skyborne"}, conditions = {{k = "level", n = 40, op = ">="}}, kind = "note", manual = true, text = "Riding and Galestriders: Genn Fairweather, at the Fairweather Stables in Valanaar on Zephras Isle.", detail = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from Genn Fairweather, the stablemaster and riding trainer at the Fairweather Stables in Valanaar on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of Dalaran about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders.", index = 59},
    {id = "b0025g02", blockID = 25, sourceBlock = 25, sourceGoal = 2, blockTitle = "Riding at 40", sourceKind = "note", races = {"Skyborne"}, conditions = {{k = "level", n = 40, op = ">="}}, kind = "note", manual = true, text = "Skyboat to Zephras Isle: the north side of Dalaran, about every five minutes.", detail = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from Genn Fairweather, the stablemaster and riding trainer at the Fairweather Stables in Valanaar on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of Dalaran about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders.", index = 60},
