    {id = "b0057g01", blockID = 57, sourceBlock = 57, sourceGoal = 1, blockTitle = "The Bloodsail captains", sourceKind = "collect", uiMapID = 1434, x = 0.2919, y = 0.886, coordFrame = "era", continentID = 0, worldX = -14937.941076, worldY = 358.146125, itemID = 4056, itemName = "Cortello's Riddle", kind = "note", manual = true, text = "Collect Cortello's Riddle ×1", detail = "The captains stand on the ships anchored off the Wild Shore, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, Fleet Master Firallon (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore.", index = 130},
    {id = "b0057g02", blockID = 57, sourceBlock = 57, sourceGoal = 2, blockTitle = "The Bloodsail captains", sourceKind = "accept", questID = 624, itemID = 4056, itemName = "Cortello's Riddle", minLevel = 35, questTitle = "Cortello's Riddle", kind = "accept", text = "Accept: Cortello's Riddle", detail = "Use Cortello's Riddle to start this quest.\n\nThe captains stand on the ships anchored off the Wild Shore, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, Fleet Master Firallon (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore.\n\nfor the Swamp of Sorrows later", index = 131},
