    {id = "b0058g02", blockID = 58, sourceBlock = 58, sourceGoal = 2, blockTitle = "Zanzil's village", sourceKind = "collect", uiMapID = 1434, x = 0.4, y = 0.5824, coordFrame = "era", continentID = 0, worldX = -13646.3762784, worldY = -331.667, questID = 609, objectiveIndex = 3, itemID = 3926, itemName = "Chucky's Huge Ring", count = 1, questTitle = "Voodoo Dues", kind = "complete", text = "Collect Chucky's Huge Ring ×1 — Voodoo Dues", detail = "From Chucky \"Ten Thumbs\".\n\nEvery Zanzil follower can drop the mixture; Chucky \"Ten Thumbs\" walks the south of the camp.", index = 133},
