    {id = "b0064g01", blockID = 64, sourceBlock = 64, sourceGoal = 1, blockTitle = "Rebel Camp", sourceKind = "kill", uiMapID = 1434, x = 0.431, y = 0.1673, coordFrame = "era", continentID = 0, worldX = -11880.4719718, worldY = -529.48575, npcID = 217588, kind = "note", manual = true, text = "Kill Arbor Tarantula ×1", detail = "Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an Arbor Tarantula crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off.\n\nArbor Tarantula: catch it, for My Little Friends", index = 142},
