    {id = "b0066g01", blockID = 66, sourceBlock = 66, sourceGoal = 1, blockTitle = "Panther Mastery", sourceKind = "collect", uiMapID = 1434, x = 0.494, y = 0.24, coordFrame = "era", continentID = 0, worldX = -12189.74984, worldY = -931.5045, conditions = {{k = "group", q = 193}}, questID = 193, objectiveIndex = 1, itemID = 3876, itemName = "Fang of Bhag'thera", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Panther Mastery", kind = "complete", text = "Collect Fang of Bhag'thera ×1 — Panther Mastery", detail = "From Bhag'thera.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Bhag'thera is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.", index = 145},
    {id = "b0067g01", blockID = 67, sourceBlock = 67, sourceGoal = 1, blockTitle = "Ruins of Zul'Mamwe: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.4561, y = 0.416, coordFrame = "era", continentID = 0, worldX = -12938.483056, worldY = -689.655125, questID = 209, objectiveIndex = 1, itemID = 1524, itemName = "Skullsplitter Tusk", count = 18, questTitle = "Skullsplitter Tusks", kind = "complete", text = "Collect Skullsplitter Tusk ×18 — Skullsplitter Tusks", detail = "Sources: Skullsplitter Panther, Gan'zulah, Nezzliok the Dire.\n\nThe Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the Crystalvein Mine; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp.", index = 146},
    {id = "b0067g02", blockID = 67, sourceBlock = 67, sourceGoal = 2, blockTitle = "Ruins of Zul'Mamwe: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.4238, y = 0.4141, coordFrame = "era", continentID = 0, worldX = -12930.4001406, worldY = -483.54075, questID = 600, objectiveIndex = 1, itemID = 3917, itemName = "Singing Blue Crystal", count = 10, questTitle = "Venture Company Mining", kind = "complete", text = "Collect Singing Blue Crystal ×10 — Venture Company Mining", detail = "Sources: Venture Co. Strip Miner, Venture Co. Surveyor, Venture Co. Foreman, Venture Co. Tinkerer.\n\nThe Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the Crystalvein Mine; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp.", index = 147},
    {id = "b0068g01", blockID = 68, sourceBlock = 68, sourceGoal = 1, blockTitle = "Level 42.06", sourceKind = "goto", uiMapID = 1434, x = 0.363, y = 0.423, coordFrame = "era", continentID = 0, worldX = -12968.262218, worldY = -95.56075, conditions = {{k = "group", neg = true, q = 193}, {frac = 0.06, k = "level", n = 42, op = "<"}}, kind = "goto", text = "Go to Cold Eye Basilisk", detail = "If you skipped Panther Mastery, grind here to level 42.06 to stay on the route's plan. Or, with a group, run the Uldaman dungeon instead.", index = 148},
