    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "Lost Rigger Cove: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.7055, y = 0.4303, coordFrame = "era", continentID = 1, worldX = -7854.38, worldY = -5086.7, worldZ = 5.6, questID = 8366, objectiveIndex = 1, npcID = 7855, count = 10, questTitle = "Southsea Shakedown", kind = "complete", text = "Kill Southsea Pirate ×10 — Southsea Shakedown", detail = "Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. Andre Firebeard stands on the far side; Stoley's stolen cargo lies in the camp.\nCareful: Two or three pirates stand with Andre, and many more pirates from the town join the fight once it starts.", index = 34},
