    {id = "b0017g01", blockID = 17, sourceBlock = 17, sourceGoal = 1, blockTitle = "The Noxious Lair", sourceKind = "collect", uiMapID = 1446, x = 0.3608, y = 0.3945, coordFrame = "era", continentID = 1, worldX = -7689.7, worldY = -2708.27, questID = 82, objectiveIndex = 1, itemID = 8587, itemName = "Centipaar Insect Parts", count = 5, questTitle = "Noxious Lair Investigation", kind = "complete", text = "Collect Centipaar Insect Parts ×5 — Noxious Lair Investigation", detail = "From Centipaar Worker.\n\nRide north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you.", index = 56},
    {id = "b0018g01", blockID = 18, sourceBlock = 18, sourceGoal = 1, blockTitle = "Dunemaul Compound", sourceKind = "kill", uiMapID = 1446, x = 0.3927, y = 0.512, coordFrame = "era", continentID = 1, worldX = -8230.2, worldY = -2928.38, worldZ = 15.6, questID = 5863, objectiveIndex = 1, npcID = 5474, count = 10, questTitle = "The Dunemaul Compound", kind = "complete", text = "Kill Dunemaul Brute ×10 — The Dunemaul Compound", detail = "Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; Gor'marok the Ravager (49) stands in the middle with guards around him: clear them first.", index = 57},
    {id = "b0018g02", blockID = 18, sourceBlock = 18, sourceGoal = 2, blockTitle = "Dunemaul Compound", sourceKind = "kill", uiMapID = 1446, x = 0.3986, y = 0.5092, coordFrame = "era", continentID = 1, worldX = -8217.32, worldY = -2969.09, worldZ = 11.2, questID = 5863, objectiveIndex = 2, npcID = 5472, count = 10, questTitle = "The Dunemaul Compound", kind = "complete", text = "Kill Dunemaul Enforcer ×10 — The Dunemaul Compound", detail = "Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; Gor'marok the Ravager (49) stands in the middle with guards around him: clear them first.", index = 58},
