    {id = "b0018g04", blockID = 18, sourceBlock = 18, sourceGoal = 4, blockTitle = "Dunemaul Compound", sourceKind = "level", kind = "level", level = 47, levelFraction = 0.06, text = "Reach level 47 + 6% XP", detail = "Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; Gor'marok the Ravager (49) stands in the middle with guards around him: clear them first.\n\ngrind on Dunemaul Brute", index = 60},
    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Thistleshrub Valley: kill these as you meet them", sourceKind = "collect", uiMapID = 1446, x = 0.3124, y = 0.6472, coordFrame = "era", continentID = 1, worldX = -8852.12, worldY = -2374.31, questID = 2605, objectiveIndex = 1, itemID = 8428, itemName = "Laden Dew Gland", count = 1, questTitle = "The Thirsty Goblin", kind = "complete", text = "Collect Laden Dew Gland ×1 — The Thirsty Goblin", detail = "From Thistleshrub Dew Collector.\n\nRide south into Thistleshrub Valley. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs.", index = 61},
