    {id = "b0019g03", blockID = 19, sourceBlock = 19, sourceGoal = 3, blockTitle = "Thistleshrub Valley: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.3122, y = 0.6554, coordFrame = "era", continentID = 1, worldX = -8889.84, worldY = -2372.93, worldZ = 13.4, questID = 3362, objectiveIndex = 1, npcID = 5490, count = 8, questTitle = "Thistleshrub Valley", kind = "complete", text = "Kill Gnarled Thistleshrub ×8 — Thistleshrub Valley", detail = "Ride south into Thistleshrub Valley. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs.", index = 63},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Tooga's escort", sourceKind = "accept", uiMapID = 1446, x = 0.3, y = 0.65, coordFrame = "era", continentID = 1, worldX = -8865.0, worldY = -2288.75, questID = 1560, npcID = 5955, npcName = "Tooga", minLevel = 40, escort = true, questTitle = "Tooga's Quest", kind = "accept", text = "Accept: Tooga's Quest", detail = "Talk to Tooga.\n\nThe little turtle Tooga hides at the north end of the valley. Lead him home to his wife Torta, by the water just east of Steamwheedle Port: he walks slowly and the desert's beasts go for him, so keep him alive.", index = 64},
