D.routes["forever/alliance/40-50/05-the-hinterlands"] = {id = "forever/alliance/40-50/05-the-hinterlands", title = "The Hinterlands, Blasted Lands & Loch Modan", faction = "Alliance", startLevel = 47, endLevel = 48, zone = 1425, zoneName = "The Hinterlands", source = "Polestar", sourceCommit = "e978e136279cf075eff34718f3ad5fd3dacba623", next = "forever/alliance/40-50/06-searing-gorge", stepCount = 99, steps = {
    {id = "b0001g01", blockID = 1, sourceBlock = 1, sourceGoal = 1, blockTitle = "The Altar of Zul", sourceKind = "goto", uiMapID = 1425, x = 0.49, y = 0.687, coordFrame = "era", continentID = 0, worldX = -296.633229, worldY = -3461.5, conditions = {{k = "onquest", q = {2989}}}, kind = "goto", text = "Go to The Altar of Zul", detail = "Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the Hinterlands, and climb to the top. Qiaga and Morta'gya the Keeper (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including Qiaga the Keeper and Morta'gya the Keeper, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group.", index = 1},
    {id = "b0001g02", blockID = 1, sourceBlock = 1, sourceGoal = 2, blockTitle = "The Altar of Zul", sourceKind = "complete", uiMapID = 1425, x = 0.49, y = 0.687, coordFrame = "era", continentID = 0, worldX = -296.633229, worldY = -3461.5, conditions = {{k = "onquest", q = {2989}}}, questID = 2989, questTitle = "The Altar of Zul", kind = "complete", text = "Complete: The Altar of Zul", detail = "Search the Altar of Zul.\n\nRide south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the Hinterlands, and climb to the top. Qiaga and Morta'gya the Keeper (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including Qiaga the Keeper and Morta'gya the Keeper, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group.", index = 2},
