    {id = "b0005g03", blockID = 5, sourceBlock = 5, sourceGoal = 3, blockTitle = "The Grimesilt outhouse", sourceKind = "turnin", uiMapID = 1427, x = 0.6559, y = 0.6217, coordFrame = "era", continentID = 0, worldX = -7024.77875, worldY = -1786.393875, worldZ = 265.8, questID = 4449, objectID = 173265, objectName = "Wooden Outhouse", questTitle = "Caught!", kind = "turnin", text = "Turn in: Caught!", detail = "Interact with Wooden Outhouse.", index = 7},
    {id = "b0005g04", blockID = 5, sourceBlock = 5, sourceGoal = 4, blockTitle = "The Grimesilt outhouse", sourceKind = "note", kind = "note", manual = true, text = "The prisoner's next task, Ledger from Tanaris, sends you to the Swamp of Sorrows and Dustwallow Marsh: skip it.", index = 8},
