    {id = "b0015g02", blockID = 15, sourceBlock = 15, sourceGoal = 2, blockTitle = "Kalaran Windblade", sourceKind = "accept", uiMapID = 1427, x = 0.3906, y = 0.3899, coordFrame = "era", continentID = 0, worldX = -6679.97625, worldY = -1194.44325, worldZ = 240.3, questID = 3442, npcID = 8479, npcName = "Velarok Windblade", minLevel = 40, requiresAny = {3441}, prerequisiteTitles = {["3441"] = "Divine Retribution"}, questTitle = "The Flawless Flame", kind = "accept", text = "Accept: The Flawless Flame", detail = "Talk to Velarok Windblade.", index = 26},
    {id = "b0016g01", blockID = 16, sourceBlock = 16, sourceGoal = 1, blockTitle = "Firewatch Ridge: kill these as you meet them", sourceKind = "collect", uiMapID = 1427, x = 0.3867, y = 0.4139, coordFrame = "era", continentID = 0, worldX = -6715.67625, worldY = -1185.741375, questID = 3442, objectiveIndex = 1, itemID = 10509, itemName = "Heart of Flame", count = 4, questTitle = "The Flawless Flame", kind = "complete", text = "Collect Heart of Flame ×4 — The Flawless Flame", detail = "Sources: Magma Elemental, Inferno Elemental, Blazing Elemental.\n\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a Thorium Plated Dagger. The Steamsmiths work at the furnaces in the middle (the Smithing Tuyere), the Lookouts stand on the southern ridges (the Spyglass). Any Dark Iron may drop the Grimesilt Outhouse Key: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee.", index = 27},
    {id = "b0016g02", blockID = 16, sourceBlock = 16, sourceGoal = 2, blockTitle = "Firewatch Ridge: kill these as you meet them", sourceKind = "collect", uiMapID = 1427, x = 0.3867, y = 0.4139, coordFrame = "era", continentID = 0, worldX = -6715.67625, worldY = -1185.741375, questID = 3442, objectiveIndex = 2, itemID = 10511, itemName = "Golem Oil", count = 4, questTitle = "The Flawless Flame", kind = "complete", text = "Collect Golem Oil ×4 — The Flawless Flame", detail = "Sources: Magma Elemental, Tempered War Golem, Heavy War Golem.\n\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a Thorium Plated Dagger. The Steamsmiths work at the furnaces in the middle (the Smithing Tuyere), the Lookouts stand on the southern ridges (the Spyglass). Any Dark Iron may drop the Grimesilt Outhouse Key: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee.", index = 28},
    {id = "b0016g03", blockID = 16, sourceBlock = 16, sourceGoal = 3, blockTitle = "Firewatch Ridge: kill these as you meet them", sourceKind = "kill", uiMapID = 1427, x = 0.3749, y = 0.3964, coordFrame = "era", continentID = 0, worldX = -6689.645, worldY = -1159.412625, worldZ = 184.9, questID = 7729, objectiveIndex = 1, npcID = 5846, count = 15, questTitle = "JOB OPPORTUNITY: Culling the Competition", kind = "complete", text = "Kill Dark Iron Taskmaster ×15 — JOB OPPORTUNITY: Culling the Competition", detail = "Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a Thorium Plated Dagger. The Steamsmiths work at the furnaces in the middle (the Smithing Tuyere), the Lookouts stand on the southern ridges (the Spyglass). Any Dark Iron may drop the Grimesilt Outhouse Key: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee.", index = 29},
