    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Fire Plume Ridge and the eastern jungle", sourceKind = "collect", uiMapID = 1449, x = 0.4641, y = 0.2222, coordFrame = "era", continentID = 1, worldX = -6514.7601852, worldY = -1183.837, questID = 4141, objectiveIndex = 1, itemID = 11316, itemName = "Bloodpetal", count = 15, questTitle = "Muigin and Larion", kind = "complete", text = "Collect Bloodpetal ×15 — Muigin and Larion", detail = "From Bloodpetal Lasher.\n\nRide south to Fire Plume Ridge in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around Fire Plume Ridge: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's Crate of Foodstuffs sits at an abandoned camp in the eastern jungle.", index = 36},
