    {id = "b0019g02", blockID = 19, sourceBlock = 19, sourceGoal = 2, blockTitle = "Level 49.51", sourceKind = "level", conditions = {{frac = 0.51, k = "level", n = 49, op = "<"}}, kind = "level", level = 49, levelFraction = 0.51, text = "Reach level 49 + 51% XP", detail = "Top up here to level 49.51 before the hand-ins at Marshal's Refuge: they take you to level 50. Or, with a group, run the Maraudon dungeon instead.\n\ngrind on Pterrordax", index = 56},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Crate of Foodstuffs", sourceKind = "collect", uiMapID = 1449, x = 0.6854, y = 0.3654, coordFrame = "era", continentID = 1, worldX = -6867.9867564, worldY = -2002.647, questID = 3881, objectiveIndex = 1, itemID = 11113, itemName = "Crate of Foodstuffs", count = 1, questTitle = "Expedition Salvation", kind = "complete", text = "Collect Crate of Foodstuffs ×1 — Expedition Salvation", detail = "From Crate of Foodstuffs.\n\nRide south down the east side. Young Diemetradons graze the eastern jungle and Fledgling Pterrordax fly near the eastern cliffs; both drop Shizzle's scales. The crate sits at the abandoned camp in the eastern jungle.", index = 57},
    {id = "b0020g02", blockID = 20, sourceBlock = 20, sourceGoal = 2, blockTitle = "Crate of Foodstuffs", sourceKind = "collect", uiMapID = 1449, x = 0.6542, y = 0.3531, coordFrame = "era", continentID = 1, worldX = -6837.6467646, worldY = -1887.207, questID = 4503, objectiveIndex = 1, itemID = 11830, itemName = "Webbed Diemetradon Scale", count = 8, questTitle = "Shizzle's Flyer", kind = "complete", text = "Collect Webbed Diemetradon Scale ×8 — Shizzle's Flyer", detail = "Sources: Young Diemetradon, Diemetradon, Elder Diemetradon.\n\nRide south down the east side. Young Diemetradons graze the eastern jungle and Fledgling Pterrordax fly near the eastern cliffs; both drop Shizzle's scales. The crate sits at the abandoned camp in the eastern jungle.", index = 58},
    {id = "b0021g01", blockID = 21, sourceBlock = 21, sourceGoal = 1, blockTitle = "Eastern Pylon", sourceKind = "goto", uiMapID = 1449, x = 0.772, y = 0.5, coordFrame = "era", continentID = 1, worldX = -7200.0, worldY = -2323.067, kind = "goto", text = "Go to Eastern Crystal Pylon", detail = "The pylon stands on the eastern cliffs.", index = 59},
