    {id = "b0022g01", blockID = 22, sourceBlock = 22, sourceGoal = 1, blockTitle = "The Gorishi hive", sourceKind = "use", uiMapID = 1449, x = 0.487, y = 0.853, coordFrame = "era", continentID = 1, worldX = -8070.733098, worldY = -1268.567, questID = 3883, objectiveIndex = 1, itemID = 11132, itemName = "Unused Scraping Vial", questTitle = "Alien Ecology", kind = "complete", text = "Use Unused Scraping Vial — Alien Ecology", detail = "Ride south-west past Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health.", index = 61},
    {id = "b0022g02", blockID = 22, sourceBlock = 22, sourceGoal = 2, blockTitle = "The Gorishi hive", sourceKind = "collect", uiMapID = 1449, x = 0.4869, y = 0.8532, coordFrame = "era", continentID = 1, worldX = -8071.2264312, worldY = -1268.197, questID = 3883, objectiveIndex = 1, itemID = 11131, itemName = "Hive Wall Sample", count = 1, questTitle = "Alien Ecology", kind = "complete", text = "Collect Hive Wall Sample ×1 — Alien Ecology", detail = "From Gorishi Hive Hatchery.\n\nRide south-west past Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health.", index = 62},
    {id = "b0022g03", blockID = 22, sourceBlock = 22, sourceGoal = 3, blockTitle = "The Gorishi hive", sourceKind = "collect", uiMapID = 1449, x = 0.4835, y = 0.8525, coordFrame = "era", continentID = 1, worldX = -8069.499765, worldY = -1255.617, questID = 3764, objectiveIndex = 1, itemID = 11018, itemName = "Un'Goro Soil", count = 20, questTitle = "Un'Goro Soil", kind = "complete", text = "Collect Un'Goro Soil ×20 — Un'Goro Soil", detail = "Sources: Gorishi Tunneler, Gorishi Hive Guard, Gorishi Worker, Gorishi Stinger, Gorishi Wasp.\n\nRide south-west past Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health.", index = 63},
    {id = "b0022g04", blockID = 22, sourceBlock = 22, sourceGoal = 4, blockTitle = "The Gorishi hive", sourceKind = "level", kind = "level", level = 49, levelFraction = 0.6, text = "Reach level 49 + 60% XP", detail = "Ride south-west past Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health.\n\ngrind on Frenzied Pterrordax", index = 64},
