    {id = "b0043g01", blockID = 43, sourceBlock = 43, sourceGoal = 1, blockTitle = "A Taste of Flame", sourceKind = "collect", uiMapID = 1428, x = 0.944, y = 0.318, coordFrame = "era", continentID = 0, worldX = -7652.012394, worldY = -3031.799704, conditions = {{k = "group", q = 4023}}, questID = 4023, objectiveIndex = 1, itemID = 10575, itemName = "Black Dragonflight Molt", count = 1, questTitle = "A Taste of Flame", kind = "complete", text = "Collect Black Dragonflight Molt ×1 — A Taste of Flame", detail = "From Frenzied Black Drake.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Frenzied Black Drake is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back.", index = 98},
