    {id = "b0045g01", blockID = 45, sourceBlock = 45, sourceGoal = 1, blockTitle = "Level 52.08", sourceKind = "goto", uiMapID = 1428, x = 0.896, y = 0.512, coordFrame = "era", continentID = 0, worldX = -8030.716496, worldY = -2891.199736, conditions = {{k = "group", neg = true, q = 4023}, {frac = 0.08, k = "level", n = 52, op = "<"}}, kind = "goto", text = "Go to Ember Worg", detail = "If you skipped A Taste of Flame, grind here to level 52.08 to stay on the route's plan. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", index = 100},
    {id = "b0045g02", blockID = 45, sourceBlock = 45, sourceGoal = 2, blockTitle = "Level 52.08", sourceKind = "level", conditions = {{k = "group", neg = true, q = 4023}, {frac = 0.08, k = "level", n = 52, op = "<"}}, kind = "level", level = 52, levelFraction = 0.08, text = "Reach level 52 + 8% XP", detail = "If you skipped A Taste of Flame, grind here to level 52.08 to stay on the route's plan. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.\n\ngrind on Ember Worg", index = 101},
    {id = "b0046g01", blockID = 46, sourceBlock = 46, sourceGoal = 1, blockTitle = "Blackrock Stronghold", sourceKind = "collect", uiMapID = 1428, x = 0.8934, y = 0.5065, coordFrame = "era", continentID = 0, worldX = -8019.9800395, worldY = -2883.5839044, questID = 4283, objectiveIndex = 1, itemID = 11467, itemName = "Blackrock Medallion", count = 50, questTitle = "FIFTY! YEP!", kind = "complete", text = "Collect Blackrock Medallion ×50 — FIFTY! YEP!", detail = "Sources: Ember Worg, Blackrock Worg, Slavering Ember Worg, Giant Ember Worg, Blackrock Soldier.\n\nGor'tesh and the Blackrock orcs hold the camps and the stronghold at the foot of Blackrock Mountain, west of Flame Crest. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: Gor'tesh has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling.\n\nBlackrock Medallion; inside", index = 102},
