    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Level 55.05", sourceKind = "goto", uiMapID = 1452, x = 0.314, y = 0.36, coordFrame = "era", continentID = 1, worldX = 6829.33312, worldY = -2546.067, conditions = {{frac = 0.05, k = "level", n = 55, op = "<"}}, kind = "goto", text = "Go to Winterfall Pathfinder", detail = "Top up here to level 55.05 before the hand-ins at Everlook: they take you to level 56. Grind the Winterfall furbolgs camped by Frostfire Hot Springs (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through Timbermaw Hold need. Or, with a group, run the Blackrock Depths dungeon or the Blackrock Spire dungeon (Lower) instead.", index = 41},
    {id = "b0011g02", blockID = 11, sourceBlock = 11, sourceGoal = 2, blockTitle = "Level 55.05", sourceKind = "level", conditions = {{frac = 0.05, k = "level", n = 55, op = "<"}}, kind = "level", level = 55, levelFraction = 0.05, text = "Reach level 55 + 5% XP", detail = "Top up here to level 55.05 before the hand-ins at Everlook: they take you to level 56. Grind the Winterfall furbolgs camped by Frostfire Hot Springs (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through Timbermaw Hold need. Or, with a group, run the Blackrock Depths dungeon or the Blackrock Spire dungeon (Lower) instead.\n\ngrind on Winterfall Pathfinder", index = 42},
