    {id = "b0100g01", blockID = 100, sourceBlock = 100, sourceGoal = 1, blockTitle = "The crater", sourceKind = "collect", uiMapID = 1449, x = 0.455, y = 0.723, coordFrame = "era", continentID = 1, worldX = -7750.066518, worldY = -1150.167, questID = 4496, objectiveIndex = 1, itemID = 11837, itemName = "Gorishi Scent Gland", count = 1, questTitle = "Bungle in the Jungle", kind = "complete", text = "Collect Gorishi Scent Gland ×1 — Bungle in the Jungle", detail = "Sources: Gorishi Reaver, Gorishi Hive Queen, Gorishi Wasp, Gorishi Worker, Gorishi Stinger.\n\nTar Beasts wallow in the Lakkari Tar Pits; the fire elementals of Fire Plume Ridge in the middle carry the ash; the Gorishi wasps of the Slithering Scar in the south carry the gland. Every creature in the crater can drop Un'Goro Soil.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd.", index = 240},
