    {id = "b0102g02", blockID = 102, sourceBlock = 102, sourceGoal = 2, blockTitle = "Torwa Pathfinder", sourceKind = "accept", uiMapID = 1449, x = 0.7164, y = 0.7596, coordFrame = "era", continentID = 1, worldX = -7840.3464936, worldY = -2117.347, worldZ = -254.3, questID = 4289, npcID = 9619, npcName = "Torwa Pathfinder", minLevel = 47, questTitle = "The Apes of Un'Goro", kind = "accept", text = "Accept: The Apes of Un'Goro", detail = "Talk to Torwa Pathfinder.\n\nRide down the ramp into the crater: Torwa camps at its foot.\n\nThe pelts come after loop 2, on the gorilla plateau", index = 243},
    {id = "b0103g01", blockID = 103, sourceBlock = 103, sourceGoal = 1, blockTitle = "Lakkari Tar Pits: kill these as you meet them", sourceKind = "collect", uiMapID = 1449, x = 0.6185, y = 0.3336, coordFrame = "era", continentID = 1, worldX = -6789.5467776, worldY = -1755.117, questID = 4504, objectiveIndex = 1, itemID = 11834, itemName = "Super Sticky Tar", count = 12, questTitle = "Super Sticky", kind = "complete", text = "Collect Super Sticky Tar ×12 — Super Sticky", detail = "Sources: Tar Beast, Tar Lurker, Tar Lord, Tar Creeper.\n\nThe gorillas live on Ironstone Plateau, east of Marshal's Refuge. Keep their pelts for Torwa Pathfinder. Stay out of the deepest cave: U'cha is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds.", index = 244},
