    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "The Undercroft", sourceKind = "turnin", uiMapID = 1423, x = 0.2358, y = 0.7379, coordFrame = "live", worldZ = 87.9, questID = 6024, objectID = 177675, objectName = "Mound of Dirt", questTitle = "Hameya's Plea", kind = "turnin", text = "Turn in: Hameya's Plea", detail = "Interact with Mound of Dirt.\n\nRide south-west to the Undercroft. The mound of dirt lies inside. Mercutio Filthgorger is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot.", index = 43},
    {id = "b0013g02", blockID = 13, sourceBlock = 13, sourceGoal = 2, blockTitle = "The Undercroft", sourceKind = "collect", uiMapID = 1423, x = 0.2385, y = 0.7422, coordFrame = "live", questID = 5781, objectiveIndex = 1, itemID = 14613, itemName = "Taelan's Hammer", count = 1, optional = true, questTitle = "Of Forgotten Memories", kind = "complete", text = "Collect Taelan's Hammer ×1 — Of Forgotten Memories", detail = "From Mercutio Filthgorger.\n\nRide south-west to the Undercroft. The mound of dirt lies inside. Mercutio Filthgorger is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot.\n\nTaelan's Hammer, from Mercutio Filthgorger", index = 44},
