    {id = "b0023g03", blockID = 23, sourceBlock = 23, sourceGoal = 3, blockTitle = "Hive'Ashi: kill these as you meet them", sourceKind = "collect", uiMapID = 1451, x = 0.2838, y = 0.3099, coordFrame = "era", continentID = 1, worldX = -6678.2056684, worldY = 1548.9298108, itemID = 20404, itemName = "Encrypted Twilight Text", count = 20, optional = true, kind = "note", manual = true, text = "Collect Encrypted Twilight Text ×20", detail = "The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an Encrypted Twilight Text: keep twenty, ten for Bor Wildmane and ten for Hermit Ortell later.\n\nTen more for True Believers", index = 56},
