    {id = "b0086g03", blockID = 86, sourceBlock = 86, sourceGoal = 3, blockTitle = "The Forlorn Cavern", sourceKind = "train", races = {"Dwarf"}, classes = {"ROGUE", "SHAMAN", "WARLOCK"}, kind = "train", text = "Train your class abilities", manual = true, detail = "North of the Great Forge: Eldrun Stormbreaker, the shaman trainer, stands at the south end of the Forlorn Cavern, the rogue and warlock trainers and Lago Blackwrench just north of him.", index = 267},
    {id = "b0087g01", blockID = 87, sourceBlock = 87, sourceGoal = 1, blockTitle = "The Tome of Divinity", sourceKind = "level", races = {"Dwarf"}, classes = {"PALADIN"}, kind = "level", level = 12, levelFraction = 0, text = "Reach level 12", detail = "West from the Forlorn Cavern into the Mystic Ward: Brandur Ironhammer, Tiza Battleforge and Muiredon Battleforge are in the Hall of Mysteries, Tiza and Muiredon on its upper floor: the stairs up start just north-east of Brandur. John Turner, a beggar, wanders the city. He asks for ten Linen Cloth: the troggs and trolls of Dun Morogh drop it, and the Auction House sells it.", index = 268},
