    {id = "b0036g01", blockID = 36, sourceBlock = 36, sourceGoal = 1, blockTitle = "Shimmerweed", sourceKind = "collect", races = {"Gnome"}, uiMapID = 1426, x = 0.421, y = 0.4552, coordFrame = "era", continentID = 0, worldX = -5371.6566368, worldY = -271.342, questID = 315, objectiveIndex = 1, itemID = 2676, itemName = "Shimmerweed", count = 6, questTitle = "The Perfect Stout", kind = "complete", text = "Collect Shimmerweed ×6 — The Perfect Stout", detail = "From Shimmerweed Basket.\n\nThe Shimmerweed grows in baskets up on Shimmer Ridge, the snowy slope north of the road between Kharanos and Brewnall: climb from the road west of Kharanos. The Frostmane Seers camped on the ridge drop it too.", index = 137},
