    {id = "b0038g01", blockID = 38, sourceBlock = 38, sourceGoal = 1, blockTitle = "Tundra MacGrann", sourceKind = "accept", races = {"Gnome"}, uiMapID = 1426, x = 0.3457, y = 0.5165, coordFrame = "era", continentID = 0, worldX = -5572.925011, worldY = 99.5105, worldZ = 483.9, questID = 312, npcID = 1266, npcName = "Tundra MacGrann", minLevel = 7, questTitle = "Tundra MacGrann's Stolen Stash", kind = "accept", text = "Accept: Tundra MacGrann's Stolen Stash", detail = "Talk to Tundra MacGrann.\n\nTundra MacGrann camps in Chill Breeze Valley, south of the road back east from Brewnall to Kharanos. His meats are in the locker in Old Icebeard's cave, east of his camp. Old Icebeard is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him.", index = 142},
