    {id = "b0079g01", blockID = 79, sourceBlock = 79, sourceGoal = 1, blockTitle = "The Applejack Still", sourceKind = "accept", races = {"Human"}, uiMapID = 1429, x = 0.2455, y = 0.5804, coordFrame = "era", continentID = 0, worldX = -9282.9669732, worldY = 683.327253, questID = 91736, objectID = 562131, objectName = "Applejack Still", minLevel = 1, optional = true, questTitle = "Applejack Still", kind = "accept", text = "Accept: Applejack Still", detail = "Interact with Applejack Still.\n\nThe Applejack Still stands north of the Westbrook Garrison. Click it with four Shiny Red Apples in your bags: it takes them and gives you a Thunder Applejack on the spot (the quest never shows in your quest log). Keep the Applejack for Sergeant De Vries: don't drink it.", index = 236},
