    {id = "b0080g01", blockID = 80, sourceBlock = 80, sourceGoal = 1, blockTitle = "Westbrook Garrison", sourceKind = "turnin", races = {"Human"}, uiMapID = 1429, x = 0.2423, y = 0.7445, coordFrame = "era", continentID = 0, worldX = -9662.7900435, worldY = 694.4339218, worldZ = 36.9, questID = 239, npcID = 963, npcName = "Deputy Rainer", questTitle = "Westbrook Garrison Needs Help!", kind = "turnin", text = "Turn in: Westbrook Garrison Needs Help!", detail = "Talk to Deputy Rainer.\n\nFollow the road south to the Westbrook Garrison, on the way into Westfall. Deputy Rainer stands outside the barracks; Sergeant De Vries stands inside. He has An Apple Treat only while you carry the Thunder Applejack: talk to him and it goes straight to the hand-in.", index = 239},
