    {id = "b0013g01-reminder", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "Raptor Heads as you go", kind = "note", sourceKind = "along-reminder", text = "While travelling: Collect Raptor Head ×12 — Raptor Thieves", detail = "Work on this objective as you travel. Its completion checkpoint appears before The Crossroads.\n\nFrom Sunscale Lashtail.\n\nSunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health.", manual = true, deferredToBlock = 57, questID = 869, questTitle = "Raptor Thieves", index = 46},
    {id = "b0014g01-reminder", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Plainstrider Beaks as you go", kind = "note", sourceKind = "along-reminder", text = "While travelling: Collect Plainstrider Beak ×7 — Plainstrider Menace", detail = "Work on this objective as you travel. Its completion checkpoint appears before The Crossroads.\n\nFrom Greater Plainstrider.\n\nPlainstriders roam the plains all over the Barrens, and about one in four drops a beak: kill the ones you pass on the way.", manual = true, deferredToBlock = 17, questID = 844, questTitle = "Plainstrider Menace", index = 47},
    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Razormane camp", sourceKind = "kill", uiMapID = 1413, x = 0.5494, y = 0.2674, coordFrame = "era", continentID = 1, worldX = -194.12125, worldY = -2944.3366996, worldZ = 91.8, questID = 871, objectiveIndex = 1, npcID = 3267, count = 8, questTitle = "Disrupt the Attacks", kind = "complete", text = "Kill Razormane Water Seeker ×8 — Disrupt the Attacks", detail = "In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.", index = 48},
