    {id = "b0039g01", blockID = 39, sourceBlock = 39, sourceGoal = 1, blockTitle = "The Barrens: kill these as you meet them", sourceKind = "collect", uiMapID = 1413, x = 0.4588, y = 0.254, coordFrame = "era", continentID = 1, worldX = -103.5875, worldY = -2026.2566392, questID = 855, objectiveIndex = 1, itemID = 5030, itemName = "Centaur Bracers", count = 15, questTitle = "Centaur Bracers", kind = "complete", text = "Collect Centaur Bracers ×15 — Centaur Bracers", detail = "Sources: Kolkar Wrangler, Kolkar Stormer, Kolkar Pack Runner, Kolkar Marauder, Kolkar Bloodcharger.\n\nThe pools lie just north of Regthar. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. Barak Kodobane stands in the Kolkar camp west of the pools.", index = 108},
    {id = "b0039g02", blockID = 39, sourceBlock = 39, sourceGoal = 2, blockTitle = "The Barrens: kill these as you meet them", sourceKind = "complete", uiMapID = 1413, x = 0.453, y = 0.228, coordFrame = "era", continentID = 1, worldX = 72.075, worldY = -1967.483302, questID = 870, questTitle = "The Forgotten Pools", kind = "complete", text = "Complete: The Forgotten Pools", detail = "Explore the waters of the Forgotten Pools.\n\nThe pools lie just north of Regthar. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. Barak Kodobane stands in the Kolkar camp west of the pools.", index = 109},
