    {id = "b0041g01", blockID = 41, sourceBlock = 41, sourceGoal = 1, blockTitle = "The Dry Hills", sourceKind = "collect", uiMapID = 1413, x = 0.4423, y = 0.3121, coordFrame = "era", continentID = 1, worldX = -496.125625, worldY = -1859.0566282, questID = 903, objectiveIndex = 1, itemID = 5096, itemName = "Prowler Claws", count = 7, questTitle = "Prowlers of the Barrens", kind = "complete", text = "Collect Prowler Claws ×7 — Prowlers of the Barrens", detail = "From Savannah Prowler.\n\nWest to the Dry Hills. The Witchwing harpies nest all over them; any of them can drop a talon. Chen's Empty Keg lies in their hills. Savannah Prowlers hunt the plains between Regthar and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat.", index = 115},
    {id = "b0041g02", blockID = 41, sourceBlock = 41, sourceGoal = 2, blockTitle = "The Dry Hills", sourceKind = "collect", uiMapID = 1413, x = 0.4185, y = 0.1932, coordFrame = "era", continentID = 1, worldX = 307.1925, worldY = -1617.883279, questID = 867, objectiveIndex = 1, itemID = 5064, itemName = "Witchwing Talon", count = 8, questTitle = "Harpy Raiders", kind = "complete", text = "Collect Witchwing Talon ×8 — Harpy Raiders", detail = "Sources: Witchwing Harpy, Witchwing Roguefeather, Witchwing Slayer, Witchwing Ambusher, Witchwing Windcaller.\n\nWest to the Dry Hills. The Witchwing harpies nest all over them; any of them can drop a talon. Chen's Empty Keg lies in their hills. Savannah Prowlers hunt the plains between Regthar and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat.", index = 116},
    {id = "b0042g01", blockID = 42, sourceBlock = 42, sourceGoal = 1, blockTitle = "Samophlange", sourceKind = "turnin", uiMapID = 1413, x = 0.524, y = 0.1165, coordFrame = "era", continentID = 1, worldX = 825.396875, worldY = -2686.950016, worldZ = 91.6, questID = 894, objectID = 4141, objectName = "Control Console", questTitle = "Samophlange", kind = "turnin", text = "Turn in: Samophlange", detail = "Interact with Control Console.\n\nThe Control Console stands at the Venture Co. research site west of the Sludge Fen. Close the three valves around the drill, use the console again, then take the Console Key from Tinkerer Sniggles beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close.", index = 117},
