    {id = "b0054g01", blockID = 54, sourceBlock = 54, sourceGoal = 1, blockTitle = "Raptor Horns", sourceKind = "collect", uiMapID = 1413, x = 0.441, y = 0.144, coordFrame = "era", continentID = 1, worldX = 639.6, worldY = -1845.883294, questID = 865, objectiveIndex = 1, itemID = 5055, itemName = "Intact Raptor Horn", count = 5, questTitle = "Raptor Horns", kind = "complete", text = "Collect Intact Raptor Horn ×5 — Raptor Horns", detail = "Sources: Sunscale Scytheclaw.\n\nOn the way east to Echeyakee: Sunscale Scytheclaws prowl the plains east of the Dry Hills; any of them can drop an Intact Raptor Horn for Mebok in Ratchet.", index = 157},
    {id = "b0055g01", blockID = 55, sourceBlock = 55, sourceGoal = 1, blockTitle = "Echeyakee", sourceKind = "use", uiMapID = 1413, x = 0.558, y = 0.171, coordFrame = "era", continentID = 1, worldX = 457.18125, worldY = -3031.483372, questID = 881, objectiveIndex = 1, itemID = 10327, itemName = "Horn of Echeyakee", questTitle = "Echeyakee", kind = "complete", text = "Use Horn of Echeyakee — Echeyakee", detail = "South-east on the way back to the Crossroads: Echeyakee, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside Echeyakee, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads.", index = 158},
    {id = "b0055g02", blockID = 55, sourceBlock = 55, sourceGoal = 2, blockTitle = "Echeyakee", sourceKind = "collect", uiMapID = 1413, x = 0.5586, y = 0.1719, coordFrame = "era", continentID = 1, worldX = 451.100625, worldY = -3037.5633724, questID = 881, objectiveIndex = 1, itemID = 5100, itemName = "Echeyakee's Hide", count = 1, questTitle = "Echeyakee", kind = "complete", text = "Collect Echeyakee's Hide ×1 — Echeyakee", detail = "From Echeyakee.\n\nSouth-east on the way back to the Crossroads: Echeyakee, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside Echeyakee, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads.", index = 159},
    {id = "b0056g01", blockID = 56, sourceBlock = 56, sourceGoal = 1, blockTitle = "Finish the Raptor Heads", sourceKind = "collect", uiMapID = 1413, x = 0.56, y = 0.15, coordFrame = "era", continentID = 1, worldX = 599.0625, worldY = -3051.75004, conditions = {{item = 5062, k = "has", n = 12, neg = true}}, questID = 869, objectiveIndex = 1, itemID = 5062, itemName = "Raptor Head", count = 12, questTitle = "Raptor Thieves", kind = "complete", text = "Collect Raptor Head ×12 — Raptor Thieves", detail = "From Sunscale Lashtail.\n\nStill short of twelve? The Sunscale Screechers are thickest on the plains around Echeyakee's lair, north of the Razormane camp.", index = 160},
    {id = "b0013g01", blockID = 57, sourceBlock = 13, sourceGoal = 1, blockTitle = "Raptor Heads as you go", sourceKind = "collect", uiMapID = 1413, x = 0.5293, y = 0.3304, coordFrame = "era", continentID = 1, worldX = -619.765, worldY = -2740.6566862, questID = 869, objectiveIndex = 1, itemID = 5062, itemName = "Raptor Head", count = 12, questTitle = "Raptor Thieves", kind = "complete", text = "Collect Raptor Head ×12 — Raptor Thieves", detail = "From Sunscale Lashtail.\n\nSunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health.", deferredFromBlock = 13, index = 161},
    {id = "b0057g01", blockID = 57, sourceBlock = 57, sourceGoal = 1, blockTitle = "The Crossroads", sourceKind = "turnin", uiMapID = 1413, x = 0.5193, y = 0.3032, coordFrame = "era", continentID = 1, worldX = -435.995, worldY = -2639.3233462, worldZ = 96.4, questID = 869, npcID = 3464, npcName = "Gazrog", questTitle = "Raptor Thieves", kind = "turnin", text = "Turn in: Raptor Thieves", detail = "Talk to Gazrog.\n\nIn from the north gate: Gazrog first, Sergra by the inn, Tonga at the south gate, then up to Darsok and Thork on the tower platform, where the flight master stands.", index = 162},
    {id = "b0057g02", blockID = 57, sourceBlock = 57, sourceGoal = 2, blockTitle = "The Crossroads", sourceKind = "accept", uiMapID = 1413, x = 0.5193, y = 0.3032, coordFrame = "era", continentID = 1, worldX = -435.995, worldY = -2639.3233462, worldZ = 96.4, questID = 3281, npcID = 3464, npcName = "Gazrog", minLevel = 9, requiresAny = {869}, prerequisiteTitles = {["869"] = "Raptor Thieves"}, questTitle = "Stolen Silver", kind = "accept", text = "Accept: Stolen Silver", detail = "Talk to Gazrog.\n\nIn from the north gate: Gazrog first, Sergra by the inn, Tonga at the south gate, then up to Darsok and Thork on the tower platform, where the flight master stands.\n\nGazrog: the Stolen Silver, in a raptor nest north-west of Northwatch Hold", index = 163},
