    {id = "b0068g01", blockID = 68, sourceBlock = 68, sourceGoal = 1, blockTitle = "Bruuz", sourceKind = "collect", uiMapID = 1413, x = 0.637, y = 0.387, coordFrame = "era", continentID = 1, worldX = -1002.16875, worldY = -3832.016758, conditions = {{k = "group", q = 92706}}, questID = 92706, objectiveIndex = 1, itemID = 253710, itemName = "Bruuz's Dorsal Fin", count = 1, optional = true, group = {kind = "group", size = 2}, questTitle = "WANTED: Bruuz", kind = "complete", text = "Collect Bruuz's Dorsal Fin ×1 — WANTED: Bruuz", detail = "From Bruuz.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Bruuz (level 20 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.", index = 197},
    {id = "b0069g01", blockID = 69, sourceBlock = 69, sourceGoal = 1, blockTitle = "Ratchet", sourceKind = "turnin", uiMapID = 1413, x = 0.6268, y = 0.3623, coordFrame = "era", continentID = 1, worldX = -835.289375, worldY = -3728.6567512, worldZ = 26.4, conditions = {{k = "group", q = 92706}}, questID = 92706, npcID = 3391, npcName = "Gazlowe", optional = true, questTitle = "WANTED: Bruuz", kind = "turnin", text = "Turn in: WANTED: Bruuz", detail = "Talk to Gazlowe.\n\nGazlowe stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", index = 198},
