    {id = "b0070g03", blockID = 70, sourceBlock = 70, sourceGoal = 3, blockTitle = "Raptor nests", sourceKind = "interact", uiMapID = 1413, x = 0.5246, y = 0.4656, coordFrame = "era", continentID = 1, worldX = -1533.21, worldY = -2693.0300164, worldZ = 91.3, questID = 905, objectiveIndex = 3, objectID = 6906, objectName = "Red Raptor Nest", questTitle = "The Angry Scytheclaws", kind = "complete", text = "Interact with Red Raptor Nest — The Angry Scytheclaws", detail = "South-west from Ratchet across the plains to the Raptor Grounds: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them.", index = 201},
    {id = "b0071g01", blockID = 71, sourceBlock = 71, sourceGoal = 1, blockTitle = "Raptor Grounds: kill these as you meet them", sourceKind = "collect", uiMapID = 1413, x = 0.5258, y = 0.4599, coordFrame = "era", continentID = 1, worldX = -1494.699375, worldY = -2705.1900172, questID = 865, objectiveIndex = 1, itemID = 5055, itemName = "Intact Raptor Horn", count = 5, questTitle = "Raptor Horns", kind = "complete", text = "Collect Intact Raptor Horn ×5 — Raptor Horns", detail = "Sources: Sunscale Scytheclaw.\n\nSunscale Scytheclaws hunt the plains around the Raptor Grounds; they drop the horns. Mebok takes them when the escort brings you back to Ratchet.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of Northwatch Hold.", index = 202},
    {id = "b0071g02", blockID = 71, sourceBlock = 71, sourceGoal = 2, blockTitle = "Raptor Grounds: kill these as you meet them", sourceKind = "collect", uiMapID = 1413, x = 0.5804, y = 0.5387, coordFrame = "era", continentID = 1, worldX = -2027.091875, worldY = -3258.4700536, questID = 3281, objectiveIndex = 1, itemID = 5061, itemName = "Stolen Silver", count = 1, questTitle = "Stolen Silver", kind = "complete", text = "Collect Stolen Silver ×1 — Stolen Silver", detail = "From Stolen Silver.\n\nSunscale Scytheclaws hunt the plains around the Raptor Grounds; they drop the horns. Mebok takes them when the escort brings you back to Ratchet.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of Northwatch Hold.", index = 203},
    {id = "b0072g01", blockID = 72, sourceBlock = 72, sourceGoal = 1, blockTitle = "Stolen Booty", sourceKind = "collect", uiMapID = 1413, x = 0.626, y = 0.496, coordFrame = "era", continentID = 1, worldX = -1738.6, worldY = -3720.550084, questID = 888, objectiveIndex = 1, itemID = 5076, itemName = "Shipment of Boots", count = 1, questTitle = "Stolen Booty", kind = "complete", text = "Collect Shipment of Boots ×1 — Stolen Booty", detail = "From Drizzlik's Emporium.\n\nEast to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, a short walk north of Northwatch Hold.", index = 204},
    {id = "b0072g02", blockID = 72, sourceBlock = 72, sourceGoal = 2, blockTitle = "Stolen Booty", sourceKind = "collect", uiMapID = 1413, x = 0.636, y = 0.493, coordFrame = "era", continentID = 1, worldX = -1718.33125, worldY = -3821.883424, questID = 888, objectiveIndex = 2, itemID = 5077, itemName = "Telescopic Lens", count = 1, questTitle = "Stolen Booty", kind = "complete", text = "Collect Telescopic Lens ×1 — Stolen Booty", detail = "From Fragile - Do Not Drop.\n\nEast to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, a short walk north of Northwatch Hold.", index = 205},
    {id = "b0073g01", blockID = 73, sourceBlock = 73, sourceGoal = 1, blockTitle = "Northwatch Hold: kill these as you meet them", sourceKind = "collect", uiMapID = 1413, x = 0.6201, y = 0.5166, coordFrame = "era", continentID = 1, worldX = -1877.77875, worldY = -3660.7634134, questID = 891, objectiveIndex = 4, itemID = 5078, itemName = "Theramore Medal", count = 10, questTitle = "The Guns of Northwatch", kind = "complete", text = "Collect Theramore Medal ×10 — The Guns of Northwatch", detail = "From Theramore Marine.\n\nNorthwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.", index = 206},
    {id = "b0073g02", blockID = 73, sourceBlock = 73, sourceGoal = 2, blockTitle = "Northwatch Hold: kill these as you meet them", sourceKind = "kill", uiMapID = 1413, x = 0.6185, y = 0.5465, coordFrame = "era", continentID = 1, worldX = -2079.790625, worldY = -3644.550079, worldZ = 96.3, questID = 891, objectiveIndex = 1, npcID = 3393, count = 1, questTitle = "The Guns of Northwatch", kind = "complete", text = "Kill Captain Fairmount ×1 — The Guns of Northwatch", detail = "Northwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.\n\nOn the top floor", index = 207},
    {id = "b0073g03", blockID = 73, sourceBlock = 73, sourceGoal = 3, blockTitle = "Northwatch Hold: kill these as you meet them", sourceKind = "kill", uiMapID = 1413, x = 0.6043, y = 0.5477, coordFrame = "era", continentID = 1, worldX = -2087.898125, worldY = -3500.6567362, worldZ = 130.1, questID = 891, objectiveIndex = 2, npcID = 3455, count = 1, questTitle = "The Guns of Northwatch", kind = "complete", text = "Kill Cannoneer Whessan ×1 — The Guns of Northwatch", detail = "Northwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.\n\nOn the top floor", index = 208},
    {id = "b0073g04", blockID = 73, sourceBlock = 73, sourceGoal = 4, blockTitle = "Northwatch Hold: kill these as you meet them", sourceKind = "kill", uiMapID = 1413, x = 0.6318, y = 0.5664, coordFrame = "era", continentID = 1, worldX = -2214.24, worldY = -3779.3234212, worldZ = 130.9, questID = 891, objectiveIndex = 3, npcID = 3454, count = 1, questTitle = "The Guns of Northwatch", kind = "complete", text = "Kill Cannoneer Smythe ×1 — The Guns of Northwatch", detail = "Northwatch Hold, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier.\n\nUpstairs", index = 209},
