    {id = "b0081g01", blockID = 81, sourceBlock = 81, sourceGoal = 1, blockTitle = "Dreadmist Peak", sourceKind = "collect", races = {"Tauren"}, classes = {"DRUID"}, uiMapID = 1413, x = 0.484, y = 0.189, coordFrame = "era", continentID = 1, worldX = 335.56875, worldY = -2281.616656, questID = 6127, objectiveIndex = 1, itemID = 15843, itemName = "Filled Dreadmist Peak Sampler", count = 1, questTitle = "The Principal Source", kind = "complete", text = "Collect Filled Dreadmist Peak Sampler ×1 — The Principal Source", detail = "From Dreadmist Peak Pool.\n\nHead north from the Crossroads to Dreadmist Peak and fill the Empty Dreadmist Peak Sampler at the Dreadmist Peak Pool, then back to Tonga Runetotem in the Crossroads. No Herbalism? Hula'mahi beside him sells Earthroot, three at a time until he restocks.", index = 222},
