    {id = "b0127g01", blockID = 127, sourceBlock = 127, sourceGoal = 1, blockTitle = "Grunt Dogran", sourceKind = "turnin", classes = {"WARLOCK"}, uiMapID = 1413, x = 0.433, y = 0.4789, coordFrame = "era", continentID = 1, worldX = -1623.068125, worldY = -1764.816622, worldZ = 91.8, questID = 1515, npcID = 5908, npcName = "Grunt Dogran", questTitle = "Dogran's Captivity", kind = "turnin", text = "Turn in: Dogran's Captivity", detail = "Talk to Grunt Dogran.\n\nDogran is chained up in the quilboar camp west of the road.", index = 337},
