    {id = "b0128g01", blockID = 128, sourceBlock = 128, sourceGoal = 1, blockTitle = "Enraged Thunder Lizards", sourceKind = "collect", uiMapID = 1413, x = 0.4346, y = 0.4925, coordFrame = "era", continentID = 1, worldX = -1714.953125, worldY = -1781.0299564, questID = 907, objectiveIndex = 1, itemID = 5143, itemName = "Thunder Lizard Blood", count = 3, questTitle = "Enraged Thunder Lizards", kind = "complete", text = "Collect Thunder Lizard Blood ×3 — Enraged Thunder Lizards", detail = "From Stormhide.\n\nThunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard, roams among them: his Tailspike starts a quest.", index = 339},
    {id = "b0128g02", blockID = 128, sourceBlock = 128, sourceGoal = 2, blockTitle = "Enraged Thunder Lizards", sourceKind = "collect", uiMapID = 1413, x = 0.442, y = 0.62, coordFrame = "era", continentID = 1, worldX = -2576.375, worldY = -1856.016628, itemID = 5102, itemName = "Owatanka's Tailspike", optional = true, kind = "note", manual = true, text = "Collect Owatanka's Tailspike ×1", detail = "Thunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard, roams among them: his Tailspike starts a quest.", index = 340},
    {id = "b0128g03", blockID = 128, sourceBlock = 128, sourceGoal = 3, blockTitle = "Enraged Thunder Lizards", sourceKind = "accept", questID = 884, itemID = 5102, itemName = "Owatanka's Tailspike", minLevel = 10, optional = true, questTitle = "Owatanka", kind = "accept", text = "Accept: Owatanka", detail = "Use Owatanka's Tailspike to start this quest.\n\nThunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard, roams among them: his Tailspike starts a quest.", index = 341},
    {id = "b0129g01", blockID = 129, sourceBlock = 129, sourceGoal = 1, blockTitle = "Jorn Skyseer", sourceKind = "turnin", uiMapID = 1413, x = 0.4486, y = 0.5914, coordFrame = "era", continentID = 1, worldX = -2383.14625, worldY = -1922.8966324, worldZ = 95.9, questID = 907, npcID = 3387, npcName = "Jorn Skyseer", questTitle = "Enraged Thunder Lizards", kind = "turnin", text = "Turn in: Enraged Thunder Lizards", detail = "Talk to Jorn Skyseer.", index = 342},
    {id = "b0129g02", blockID = 129, sourceBlock = 129, sourceGoal = 2, blockTitle = "Jorn Skyseer", sourceKind = "accept", uiMapID = 1413, x = 0.4486, y = 0.5914, coordFrame = "era", continentID = 1, worldX = -2383.14625, worldY = -1922.8966324, worldZ = 95.9, questID = 913, npcID = 3387, npcName = "Jorn Skyseer", minLevel = 10, requiresAny = {907}, prerequisiteTitles = {["907"] = "Enraged Thunder Lizards"}, questTitle = "Cry of the Thunderhawk", kind = "accept", text = "Accept: Cry of the Thunderhawk", detail = "Talk to Jorn Skyseer.", index = 343},
    {id = "b0129g03", blockID = 129, sourceBlock = 129, sourceGoal = 3, blockTitle = "Jorn Skyseer", sourceKind = "turnin", uiMapID = 1413, x = 0.4486, y = 0.5914, coordFrame = "era", continentID = 1, worldX = -2383.14625, worldY = -1922.8966324, worldZ = 95.9, questID = 884, npcID = 3387, npcName = "Jorn Skyseer", optional = true, questTitle = "Owatanka", kind = "turnin", text = "Turn in: Owatanka", detail = "Talk to Jorn Skyseer.", index = 344},
    {id = "b0130g01", blockID = 130, sourceBlock = 130, sourceGoal = 1, blockTitle = "Cry of the Thunderhawk", sourceKind = "collect", uiMapID = 1413, x = 0.4669, y = 0.6149, coordFrame = "era", continentID = 1, worldX = -2541.918125, worldY = -2108.3366446, questID = 913, objectiveIndex = 1, itemID = 5164, itemName = "Thunderhawk Wings", count = 1, questTitle = "Cry of the Thunderhawk", kind = "complete", text = "Collect Thunderhawk Wings ×1 — Cry of the Thunderhawk", detail = "From Thunderhawk Hatchling.\n\nThunderhawk Cloudscrapers circle over the same plains south of the camp.", index = 345},
    {id = "b0131g01", blockID = 131, sourceBlock = 131, sourceGoal = 1, blockTitle = "Field of Giants", sourceKind = "collect", uiMapID = 1413, x = 0.4494, y = 0.694, coordFrame = "era", continentID = 1, worldX = -3076.3375, worldY = -1931.0032996, questID = 868, objectiveIndex = 1, itemID = 5058, itemName = "Silithid Egg", count = 12, questTitle = "Egg Hunt", kind = "complete", text = "Collect Silithid Egg ×12 — Egg Hunt", detail = "South of Camp Taurajo, on the road to Gann, the Silithid Mounds dot the Field of Giants; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head.\n\nFrom Silithid Mound.\n\nSouth of Camp Taurajo, the Silithid Mounds dot the Field of Giants; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit.", index = 346},
    {id = "b0132g01", blockID = 132, sourceBlock = 132, sourceGoal = 1, blockTitle = "Brine", sourceKind = "turnin", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1530, npcID = 5899, npcName = "Brine", questTitle = "Call of Water", kind = "turnin", text = "Turn in: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.", index = 347},
    {id = "b0132g02", blockID = 132, sourceBlock = 132, sourceGoal = 2, blockTitle = "Brine", sourceKind = "accept", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1535, npcID = 5899, npcName = "Brine", minLevel = 20, requiresAny = {1530}, prerequisiteTitles = {["1530"] = "Call of Water"}, questTitle = "Call of Water", kind = "accept", text = "Accept: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.", index = 348},
    {id = "b0132g03", blockID = 132, sourceBlock = 132, sourceGoal = 3, blockTitle = "Brine", sourceKind = "collect", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.443, y = 0.768, coordFrame = "era", continentID = 1, worldX = -3576.3, worldY = -1866.149962, questID = 1535, objectiveIndex = 1, itemID = 7769, itemName = "Filled Brown Waterskin", count = 1, questTitle = "Call of Water", kind = "complete", text = "Collect Filled Brown Waterskin ×1 — Call of Water", detail = "From Quilboar Watering Hole.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.\n\nFill the Empty Brown Waterskin at the quilboar watering hole", index = 349},
    {id = "b0132g04", blockID = 132, sourceBlock = 132, sourceGoal = 4, blockTitle = "Brine", sourceKind = "turnin", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1535, npcID = 5899, npcName = "Brine", questTitle = "Call of Water", kind = "turnin", text = "Turn in: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.", index = 350},
    {id = "b0132g05", blockID = 132, sourceBlock = 132, sourceGoal = 5, blockTitle = "Brine", sourceKind = "accept", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1536, npcID = 5899, npcName = "Brine", minLevel = 20, requiresAny = {1535}, prerequisiteTitles = {["1535"] = "Call of Water"}, questTitle = "Call of Water", kind = "accept", text = "Accept: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo: fill the Empty Brown Waterskin at the watering hole below it.\n\nKeep it: the Spring Well is beside Tarren Mill, on the Hillsbrad guide", index = 351},
    {id = "b0133g01", blockID = 133, sourceBlock = 133, sourceGoal = 1, blockTitle = "Twitching Antennae", sourceKind = "collect", classes = {"WARRIOR"}, uiMapID = 1413, x = 0.4377, y = 0.7296, coordFrame = "era", continentID = 1, worldX = -3316.86, worldY = -1812.4432918, questID = 1824, objectiveIndex = 1, itemID = 7119, itemName = "Twitching Antenna", count = 5, questTitle = "Trial at the Field of Giants", kind = "complete", text = "Collect Twitching Antenna ×5 — Trial at the Field of Giants", detail = "The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the Field of Giants' mounds until you have five, then take them straight to Ruga Ragetotem in Camp Taurajo.\n\nFrom Silithid Creeper.\n\nThe antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the Field of Giants' mounds, just south of Jorn's thunderhawks, until you have five, then take them straight to Ruga Ragetotem in Camp Taurajo.\nCareful: Silithid Swarmers (level 21-22) cast Silithid Swarm both in and out of combat, which brings several small adds. Silithid Creepers (level 20-21) periodically cast Silithid Creeper Egg in combat, which spawns extra adds.\n\nTwitching Antennae from the silithid", index = 352},
    {id = "b0134g01", blockID = 134, sourceBlock = 134, sourceGoal = 1, blockTitle = "Camp Taurajo", sourceKind = "turnin", classes = {"WARRIOR"}, uiMapID = 1413, x = 0.4467, y = 0.5942, coordFrame = "era", continentID = 1, worldX = -2402.06375, worldY = -1903.6432978, worldZ = 96.8, questID = 1824, npcID = 6394, npcName = "Ruga Ragetotem", questTitle = "Trial at the Field of Giants", kind = "turnin", text = "Turn in: Trial at the Field of Giants", detail = "Talk to Ruga Ragetotem.\n\nBack north into Camp Taurajo on the way to the Crossroads: Jorn takes the thunderhawk wings. Warriors: Ruga Ragetotem first, before the antennae fade.\n\nRuga Ragetotem, inside", index = 353},
    {id = "b0134g02", blockID = 134, sourceBlock = 134, sourceGoal = 2, blockTitle = "Camp Taurajo", sourceKind = "accept", classes = {"WARRIOR"}, uiMapID = 1413, x = 0.4467, y = 0.5942, coordFrame = "era", continentID = 1, worldX = -2402.06375, worldY = -1903.6432978, worldZ = 96.8, questID = 1825, npcID = 6394, npcName = "Ruga Ragetotem", minLevel = 20, requiresAny = {1824}, closedBy = {1838}, prerequisiteTitles = {["1824"] = "Trial at the Field of Giants", ["1838"] = "Brutal Armor"}, questTitle = "Speak with Thun'grim", kind = "accept", text = "Accept: Speak with Thun'grim", detail = "Talk to Ruga Ragetotem.\n\nBack north into Camp Taurajo on the way to the Crossroads: Jorn takes the thunderhawk wings. Warriors: Ruga Ragetotem first, before the antennae fade.", index = 354},
    {id = "b0134g03", blockID = 134, sourceBlock = 134, sourceGoal = 3, blockTitle = "Camp Taurajo", sourceKind = "turnin", uiMapID = 1413, x = 0.4486, y = 0.5914, coordFrame = "era", continentID = 1, worldX = -2383.14625, worldY = -1922.8966324, worldZ = 95.9, questID = 913, npcID = 3387, npcName = "Jorn Skyseer", questTitle = "Cry of the Thunderhawk", kind = "turnin", text = "Turn in: Cry of the Thunderhawk", detail = "Talk to Jorn Skyseer.\n\nBack north into Camp Taurajo on the way to the Crossroads: Jorn takes the thunderhawk wings. Warriors: Ruga Ragetotem first, before the antennae fade.", index = 355},
