    {id = "b0135g02", blockID = 135, sourceBlock = 135, sourceGoal = 2, blockTitle = "The Crossroads", sourceKind = "turnin", uiMapID = 1413, x = 0.5107, y = 0.2963, coordFrame = "era", continentID = 1, worldX = -389.376875, worldY = -2552.1766738, worldZ = 99, questID = 868, npcID = 3428, npcName = "Korran", questTitle = "Egg Hunt", kind = "turnin", text = "Turn in: Egg Hunt", detail = "Talk to Korran.\n\nNorth up the Gold Road to the Crossroads: Mankrik stands by the inn, Korran west of the north gate.", index = 357},
    {id = "b0136g01", blockID = 136, sourceBlock = 136, sourceGoal = 1, blockTitle = "Thun'grim Firegaze", sourceKind = "turnin", classes = {"WARRIOR"}, uiMapID = 1413, x = 0.5723, y = 0.3034, coordFrame = "era", continentID = 1, worldX = -437.34625, worldY = -3176.3900482, worldZ = 211.4, questID = 1825, npcID = 5878, npcName = "Thun'grim Firegaze", questTitle = "Speak with Thun'grim", kind = "turnin", text = "Turn in: Speak with Thun'grim", detail = "Talk to Thun'grim Firegaze.\n\nThun'grim camps beside the road east of the Crossroads.", index = 358},
    {id = "b0136g02", blockID = 136, sourceBlock = 136, sourceGoal = 2, blockTitle = "Thun'grim Firegaze", sourceKind = "note", classes = {"WARRIOR"}, kind = "note", manual = true, text = "He offers Brutal Armor next (1838, level 30): it needs Razorfen Kraul and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide Brutal Armor covers it.", detail = "Thun'grim camps beside the road east of the Crossroads.", index = 359},
    {id = "b0137g01", blockID = 137, sourceBlock = 137, sourceGoal = 1, blockTitle = "Regthar Deathgate", sourceKind = "turnin", uiMapID = 1413, x = 0.4534, y = 0.2841, coordFrame = "era", continentID = 1, worldX = -306.950625, worldY = -1971.5366356, worldZ = 96.5, questID = 852, npcID = 3389, npcName = "Regthar Deathgate", questTitle = "Hezrul Bloodmark", kind = "turnin", text = "Turn in: Hezrul Bloodmark", detail = "Talk to Regthar Deathgate.", index = 360},
