    {id = "b0138g01", blockID = 138, sourceBlock = 138, sourceGoal = 1, blockTitle = "Counterattack!", sourceKind = "collect", uiMapID = 1413, x = 0.444, y = 0.281, coordFrame = "era", continentID = 1, worldX = -286.00625, worldY = -1876.283296, questID = 4021, objectiveIndex = 1, itemID = 11227, itemName = "Piece of Krom'zar's Banner", count = 1, questTitle = "Counterattack!", kind = "complete", text = "Collect Piece of Krom'zar's Banner ×1 — Counterattack!", detail = "Speak to Regthar again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until Warlord Krom'zar (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body.", index = 362},
    {id = "b0138g02", blockID = 138, sourceBlock = 138, sourceGoal = 2, blockTitle = "Counterattack!", sourceKind = "turnin", uiMapID = 1413, x = 0.4534, y = 0.2841, coordFrame = "era", continentID = 1, worldX = -306.950625, worldY = -1971.5366356, worldZ = 96.5, questID = 4021, npcID = 3389, npcName = "Regthar Deathgate", questTitle = "Counterattack!", kind = "turnin", text = "Turn in: Counterattack!", detail = "Talk to Regthar Deathgate.\n\nSpeak to Regthar again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until Warlord Krom'zar (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body.", index = 363},
    {id = "b0139g01", blockID = 139, sourceBlock = 139, sourceGoal = 1, blockTitle = "Crossroads flight master", sourceKind = "goto", classes = {"PALADIN"}, uiMapID = 1413, x = 0.515, y = 0.304, coordFrame = "era", continentID = 1, worldX = -441.4, worldY = -2595.75001, kind = "goto", text = "Go to Crossroads flight master", index = 364},
    {id = "b0140g01", blockID = 140, sourceBlock = 140, sourceGoal = 1, blockTitle = "Thunder Bluff", sourceKind = "fly", classes = {"PALADIN"}, location = "Camp Taurajo", nodeID = 77, kind = "flight", mode = "fly", text = "Fly to Camp Taurajo", manual = true, detail = "Alodan the Hopeful teaches Paladins in Thunder Bluff. You have no flight path there yet: fly to Camp Taurajo, head west through Mulgore and up a lift, and take the flight path from Tal on the central rise.", index = 365},
    {id = "b0140g02", blockID = 140, sourceBlock = 140, sourceGoal = 2, blockTitle = "Thunder Bluff", sourceKind = "getfp", classes = {"PALADIN"}, uiMapID = 1456, x = 0.47, y = 0.4983, coordFrame = "era", continentID = 1, worldX = -1196.7335839, worldY = 26.1045, worldZ = 177, npcID = 2995, npcName = "Tal", location = "Thunder Bluff", nodeID = 22, kind = "flight", mode = "learn", text = "Learn the flight path at Thunder Bluff", manual = true, detail = "Alodan the Hopeful teaches Paladins in Thunder Bluff. You have no flight path there yet: fly to Camp Taurajo, head west through Mulgore and up a lift, and take the flight path from Tal on the central rise.", index = 366},
    {id = "b0140g03", blockID = 140, sourceBlock = 140, sourceGoal = 3, blockTitle = "Thunder Bluff", sourceKind = "train", classes = {"PALADIN"}, kind = "train", text = "Train your class abilities", manual = true, detail = "Alodan the Hopeful teaches Paladins in Thunder Bluff. You have no flight path there yet: fly to Camp Taurajo, head west through Mulgore and up a lift, and take the flight path from Tal on the central rise.", index = 367},
