    {id = "b0158g02", blockID = 158, sourceBlock = 158, sourceGoal = 2, blockTitle = "Ziz Fizziks", sourceKind = "accept", uiMapID = 1442, x = 0.5899, y = 0.626, coordFrame = "era", continentID = 1, worldX = 878.2545, worldY = 365.1548633, worldZ = 23.3, questID = 1093, npcID = 4201, npcName = "Ziz Fizziks", minLevel = 16, questTitle = "Super Reaper 6000", kind = "accept", text = "Accept: Super Reaper 6000", detail = "Talk to Ziz Fizziks.\n\nThe road climbs north as the Webwinder Path. Ziz Fizziks has a hut where the road forks east to Windshear Crag.", index = 420},
    {id = "b0159g01", blockID = 159, sourceBlock = 159, sourceGoal = 1, blockTitle = "Windshear Crag", sourceKind = "collect", uiMapID = 1442, x = 0.6251, y = 0.5384, coordFrame = "era", continentID = 1, worldX = 1163.502, worldY = 193.2615417, questID = 1093, objectiveIndex = 1, itemID = 5734, itemName = "Super Reaper 6000 Blueprints", count = 1, questTitle = "Super Reaper 6000", kind = "complete", text = "Collect Super Reaper 6000 Blueprints ×1 — Super Reaper 6000", detail = "From Venture Co. Operator.\n\nEast of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints. Piznik mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended.", index = 421},
    {id = "b0159g02", blockID = 159, sourceBlock = 159, sourceGoal = 2, blockTitle = "Windshear Crag", sourceKind = "kill", uiMapID = 1442, x = 0.6148, y = 0.5534, coordFrame = "era", continentID = 1, worldX = 1114.65825, worldY = 243.5598716, worldZ = 11.9, questID = 1062, objectiveIndex = 1, npcID = 3989, count = 15, questTitle = "Goblin Invaders", kind = "complete", text = "Kill Venture Co. Logger ×15 — Goblin Invaders", detail = "East of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints. Piznik mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended.\n\nVenture Co. Loggers, all over the clear-cut", index = 422},
    {id = "b0159g03", blockID = 159, sourceBlock = 159, sourceGoal = 3, blockTitle = "Windshear Crag", sourceKind = "accept", uiMapID = 1442, x = 0.7187, y = 0.6, coordFrame = "era", continentID = 1, worldX = 962.917, worldY = -263.8184271, worldZ = -5.3, questID = 1090, npcID = 4276, npcName = "Piznik", minLevel = 17, questTitle = "Gerenzo's Orders", kind = "accept", text = "Accept: Gerenzo's Orders", detail = "Piznik's defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone. Piznik mines at the bottom of the Windshear Mine, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.\n\nTalk to Piznik.\n\nEast of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints. Piznik mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended.\n\nPiznik, below ground", index = 423},
