    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Brine", sourceKind = "turnin", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1536, npcID = 5899, npcName = "Brine", questTitle = "Call of Water", kind = "turnin", text = "Turn in: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo, on the way to Bael Modan.\n\nBrine: the red waterskin from Tarren Mill", index = 45},
    {id = "b0014g02", blockID = 14, sourceBlock = 14, sourceGoal = 2, blockTitle = "Brine", sourceKind = "accept", classes = {"SHAMAN"}, uiMapID = 1413, x = 0.4342, y = 0.7741, coordFrame = "era", continentID = 1, worldX = -3617.513125, worldY = -1776.9766228, worldZ = 135.7, questID = 1534, npcID = 5899, npcName = "Brine", minLevel = 20, requiresAny = {1536}, prerequisiteTitles = {["1536"] = "Call of Water"}, questTitle = "Call of Water", kind = "accept", text = "Accept: Call of Water", detail = "Talk to Brine.\n\nBrine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo, on the way to Bael Modan.\n\nBrine: the blue waterskin is filled in Ashenvale, next guide", index = 46},
    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Gann Stonespire", sourceKind = "accept", uiMapID = 1413, x = 0.4589, y = 0.77, coordFrame = "era", continentID = 1, worldX = -3589.8125, worldY = -2027.2699726, worldZ = 91.8, questID = 843, npcID = 3341, npcName = "Gann Stonespire", minLevel = 17, questTitle = "Gann's Reclamation", kind = "accept", text = "Accept: Gann's Reclamation", detail = "Gann walks the road south toward Bael Modan, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. Sulhasa sits up in the tree just east of the road at 47.9,77.5.\n\nTalk to Gann Stonespire.\n\nGann waits in a small camp further south, on the road toward Bael Modan; Sulhasa sits up in the tree just east of him.\n\nGann Stonespire walks around Blackthorn Ridge: look inside the circle on the map", index = 47},
    {id = "b0015g02", blockID = 15, sourceBlock = 15, sourceGoal = 2, blockTitle = "Gann Stonespire", sourceKind = "accept", uiMapID = 1413, x = 0.478, y = 0.776, coordFrame = "era", continentID = 1, worldX = -3630.35, worldY = -2220.816652, questID = 98093, npcID = 14242, npcName = "Sulhasa", minLevel = 18, questTitle = "Field to Clear", kind = "accept", text = "Accept: Field to Clear", detail = "Talk to Sulhasa.\n\nGann waits in a small camp further south, on the road toward Bael Modan; Sulhasa sits up in the tree just east of him.\n\nSulhasa, up in the tree just east of Gann", index = 48},
    {id = "b0016g01", blockID = 16, sourceBlock = 16, sourceGoal = 1, blockTitle = "Bael Modan", sourceKind = "kill", uiMapID = 1413, x = 0.4706, y = 0.8387, coordFrame = "era", continentID = 1, worldX = -4053.966875, worldY = -2145.8299804, worldZ = 90.1, questID = 843, objectiveIndex = 1, npcID = 3374, count = 15, questTitle = "Gann's Reclamation", kind = "complete", text = "Kill Bael'dun Excavator ×15 — Gann's Reclamation", detail = "South of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight.", index = 49},
    {id = "b0016g02", blockID = 16, sourceBlock = 16, sourceGoal = 2, blockTitle = "Bael Modan", sourceKind = "kill", uiMapID = 1413, x = 0.4741, y = 0.8432, coordFrame = "era", continentID = 1, worldX = -4084.37, worldY = -2181.2966494, worldZ = 50.3, questID = 843, objectiveIndex = 2, npcID = 3375, count = 5, questTitle = "Gann's Reclamation", kind = "complete", text = "Kill Bael'dun Foreman ×5 — Gann's Reclamation", detail = "South of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight.\n\nBael'dun Foreman walks around Bael Modan: look inside the circle on the map", index = 50},
    {id = "b0016g03", blockID = 16, sourceBlock = 16, sourceGoal = 3, blockTitle = "Bael Modan", sourceKind = "collect", uiMapID = 1413, x = 0.475, y = 0.8506, coordFrame = "era", continentID = 1, worldX = -4134.36625, worldY = -2190.41665, questID = 843, objectiveIndex = 3, itemID = 5006, itemName = "Khazgorm's Journal", count = 1, questTitle = "Gann's Reclamation", kind = "complete", text = "Collect Khazgorm's Journal ×1 — Gann's Reclamation", detail = "From Prospector Khazgorm.\n\nSouth of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight.", index = 51},
    {id = "b0017g01", blockID = 17, sourceBlock = 17, sourceGoal = 1, blockTitle = "Blackthorn Ridge", sourceKind = "collect", uiMapID = 1413, x = 0.4375, y = 0.8326, coordFrame = "era", continentID = 1, worldX = -4012.75375, worldY = -1810.416625, questID = 879, objectiveIndex = 2, itemID = 5073, itemName = "Nak's Skull", count = 1, questTitle = "Betrayal from Within", kind = "complete", text = "Collect Nak's Skull ×1 — Betrayal from Within", detail = "From Nak.\n\nWest of Gann, the Razormane hold Blackthorn Ridge. Kuz is on the east side, Nak to the south, Lok Orcbane at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; Hagg Taurenbane, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. Washte Pawne, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with Sinister Strike, so they can join a fight without warning.", index = 52},
