    {id = "b0018g01", blockID = 18, sourceBlock = 18, sourceGoal = 1, blockTitle = "Field to Clear", sourceKind = "kill", uiMapID = 1413, x = 0.4528, y = 0.7897, coordFrame = "era", continentID = 1, worldX = -3722.910625, worldY = -1965.4566352, worldZ = 95.2, questID = 98093, objectiveIndex = 1, npcID = 4128, count = 7, questTitle = "Field to Clear", kind = "complete", text = "Kill Hecklefang Stalker ×7 — Field to Clear", detail = "On the way back east to Gann: Hecklefang Stalkers and Stormhide lizards roam the plain between the ridge and his camp.\n\nHecklefang Stalker walks around Southern Barrens: look inside the circle on the map", index = 61},
