    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Zoram'gar Outpost", sourceKind = "getfp", uiMapID = 1440, x = 0.1224, y = 0.338, coordFrame = "era", continentID = 1, worldX = 3373.7295, worldY = 994.1599592, worldZ = 5.4, npcID = 11901, npcName = "Andruk", location = "Zoram'gar Outpost", nodeID = 58, kind = "flight", mode = "learn", text = "Learn the flight path at Zoram'gar Outpost", manual = true, detail = "Head west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.", index = 21},
