    {id = "b0008g03", blockID = 8, sourceBlock = 8, sourceGoal = 3, blockTitle = "Zoram'gar Outpost", sourceKind = "accept", uiMapID = 1440, x = 0.1165, y = 0.3485, coordFrame = "era", continentID = 1, worldX = 3333.370125, worldY = 1028.1832945, worldZ = 6.4, questID = 6462, npcID = 12721, npcName = "Mitsuwa", minLevel = 19, questTitle = "Troll Charm", kind = "accept", text = "Accept: Troll Charm", detail = "Learn the flight path here while you pick up the outpost's quests.\n\nTalk to Mitsuwa.\n\nHead west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.\n\nMitsuwa: the troll charms are in Thistlefur Hold, east of the outpost", index = 23},
    {id = "b0008g04", blockID = 8, sourceBlock = 8, sourceGoal = 4, blockTitle = "Zoram'gar Outpost", sourceKind = "accept", uiMapID = 1440, x = 0.119, y = 0.3454, coordFrame = "era", continentID = 1, worldX = 3345.28575, worldY = 1013.766627, worldZ = 3.4, questID = 216, npcID = 12757, npcName = "Karang Amakkar", minLevel = 21, questTitle = "Between a Rock and a Thistlefur", kind = "accept", text = "Accept: Between a Rock and a Thistlefur", detail = "Talk to Karang Amakkar.\n\nHead west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.", index = 24},
    {id = "b0008g05", blockID = 8, sourceBlock = 8, sourceGoal = 5, blockTitle = "Zoram'gar Outpost", sourceKind = "accept", uiMapID = 1440, x = 0.1206, y = 0.3463, coordFrame = "era", continentID = 1, worldX = 3341.826375, worldY = 1004.5399598, worldZ = 3.9, questID = 6641, npcID = 12717, npcName = "Muglash", minLevel = 20, escort = true, questTitle = "Vorsha the Lasher", kind = "accept", text = "Accept: Vorsha the Lasher", detail = "Talk to Muglash.\n\nHead west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west: Marukai, Mitsuwa and Karang Amakkar stand around it, the Warsong Runner beside the flight master. Its other quests are for the next visit, at 26.\n\nMuglash: take it last, his escort starts at once", index = 25},
    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "Vorsha the Lasher", sourceKind = "goto", uiMapID = 1440, x = 0.096, y = 0.276, coordFrame = "era", continentID = 1, worldX = 3612.042, worldY = 1146.399968, kind = "goto", text = "Go to Naga brazier", detail = "Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads Marukai wants.", index = 26},
