    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Thistlefur Village", sourceKind = "kill", uiMapID = 1440, x = 0.3174, y = 0.38, coordFrame = "era", continentID = 1, worldX = 3212.292, worldY = -130.3401058, worldZ = 106.2, questID = 216, objectiveIndex = 1, npcID = 3925, count = 12, questTitle = "Between a Rock and a Thistlefur", kind = "complete", text = "Kill Thistlefur Avenger ×12 — Between a Rock and a Thistlefur", detail = "East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs.", index = 31},
    {id = "b0012g02", blockID = 12, sourceBlock = 12, sourceGoal = 2, blockTitle = "Thistlefur Village", sourceKind = "kill", uiMapID = 1440, x = 0.321, y = 0.3893, coordFrame = "era", continentID = 1, worldX = 3176.545125, worldY = -151.100107, worldZ = 104.9, questID = 216, objectiveIndex = 2, npcID = 3924, count = 12, questTitle = "Between a Rock and a Thistlefur", kind = "complete", text = "Kill Thistlefur Shaman ×12 — Between a Rock and a Thistlefur", detail = "East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs.", index = 32},
