    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "Beren's Peril", sourceKind = "accept", questID = 95884, itemID = 271343, itemName = "Note Scrap", minLevel = 20, questTitle = "The Offering Stone", kind = "accept", text = "Accept: The Offering Stone", detail = "Use Note Scrap to start this quest.\n\nIn the ruins of Beren's Peril: The Ravenclaw undead haunt the ruins of Beren's Peril east of the road in the south-east of the forest; a Ravenclaw Guardian drops the Note Scrap that leads to the Offering Stone.\n\nNote Scrap, from a Ravenclaw Guardian", index = 61},
