    {id = "b0027g01", blockID = 27, sourceBlock = 27, sourceGoal = 1, blockTitle = "The Offering of Blood", sourceKind = "goto", uiMapID = 1421, x = 0.581, y = 0.698, coordFrame = "era", continentID = 0, worldX = -287.733, worldY = 1009.8, kind = "goto", text = "Go to Offering Stone", detail = "Use the Tortured Soul at the Offering Stone for a willing sacrifice and kill the Tortured Soul that answers. The Tortured Soul is elite: grouping up is advised.", index = 66},
