    {id = "b0002g01", blockID = 2, sourceBlock = 2, sourceGoal = 1, blockTitle = "Serge Hinott", sourceKind = "turnin", classes = {"ROGUE"}, uiMapID = 1424, x = 0.6163, y = 0.1919, coordFrame = "era", continentID = 0, worldX = -9.3866027, worldY = -905.493, worldZ = 57.6, questID = 2479, npcID = 2391, npcName = "Serge Hinott", optional = true, questTitle = "Hinott's Assistance", kind = "turnin", text = "Turn in: Hinott's Assistance", detail = "Talk to Serge Hinott.\n\nAfter returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", index = 11},
    {id = "b0002g02", blockID = 2, sourceBlock = 2, sourceGoal = 2, blockTitle = "Serge Hinott", sourceKind = "accept", classes = {"ROGUE"}, uiMapID = 1424, x = 0.6163, y = 0.1919, coordFrame = "era", continentID = 0, worldX = -9.3866027, worldY = -905.493, worldZ = 57.6, questID = 2480, npcID = 2391, npcName = "Serge Hinott", minLevel = 20, optional = true, requiresAny = {2479}, prerequisiteTitles = {["2479"] = "Hinott's Assistance"}, questTitle = "Hinott's Assistance", kind = "accept", text = "Accept: Hinott's Assistance", detail = "Talk to Serge Hinott.\n\nAfter returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", index = 12},
    {id = "b0002g03", blockID = 2, sourceBlock = 2, sourceGoal = 3, blockTitle = "Serge Hinott", sourceKind = "complete", classes = {"ROGUE"}, questID = 2480, optional = true, questTitle = "Hinott's Assistance", kind = "complete", text = "Complete: Hinott's Assistance", detail = "Cure Completed.\n\nAfter returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", index = 13, objectiveTargets = {{kind = "complete", questID = 2480, questTitle = "Hinott's Assistance", objectiveIndex = 1, blockTitle = "Serge Hinott", sourceKind = "event", text = "Complete: Hinott's Assistance", uiMapID = 1424, x = 0.616, y = 0.192, coordFrame = "era", continentID = 0, worldX = -9.599936000000014, worldY = -904.5330000000001, navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
    {id = "b0002g04", blockID = 2, sourceBlock = 2, sourceGoal = 4, blockTitle = "Serge Hinott", sourceKind = "turnin", classes = {"ROGUE"}, uiMapID = 1424, x = 0.6163, y = 0.1919, coordFrame = "era", continentID = 0, worldX = -9.3866027, worldY = -905.493, worldZ = 57.6, questID = 2480, npcID = 2391, npcName = "Serge Hinott", optional = true, questTitle = "Hinott's Assistance", kind = "turnin", text = "Turn in: Hinott's Assistance", detail = "Talk to Serge Hinott.\n\nAfter returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.\n\nSerge Hinott: Poisons", index = 14, objectiveTargets = {{kind = "complete", questID = 2480, questTitle = "Hinott's Assistance", objectiveIndex = 1, blockTitle = "Serge Hinott", sourceKind = "event", text = "Complete: Hinott's Assistance", uiMapID = 1424, x = 0.616, y = 0.192, coordFrame = "era", continentID = 0, worldX = -9.599936000000014, worldY = -904.5330000000001, navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
    {id = "b0002g05", blockID = 2, sourceBlock = 2, sourceGoal = 5, blockTitle = "Serge Hinott", sourceKind = "note", classes = {"ROGUE"}, kind = "note", manual = true, text = "Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide.", detail = "After returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", index = 15},
    {id = "b0003g01", blockID = 3, sourceBlock = 3, sourceGoal = 1, blockTitle = "Bears, creepers and lions", sourceKind = "collect", uiMapID = 1424, x = 0.543, y = 0.396, coordFrame = "era", continentID = 0, worldX = -444.799868, worldY = -670.933, questID = 496, objectiveIndex = 1, itemID = 3476, itemName = "Gray Bear Tongue", count = 10, questTitle = "Elixir of Suffering", kind = "complete", text = "Collect Gray Bear Tongue ×10 — Elixir of Suffering", detail = "Sources: Vicious Gray Bear, Gray Bear.\n\nWest of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop Creeper Ichor rarely; you need only one.", index = 16},
    {id = "b0003g02", blockID = 3, sourceBlock = 3, sourceGoal = 2, blockTitle = "Bears, creepers and lions", sourceKind = "collect", uiMapID = 1424, x = 0.59, y = 0.3534, coordFrame = "era", continentID = 0, worldX = -353.9198822, worldY = -821.333, questID = 496, objectiveIndex = 2, itemID = 3477, itemName = "Creeper Ichor", count = 1, questTitle = "Elixir of Suffering", kind = "complete", text = "Collect Creeper Ichor ×1 — Elixir of Suffering", detail = "Sources: Forest Moss Creeper, Creepthess.\n\nWest of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop Creeper Ichor rarely; you need only one.", index = 17},
