    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Gloomrise: kill these as you meet them", sourceKind = "collect", uiMapID = 1412, x = 0.3328, y = 0.146, coordFrame = "live", questID = 96260, objectiveIndex = 1, itemID = 273181, itemName = "Crystalline Silk", count = 3, questTitle = "Stronger than Steel", kind = "complete", text = "Collect Crystalline Silk ×3 — Stronger than Steel", detail = "From Gloomrise Spinner.\n\nNorth of the camp, spiders overrun the burial ground at Gloomrise. Use Mazu'kon's Toxin Extractor on the Gnawed Corpses; the Spinners drop the Crystalline Silk. Broodmother Valraxx sits at the north end: her Bloody Parchment starts A Darker Truth.\n\nCrystalline Silk, from Gloomrise Spinners", index = 59},
