    {id = "b0042g07", blockID = 42, sourceBlock = 42, sourceGoal = 7, blockTitle = "Freewind Post", sourceKind = "accept", uiMapID = 1441, x = 0.4621, y = 0.5151, coordFrame = "era", continentID = 1, worldX = -5477.6268283, worldY = -2466.573, worldZ = 89.4, questID = 98070, npcID = 4877, npcName = "Jandia", minLevel = 25, questTitle = "Stop the Screeching", kind = "accept", text = "Accept: Stop the Screeching", detail = "Talk to Jandia.\n\nRide the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side.\n\nJandia, the trade supplies vendor: the Screeching harpies of Roguefeather Den; inside the inn", index = 89},
    {id = "b0042g08", blockID = 42, sourceBlock = 42, sourceGoal = 8, blockTitle = "Freewind Post", sourceKind = "accept", uiMapID = 1441, x = 0.4621, y = 0.5151, coordFrame = "era", continentID = 1, worldX = -5477.6268283, worldY = -2466.573, worldZ = 89.4, questID = 98069, npcID = 4877, npcName = "Jandia", minLevel = 25, questTitle = "Stolen Freewind Supplies", kind = "accept", text = "Accept: Stolen Freewind Supplies", detail = "Talk to Jandia.\n\nRide the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side.\n\nJandia: her stolen supplies lie in the same harpy den", index = 90},
