    {id = "b0044g01", blockID = 44, sourceBlock = 44, sourceGoal = 1, blockTitle = "Galak centaurs", sourceKind = "kill", uiMapID = 1441, x = 0.4553, y = 0.4354, coordFrame = "era", continentID = 1, worldX = -5243.8401882, worldY = -2436.653, questID = 4841, objectiveIndex = 1, npcID = 4094, count = 12, questTitle = "Pacify the Centaur", kind = "complete", text = "Kill Galak Scout ×12 — Pacify the Centaur", detail = "The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone Galak Messenger walks between the camps: kill him when you meet him, his note starts a quest for Whitereach Post.", index = 93},
