    {id = "b0048g01", blockID = 48, sourceBlock = 48, sourceGoal = 1, blockTitle = "Darkcloud Pinnacle", sourceKind = "interact", uiMapID = 1441, x = 0.318, y = 0.326, coordFrame = "era", continentID = 1, worldX = -4922.933558, worldY = -1832.533, worldZ = 80.8, questID = 5064, objectiveIndex = 1, objectID = 176344, objectName = "Document Chest", questTitle = "Grimtotem Spying", kind = "complete", text = "Interact with Document Chest — Grimtotem Spying", detail = "West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.\n\nDocument Chest, north-west camp", index = 107},
