    {id = "b0048g03", blockID = 48, sourceBlock = 48, sourceGoal = 3, blockTitle = "Darkcloud Pinnacle", sourceKind = "interact", uiMapID = 1441, x = 0.3934, y = 0.4153, coordFrame = "era", continentID = 1, worldX = -5184.8801949, worldY = -2164.293, questID = 5064, objectiveIndex = 3, objectID = 190484, objectName = "Document Chest", questTitle = "Grimtotem Spying", kind = "complete", text = "Interact with Document Chest — Grimtotem Spying", detail = "West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.\n\nDocument Chest, south-east camp", index = 109},
    {id = "b0049g01", blockID = 49, sourceBlock = 49, sourceGoal = 1, blockTitle = "Level 28.9", sourceKind = "goto", uiMapID = 1441, x = 0.338, y = 0.4, coordFrame = "era", continentID = 1, worldX = -5140.0002, worldY = -1920.533, conditions = {{frac = 0.9, k = "level", n = 28, op = "<"}}, kind = "goto", text = "Go to Grimtotem camps below Darkcloud Pinnacle", detail = "Short of 28.9? The Grimtotem around these camps (27-29) are the right level: kill a few more before the climb to Lakota. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Razorfen Kraul dungeon instead.", index = 110},
    {id = "b0049g02", blockID = 49, sourceBlock = 49, sourceGoal = 2, blockTitle = "Level 28.9", sourceKind = "level", conditions = {{frac = 0.9, k = "level", n = 28, op = "<"}}, kind = "level", level = 28, levelFraction = 0.9, text = "Reach level 28 + 90% XP", detail = "Short of 28.9? The Grimtotem around these camps (27-29) are the right level: kill a few more before the climb to Lakota. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon or the Razorfen Kraul dungeon instead.\n\ngrind on the Grimtotem below Darkcloud Pinnacle", index = 111},
    {id = "b0050g01", blockID = 50, sourceBlock = 50, sourceGoal = 1, blockTitle = "Lakota Windsong", sourceKind = "collect", uiMapID = 1441, x = 0.381, y = 0.269, coordFrame = "era", continentID = 1, worldX = -4755.733577, worldY = -2109.733, questID = 5147, objectiveIndex = 1, itemID = 12884, itemName = "Arnak's Hoof", count = 1, questTitle = "WANTED: Arnak Grimtotem", kind = "complete", text = "Collect Arnak's Hoof ×1 — WANTED: Arnak Grimtotem", detail = "From Arnak Grimtotem.\n\nClimb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", index = 112},
    {id = "b0050g02", blockID = 50, sourceBlock = 50, sourceGoal = 2, blockTitle = "Lakota Windsong", sourceKind = "accept", uiMapID = 1441, x = 0.3795, y = 0.2645, coordFrame = "era", continentID = 1, worldX = -4742.5335785, worldY = -2103.133, worldZ = 83.7, questID = 4904, npcID = 10646, npcName = "Lakota Windsong", minLevel = 25, escort = true, questTitle = "Free at Last", kind = "accept", text = "Accept: Free at Last", detail = "Talk to Lakota Windsong.\n\nClimb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", index = 113},
    {id = "b0050g03", blockID = 50, sourceBlock = 50, sourceGoal = 3, blockTitle = "Lakota Windsong", sourceKind = "complete", questID = 4904, escort = true, questTitle = "Free at Last", kind = "complete", text = "Complete: Free at Last", detail = "Escort Lakota Windsong from the Darkcloud Pinnacle..\n\nClimb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", index = 114, objectiveTargets = {{kind = "complete", questID = 4904, questTitle = "Free at Last", objectiveIndex = 1, blockTitle = "Lakota Windsong", sourceKind = "event", text = "Complete: Free at Last", uiMapID = 1441, x = 0.309, y = 0.371, coordFrame = "era", continentID = 1, worldX = -5054.933543, worldY = -1792.933, navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
    {id = "b0051g01", blockID = 51, sourceBlock = 51, sourceGoal = 1, blockTitle = "Highperch", sourceKind = "collect", uiMapID = 1441, x = 0.1802, y = 0.4168, coordFrame = "era", continentID = 1, worldX = -5189.2801944, worldY = -1226.213, questID = 4767, objectiveIndex = 1, itemID = 12356, itemName = "Highperch Wyvern Egg", count = 10, questTitle = "Wind Rider", kind = "complete", text = "Collect Highperch Wyvern Egg ×10 — Wind Rider", detail = "From Highperch Wyvern Egg.\n\nWest of Whitereach the wyverns nest on the Highperch cliffs; the eggs lie in the nests. Pao'ka Swiftmountain waits on the east side of the nesting grounds: free him and keep him alive on the walk back to Whitereach Post.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom.", index = 115},
