    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Henchman Valik", sourceKind = "accept", uiMapID = 1416, x = 0.5717, y = 0.6951, coordFrame = "era", continentID = 0, worldX = 202.4797683, worldY = -817.427, worldZ = 151.2, questID = 535, npcID = 2333, npcName = "Henchman Valik", minLevel = 29, questTitle = "Valik", kind = "accept", text = "Accept: Valik", detail = "Talk to Henchman Valik.\n\nFollow the road north out of Tarren Mill into the Alterac foothills. Valik waits by the Syndicate camp; hand him the stout.", index = 38},
    {id = "b0021g01", blockID = 21, sourceBlock = 21, sourceGoal = 1, blockTitle = "Syndicate missives", sourceKind = "collect", uiMapID = 1416, x = 0.576, y = 0.6854, coordFrame = "era", continentID = 0, worldX = 220.5864382, worldY = -829.467, questID = 533, objectiveIndex = 1, itemID = 3601, itemName = "Syndicate Missive", count = 1, questTitle = "Infiltration", kind = "complete", text = "Collect Syndicate Missive ×1 — Infiltration", detail = "The Syndicate Footpads and Thieves (32-34) around the camps west of the road carry the missives; about one in three drops one.\n\nSources: Syndicate Thief, Syndicate Footpad.\n\nThe Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one.", index = 39},
    {id = "b0022g01", blockID = 22, sourceBlock = 22, sourceGoal = 1, blockTitle = "Henchman Valik", sourceKind = "turnin", uiMapID = 1416, x = 0.5717, y = 0.6951, coordFrame = "era", continentID = 0, worldX = 202.4797683, worldY = -817.427, worldZ = 151.2, questID = 535, npcID = 2333, npcName = "Henchman Valik", questTitle = "Valik", kind = "turnin", text = "Turn in: Valik", detail = "Talk to Henchman Valik.", index = 40},
    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Hillsbrad Foothills", sourceKind = "goto", uiMapID = 1424, x = 0.615, y = 0.209, coordFrame = "era", continentID = 0, worldX = -45.866597, worldY = -901.333, kind = "goto", text = "Go to Hillsbrad Foothills", index = 41},
    {id = "b0024g01", blockID = 24, sourceBlock = 24, sourceGoal = 1, blockTitle = "Helcular's Rod", sourceKind = "collect", uiMapID = 1424, x = 0.474, y = 0.3088, coordFrame = "era", continentID = 0, worldX = -258.7732304, worldY = -450.133, questID = 552, objectiveIndex = 1, itemID = 3708, itemName = "Helcular's Rod", count = 1, questTitle = "Helcular's Revenge", kind = "complete", text = "Collect Helcular's Rod ×1 — Helcular's Revenge", detail = "South-west, the Cave and Ferocious Yetis (30-32) fill the Foothill Caverns in the hills west of Tarren Mill; about one in sixteen carries the rod.\n\nSources: Cave Yeti, Ferocious Yeti, Mountain Yeti, Giant Yeti.\n\nSouth-west, the Cave and Ferocious Yetis (30-31) fill the Foothill Caverns in the hills west of Tarren Mill; about one in sixteen carries the rod.", index = 42},
    {id = "b0025g01", blockID = 25, sourceBlock = 25, sourceGoal = 1, blockTitle = "Level 30", sourceKind = "goto", uiMapID = 1424, x = 0.44, y = 0.28, coordFrame = "era", continentID = 0, worldX = -197.33324, worldY = -341.333, conditions = {{k = "level", n = 30, op = "<"}}, kind = "goto", text = "Go to Foothill Caverns", detail = "Tarren Mill's Prison Break In, Stone Tokens and The Hammer May Fall are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.", index = 43},
    {id = "b0025g02", blockID = 25, sourceBlock = 25, sourceGoal = 2, blockTitle = "Level 30", sourceKind = "level", conditions = {{k = "level", n = 30, op = "<"}}, kind = "level", level = 30, levelFraction = 0, text = "Reach level 30", detail = "Tarren Mill's Prison Break In, Stone Tokens and The Hammer May Fall are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the Scarlet Monastery dungeon (Graveyard) or the Blackfathom Deeps dungeon instead.\n\ngrind on Cave Yeti", index = 44},
    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "Town hall", sourceKind = "kill", uiMapID = 1424, x = 0.3206, y = 0.4243, coordFrame = "era", continentID = 0, worldX = -505.1731919, worldY = 40.747, worldZ = 51.1, questID = 532, objectiveIndex = 2, npcID = 2387, count = 5, questTitle = "Battle of Hillsbrad", kind = "complete", text = "Kill Hillsbrad Councilman ×5 — Battle of Hillsbrad", detail = "On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", index = 45},
    {id = "b0026g02", blockID = 26, sourceBlock = 26, sourceGoal = 2, blockTitle = "Town hall", sourceKind = "interact", uiMapID = 1424, x = 0.2973, y = 0.4175, coordFrame = "era", continentID = 0, worldX = -490.6665275, worldY = 115.307, worldZ = 61.5, questID = 532, objectiveIndex = 3, objectID = 1761, objectName = "Hillsbrad Proclamation", questTitle = "Battle of Hillsbrad", kind = "complete", text = "Interact with Hillsbrad Proclamation — Battle of Hillsbrad", detail = "On to Hillsbrad town, south-west of the yeti caves. The town hall is on the town's west side: Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.\n\nHillsbrad Proclamation, inside", index = 46},
