    {id = "b0017g01", blockID = 17, sourceBlock = 17, sourceGoal = 1, blockTitle = "The Rustmaul Dig Site", sourceKind = "kill", uiMapID = 1441, x = 0.698, y = 0.833, coordFrame = "era", continentID = 1, worldX = -6410.133389, worldY = -3504.533, questID = 1147, objectiveIndex = 1, npcID = 4130, count = 5, questTitle = "The Swarm Grows", kind = "complete", text = "Kill Silithid Searcher ×5 — The Swarm Grows", detail = "West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", index = 31},
    {id = "b0017g02", blockID = 17, sourceBlock = 17, sourceGoal = 2, blockTitle = "The Rustmaul Dig Site", sourceKind = "kill", uiMapID = 1441, x = 0.68, y = 0.857, coordFrame = "era", continentID = 1, worldX = -6480.533381, worldY = -3425.333, worldZ = -70, questID = 1147, objectiveIndex = 2, npcID = 4133, count = 5, questTitle = "The Swarm Grows", kind = "complete", text = "Kill Silithid Hive Drone ×5 — The Swarm Grows", detail = "West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", index = 32},
