    {id = "b0017g04", blockID = 17, sourceBlock = 17, sourceGoal = 4, blockTitle = "The Rustmaul Dig Site", sourceKind = "collect", uiMapID = 1441, x = 0.6448, y = 0.8583, coordFrame = "era", continentID = 1, worldX = -6484.3467139, worldY = -3270.453, itemID = 5877, itemName = "Cracked Silithid Carapace", count = 1, kind = "note", manual = true, text = "Collect Cracked Silithid Carapace ×1", detail = "West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", index = 34},
    {id = "b0017g05", blockID = 17, sourceBlock = 17, sourceGoal = 5, blockTitle = "The Rustmaul Dig Site", sourceKind = "accept", questID = 1148, itemID = 5877, itemName = "Cracked Silithid Carapace", minLevel = 28, requiresAny = {1146}, prerequisiteTitles = {["1146"] = "The Swarm Grows"}, questTitle = "Parts of the Swarm", kind = "accept", text = "Accept: Parts of the Swarm", detail = "Use Cracked Silithid Carapace to start this quest.\n\nWest of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a Cracked Silithid Carapace: open it.\nCareful: Hive Drones call for help when they fall to 20% health.", index = 35},
    {id = "b0018g01", blockID = 18, sourceBlock = 18, sourceGoal = 1, blockTitle = "Parts of the Swarm", sourceKind = "collect", uiMapID = 1441, x = 0.6448, y = 0.8583, coordFrame = "era", continentID = 1, worldX = -6484.3467139, worldY = -3270.453, questID = 1148, objectiveIndex = 1, itemID = 5855, itemName = "Silithid Heart", count = 1, questTitle = "Parts of the Swarm", kind = "complete", text = "Collect Silithid Heart ×1 — Parts of the Swarm", detail = "Sources: Silithid Hive Drone, Silithid Searcher, Silithid Invader, Silithid Ravager.\n\nKeep killing silithid at the dig site for the heart, the talons and the carapaces.", index = 36},
    {id = "b0018g02", blockID = 18, sourceBlock = 18, sourceGoal = 2, blockTitle = "Parts of the Swarm", sourceKind = "collect", uiMapID = 1441, x = 0.6448, y = 0.8583, coordFrame = "era", continentID = 1, worldX = -6484.3467139, worldY = -3270.453, questID = 1148, objectiveIndex = 2, itemID = 5854, itemName = "Silithid Talon", count = 5, questTitle = "Parts of the Swarm", kind = "complete", text = "Collect Silithid Talon ×5 — Parts of the Swarm", detail = "From Silithid Searcher.\n\nKeep killing silithid at the dig site for the heart, the talons and the carapaces.", index = 37},
    {id = "b0018g03", blockID = 18, sourceBlock = 18, sourceGoal = 3, blockTitle = "Parts of the Swarm", sourceKind = "collect", uiMapID = 1441, x = 0.6448, y = 0.8583, coordFrame = "era", continentID = 1, worldX = -6484.3467139, worldY = -3270.453, questID = 1148, objectiveIndex = 3, itemID = 5853, itemName = "Intact Silithid Carapace", count = 3, questTitle = "Parts of the Swarm", kind = "complete", text = "Collect Intact Silithid Carapace ×3 — Parts of the Swarm", detail = "From Silithid Searcher.\n\nKeep killing silithid at the dig site for the heart, the talons and the carapaces.", index = 38},
    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Moktar Krin", sourceKind = "turnin", uiMapID = 1441, x = 0.6758, y = 0.6394, coordFrame = "era", continentID = 1, worldX = -5842.2401202, worldY = -3406.853, worldZ = -50.8, questID = 1147, npcID = 4483, npcName = "Moktar Krin", questTitle = "The Swarm Grows", kind = "turnin", text = "Turn in: The Swarm Grows", detail = "Talk to Moktar Krin.\n\nNorth from the dig to Moktar Krin's camp on the western edge of the flats.", index = 39},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Shimmering Flats: kill these as you meet them", sourceKind = "kill", uiMapID = 1441, x = 0.757, y = 0.573, coordFrame = "era", continentID = 1, worldX = -5647.466809, worldY = -3764.133, worldZ = -58.6, questID = 1175, objectiveIndex = 1, npcID = 4147, count = 10, questTitle = "A Bump in the Road", kind = "complete", text = "Kill Saltstone Basilisk ×10 — A Bump in the Road", detail = "East onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.", index = 40},
    {id = "b0020g02", blockID = 20, sourceBlock = 20, sourceGoal = 2, blockTitle = "Shimmering Flats: kill these as you meet them", sourceKind = "collect", uiMapID = 1441, x = 0.821, y = 0.55, coordFrame = "era", continentID = 1, worldX = -5580.00015, worldY = -4045.733, questID = 1105, objectiveIndex = 1, itemID = 5795, itemName = "Hardened Tortoise Shell", count = 9, questTitle = "Hardened Shells", kind = "complete", text = "Collect Hardened Tortoise Shell ×9 — Hardened Shells", detail = "Sources: Sparkleshell Snapper, Sparkleshell Tortoise.\n\nEast onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.", index = 41},
    {id = "b0020g03", blockID = 20, sourceBlock = 20, sourceGoal = 3, blockTitle = "Shimmering Flats: kill these as you meet them", sourceKind = "collect", uiMapID = 1441, x = 0.879, y = 0.654, coordFrame = "era", continentID = 1, worldX = -5885.066782, worldY = -4300.933, questID = 1176, objectiveIndex = 1, itemID = 5848, itemName = "Hollow Vulture Bone", count = 10, questTitle = "Load Lightening", kind = "complete", text = "Collect Hollow Vulture Bone ×10 — Load Lightening", detail = "From Salt Flats Scavenger.\n\nEast onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.", index = 42},
    {id = "b0020g04", blockID = 20, sourceBlock = 20, sourceGoal = 4, blockTitle = "Shimmering Flats: kill these as you meet them", sourceKind = "collect", uiMapID = 1441, x = 0.8886, y = 0.665, coordFrame = "era", continentID = 1, worldX = -5917.333445, worldY = -4343.173, questID = 1110, objectiveIndex = 1, itemID = 5798, itemName = "Rocket Car Parts", count = 30, questTitle = "Rocket Car Parts", kind = "complete", text = "Collect Rocket Car Parts ×30 — Rocket Car Parts", detail = "From Rocket Car Rubble.\n\nEast onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.\n\nRocket Car Rubble, all over the northern flats", index = 43},
    {id = "b0020g05", blockID = 20, sourceBlock = 20, sourceGoal = 5, blockTitle = "Shimmering Flats: kill these as you meet them", sourceKind = "collect", uiMapID = 1441, x = 0.8821, y = 0.6902, coordFrame = "era", continentID = 1, worldX = -5991.2534366, worldY = -4314.573, questID = 1104, objectiveIndex = 1, itemID = 5794, itemName = "Salty Scorpid Venom", count = 6, questTitle = "Salt Flat Venom", kind = "complete", text = "Collect Salty Scorpid Venom ×6 — Salt Flat Venom", detail = "Sources: Scorpid Terror, Scorpid Reaver.\n\nEast onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises.\n\nSalt Flat Venom, from the Scorpid Reavers of the north half", index = 44},
    {id = "b0021g01", blockID = 21, sourceBlock = 21, sourceGoal = 1, blockTitle = "Level 32.5", sourceKind = "goto", uiMapID = 1441, x = 0.71, y = 0.78, coordFrame = "era", continentID = 1, worldX = -6254.66674, worldY = -3557.333, conditions = {{frac = 0.5, k = "level", n = 32, op = "<"}}, kind = "goto", text = "Go to Sparkleshell Snappers", detail = "Desolace's quests are 33-38. Below 32.5? Keep killing the Sparkleshell Snappers near the silithid dig and the Saltstone Gazers south of it until level 32.5. Or, with a group, run the Scarlet Monastery dungeon (Graveyard or Library) instead.", index = 45},
    {id = "b0021g02", blockID = 21, sourceBlock = 21, sourceGoal = 2, blockTitle = "Level 32.5", sourceKind = "level", conditions = {{frac = 0.5, k = "level", n = 32, op = "<"}}, kind = "level", level = 32, levelFraction = 0.5, text = "Reach level 32 + 50% XP", detail = "Desolace's quests are 33-38. Below 32.5? Keep killing the Sparkleshell Snappers near the silithid dig and the Saltstone Gazers south of it until level 32.5. Or, with a group, run the Scarlet Monastery dungeon (Graveyard or Library) instead.\n\ngrind on Sparkleshell Snapper", index = 46},
