    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Kodo Graveyard", sourceKind = "goto", uiMapID = 1443, x = 0.52, y = 0.575, coordFrame = "era", continentID = 1, worldX = -1271.7187, worldY = 1895.49984, kind = "goto", text = "Go to Kodo Graveyard", detail = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", index = 67},
    {id = "b0028g02", blockID = 28, sourceBlock = 28, sourceGoal = 2, blockTitle = "Kodo Graveyard", sourceKind = "complete", questID = 5561, startItemID = 13892, startItemName = "Kodo Kombobulator", questTitle = "Kodo Roundup", kind = "complete", text = "Complete: Kodo Roundup", detail = "Aged Kodo ×5.\n\nUse Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", index = 68, objectiveTargets = {{kind = "complete", questID = 5561, questTitle = "Kodo Roundup", objectiveIndex = 1, blockTitle = "Kodo Graveyard", sourceKind = "kill", npcID = 4700, text = "Quest target: Aged Kodo x5", uiMapID = 1443, x = 0.531, y = 0.5710000000000001, coordFrame = "era", continentID = 1, worldX = -1259.7270360000002, worldY = 1846.0456769999996, navigationHint = "Recorded spawn or collection area. Search nearby; this marker does not track a moving NPC.", approximate = true}}},
    {id = "b0029g01", blockID = 29, sourceBlock = 29, sourceGoal = 1, blockTitle = "Scrabblescrew's Camp", sourceKind = "turnin", uiMapID = 1443, x = 0.6086, y = 0.6186, coordFrame = "era", continentID = 1, worldX = -1402.4278376, worldY = 1497.1690362, worldZ = 61.4, questID = 5561, npcID = 11596, npcName = "Smeed Scrabblescrew", questTitle = "Kodo Roundup", kind = "turnin", text = "Turn in: Kodo Roundup", detail = "Talk to Smeed Scrabblescrew.", index = 69, objectiveTargets = {{kind = "complete", questID = 5561, questTitle = "Kodo Roundup", objectiveIndex = 1, blockTitle = "Kodo Graveyard", sourceKind = "kill", npcID = 4700, text = "Quest target: Aged Kodo x5", uiMapID = 1443, x = 0.531, y = 0.5710000000000001, coordFrame = "era", continentID = 1, worldX = -1259.7270360000002, worldY = 1846.0456769999996, navigationHint = "Recorded spawn or collection area. Search nearby; this marker does not track a moving NPC.", approximate = true}}},
    {id = "b0030g01", blockID = 30, sourceBlock = 30, sourceGoal = 1, blockTitle = "Level 33", sourceKind = "goto", uiMapID = 1443, x = 0.599, y = 0.546, coordFrame = "era", continentID = 1, worldX = -1184.779136, worldY = 1540.329033, conditions = {{k = "level", n = 33, op = "<"}}, kind = "goto", text = "Go to Scorpashi Lashers", detail = "Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", index = 70},
    {id = "b0030g02", blockID = 30, sourceBlock = 30, sourceGoal = 2, blockTitle = "Level 33", sourceKind = "level", conditions = {{k = "level", n = 33, op = "<"}}, kind = "level", level = 33, levelFraction = 0, text = "Reach level 33", detail = "Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.\n\ngrind on Scorpashi Lasher", index = 71},
    {id = "b0031g01", blockID = 31, sourceBlock = 31, sourceGoal = 1, blockTitle = "Shadowprey Village", sourceKind = "accept", uiMapID = 1443, x = 0.2535, y = 0.6717, coordFrame = "era", continentID = 1, worldX = -1561.6171772, worldY = 3093.6393345, questID = 97265, npcID = 268705, npcName = "Aka'rai", minLevel = 28, questTitle = "Hate the Hatefury", kind = "accept", text = "Accept: Hate the Hatefury", detail = "Aka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it.\n\nTalk to Aka'rai.\n\nHead west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\n\nAka'rai: the Hatefury satyrs of Sargeron, later in this guide", index = 72},
    {id = "b0031g02", blockID = 31, sourceBlock = 31, sourceGoal = 2, blockTitle = "Shadowprey Village", sourceKind = "getfp", uiMapID = 1443, x = 0.216, y = 0.7413, coordFrame = "era", continentID = 1, worldX = -1770.2721308, worldY = 3262.233072, worldZ = 5.1, npcID = 6726, npcName = "Thalon", location = "Shadowprey Village", nodeID = 38, kind = "flight", mode = "learn", text = "Learn the flight path at Shadowprey Village", manual = true, detail = "Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.", index = 73},
    {id = "b0031g03", blockID = 31, sourceBlock = 31, sourceGoal = 3, blockTitle = "Shadowprey Village", sourceKind = "accept", uiMapID = 1443, x = 0.2332, y = 0.7287, coordFrame = "era", continentID = 1, worldX = -1732.4983892, worldY = 3184.9047444, worldZ = 4.1, questID = 6143, npcID = 12340, npcName = "Drulzegar Skraghook", minLevel = 32, questTitle = "Other Fish to Fry", kind = "accept", text = "Accept: Other Fish to Fry", detail = "Talk to Drulzegar Skraghook.\n\nHead west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.", index = 74},
    {id = "b0031g04", blockID = 31, sourceBlock = 31, sourceGoal = 4, blockTitle = "Shadowprey Village", sourceKind = "accept", uiMapID = 1443, x = 0.2264, y = 0.7197, coordFrame = "era", continentID = 1, worldX = -1705.5171452, worldY = 3215.4764088, worldZ = 8, questID = 6142, npcID = 12031, npcName = "Mai'Lahii", minLevel = 31, questTitle = "Clam Bait", kind = "accept", text = "Accept: Clam Bait", detail = "Talk to Mai'Lahii.\n\nHead west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.", index = 75},
    {id = "b0031g05", blockID = 31, sourceBlock = 31, sourceGoal = 5, blockTitle = "Shadowprey Village", sourceKind = "accept", uiMapID = 1443, x = 0.2582, y = 0.6821, coordFrame = "era", continentID = 1, worldX = -1592.7955036, worldY = 3072.5089194, worldZ = 49.1, questID = 5381, npcID = 11624, npcName = "Taiga Wisemane", minLevel = 32, questTitle = "Hand of Iruxos", kind = "accept", text = "Accept: Hand of Iruxos", detail = "Talk to Taiga Wisemane.\n\nHead west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.", index = 76},
    {id = "b0031g06", blockID = 31, sourceBlock = 31, sourceGoal = 6, blockTitle = "Shadowprey Village", sourceKind = "accept", uiMapID = 1443, x = 0.2505, y = 0.7227, coordFrame = "era", continentID = 1, worldX = -1714.5108932, worldY = 3107.1268335, worldZ = 33.6, questID = 5763, npcID = 11877, npcName = "Roon Wildmane", minLevel = 28, questTitle = "Hunting in Stranglethorn", kind = "accept", text = "Accept: Hunting in Stranglethorn", detail = "Talk to Roon Wildmane.\n\nHead west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\n\nRoon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide", index = 77},
    {id = "b0031g07", blockID = 31, sourceBlock = 31, sourceGoal = 7, blockTitle = "Shadowprey Village", sourceKind = "sethome", uiMapID = 1443, x = 0.2409, y = 0.6821, coordFrame = "era", continentID = 1, worldX = -1592.7955036, worldY = 3150.2868303, worldZ = 46.6, npcID = 11106, npcName = "Innkeeper Sikewa", location = "Shadowprey Village", kind = "hearth", mode = "bind", text = "Set your Hearthstone to Shadowprey Village", manual = true, detail = "Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.", index = 78},
    {id = "b0032g01", blockID = 32, sourceBlock = 32, sourceGoal = 1, blockTitle = "Clam beds", sourceKind = "collect", uiMapID = 1443, x = 0.3096, y = 0.3575, coordFrame = "era", continentID = 1, worldX = -619.67197, worldY = 2841.4231032, questID = 6142, objectiveIndex = 1, itemID = 15924, itemName = "Soft-shelled Clam Meat", count = 10, questTitle = "Clam Bait", kind = "complete", text = "Collect Soft-shelled Clam Meat ×10 — Clam Bait", detail = "Head north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a Soft-shelled Clam. Open each one in your bags for its meat.\n\nFrom Enraged Reef Crawler.\n\nHead north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat.\n\nUnderwater", index = 79},
    {id = "b0033g01", blockID = 33, sourceBlock = 33, sourceGoal = 1, blockTitle = "Sar'theris Strand", sourceKind = "kill", uiMapID = 1443, x = 0.3218, y = 0.2338, coordFrame = "era", continentID = 1, worldX = -248.8297608, worldY = 2786.5739406, worldZ = 0.8, questID = 6143, objectiveIndex = 1, npcID = 4714, count = 7, questTitle = "Other Fish to Fry", kind = "complete", text = "Kill Slitherblade Myrmidon ×7 — Other Fish to Fry", detail = "Keep north to Sar'theris Strand. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time.", index = 80},
    {id = "b0033g02", blockID = 33, sourceBlock = 33, sourceGoal = 2, blockTitle = "Sar'theris Strand", sourceKind = "kill", uiMapID = 1443, x = 0.3274, y = 0.2392, coordFrame = "era", continentID = 1, worldX = -265.0185072, worldY = 2761.3972758, worldZ = -5.2, questID = 6143, objectiveIndex = 2, npcID = 4711, count = 7, questTitle = "Other Fish to Fry", kind = "complete", text = "Kill Slitherblade Naga ×7 — Other Fish to Fry", detail = "Keep north to Sar'theris Strand. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time.", index = 81},
    {id = "b0033g03", blockID = 33, sourceBlock = 33, sourceGoal = 3, blockTitle = "Sar'theris Strand", sourceKind = "kill", uiMapID = 1443, x = 0.3294, y = 0.2332, coordFrame = "era", continentID = 1, worldX = -247.0310112, worldY = 2752.4056098, worldZ = -5.9, questID = 6143, objectiveIndex = 3, npcID = 4712, count = 5, questTitle = "Other Fish to Fry", kind = "complete", text = "Kill Slitherblade Sorceress ×5 — Other Fish to Fry", detail = "Keep north to Sar'theris Strand. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time.", index = 82},
    {id = "b0034g01", blockID = 34, sourceBlock = 34, sourceGoal = 1, blockTitle = "Ethel Rethor", sourceKind = "accept", uiMapID = 1443, x = 0.3888, y = 0.2716, coordFrame = "era", continentID = 1, worldX = -362.1509856, worldY = 2485.3531296, worldZ = 75.5, questID = 5741, npcID = 11863, npcName = "Azore Aldamort", minLevel = 30, questTitle = "Sceptre of Light", kind = "accept", text = "Accept: Sceptre of Light", detail = "Talk to Azore Aldamort.\n\nAzore Aldamort waits in the ruined tower of Ethel Rethor, inland to the east.", index = 83},
    {id = "b0035g01", blockID = 35, sourceBlock = 35, sourceGoal = 1, blockTitle = "Thunder Axe Fortress", sourceKind = "collect", uiMapID = 1443, x = 0.5208, y = 0.2886, coordFrame = "era", continentID = 1, worldX = -413.1155576, worldY = 1891.9031736, questID = 1435, objectiveIndex = 1, itemID = 6435, itemName = "Infused Burning Gem", count = 15, questTitle = "The Burning of Spirits", kind = "complete", text = "Collect Infused Burning Gem ×15 — The Burning of Spirits", detail = "Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Hand of Iruxos: clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box.\n\nSources: Burning Blade Augur, Burning Blade Reaver, Burning Blade Adept, Burning Blade Felsworn, Burning Blade Shadowmage.\n\nHead east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre; use the Demon Pick on the Demon Spirit for the Demon Box. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.", index = 84},
    {id = "b0035g02", blockID = 35, sourceBlock = 35, sourceGoal = 2, blockTitle = "Thunder Axe Fortress", sourceKind = "collect", uiMapID = 1443, x = 0.552, y = 0.301, coordFrame = "era", continentID = 1, worldX = -450.289716, worldY = 1751.633184, questID = 5741, objectiveIndex = 1, itemID = 15750, itemName = "Sceptre of Light", count = 1, questTitle = "Sceptre of Light", kind = "complete", text = "Collect Sceptre of Light ×1 — Sceptre of Light", detail = "From Burning Blade Seer.\n\nHead east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre; use the Demon Pick on the Demon Spirit for the Demon Box. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.\n\nOn the top floor", index = 85},
    {id = "b0035g03", blockID = 35, sourceBlock = 35, sourceGoal = 3, blockTitle = "Thunder Axe Fortress", sourceKind = "collect", uiMapID = 1443, x = 0.55, y = 0.266, coordFrame = "era", continentID = 1, worldX = -345.362656, worldY = 1760.62485, questID = 5381, objectiveIndex = 1, itemID = 13542, itemName = "Demon Box", count = 1, questTitle = "Hand of Iruxos", kind = "complete", text = "Collect Demon Box ×1 — Hand of Iruxos", detail = "From Demon Spirit.\n\nHead east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre; use the Demon Pick on the Demon Spirit for the Demon Box. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.", index = 86},
    {id = "b0035g04", blockID = 35, sourceBlock = 35, sourceGoal = 4, blockTitle = "Thunder Axe Fortress", sourceKind = "collect", uiMapID = 1443, x = 0.5499, y = 0.2619, coordFrame = "era", continentID = 1, worldX = -333.0712004, worldY = 1761.0744333, itemID = 20310, itemName = "Flayed Demon Skin", count = 1, optional = true, kind = "note", manual = true, text = "Collect Flayed Demon Skin ×1", detail = "Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre; use the Demon Pick on the Demon Spirit for the Demon Box. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.", index = 87},
    {id = "b0035g05", blockID = 35, sourceBlock = 35, sourceGoal = 5, blockTitle = "Thunder Axe Fortress", sourceKind = "accept", questID = 1480, itemID = 20310, itemName = "Flayed Demon Skin", minLevel = 25, optional = true, questTitle = "The Corrupter", kind = "accept", text = "Accept: The Corrupter", detail = "Use Flayed Demon Skin to start this quest.\n\nHead east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre; use the Demon Pick on the Demon Spirit for the Demon Box. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.", index = 88},
    {id = "b0036g01", blockID = 36, sourceBlock = 36, sourceGoal = 1, blockTitle = "Ethel Rethor", sourceKind = "turnin", uiMapID = 1443, x = 0.3888, y = 0.2716, coordFrame = "era", continentID = 1, worldX = -362.1509856, worldY = 2485.3531296, worldZ = 75.5, questID = 5741, npcID = 11863, npcName = "Azore Aldamort", questTitle = "Sceptre of Light", kind = "turnin", text = "Turn in: Sceptre of Light", detail = "Talk to Azore Aldamort.\n\nBack west to Azore.", index = 89},
    {id = "b0036g02", blockID = 36, sourceBlock = 36, sourceGoal = 2, blockTitle = "Ethel Rethor", sourceKind = "accept", uiMapID = 1443, x = 0.3888, y = 0.2716, coordFrame = "era", continentID = 1, worldX = -362.1509856, worldY = 2485.3531296, worldZ = 75.5, questID = 6027, npcID = 11863, npcName = "Azore Aldamort", minLevel = 30, requiresAny = {5741}, prerequisiteTitles = {["5741"] = "Sceptre of Light"}, questTitle = "Book of the Ancients", kind = "accept", text = "Accept: Book of the Ancients", detail = "Talk to Azore Aldamort.\n\nBack west to Azore.", index = 90},
    {id = "b0037g01", blockID = 37, sourceBlock = 37, sourceGoal = 1, blockTitle = "The Book of the Ancients", sourceKind = "collect", uiMapID = 1443, x = 0.2824, y = 0.0667, coordFrame = "era", continentID = 1, worldX = 252.1220028, worldY = 2963.7097608, questID = 6027, objectiveIndex = 1, itemID = 15803, itemName = "Book of the Ancients", count = 1, questTitle = "Book of the Ancients", kind = "complete", text = "Collect Book of the Ancients ×1 — Book of the Ancients", detail = "The Slitherblade naga hold the coast north of Ethel Rethor. Swim out to Ranazjar Isle off the far northern tip and use the Gem of the Serpent on the Serpent Statue: Lord Kragaru (38) rises; kill him for the Book of the Ancients. He is well above you: rest to full first.\n\nFrom Lord Kragaru.\n\nThe Slitherblade naga hold the coast north of Ethel Rethor; Lord Kragaru guards the Book of the Ancients at the far northern tip.", index = 91},
    {id = "b0038g01", blockID = 38, sourceBlock = 38, sourceGoal = 1, blockTitle = "Azore Aldamort", sourceKind = "turnin", uiMapID = 1443, x = 0.3888, y = 0.2716, coordFrame = "era", continentID = 1, worldX = -362.1509856, worldY = 2485.3531296, worldZ = 75.5, questID = 6027, npcID = 11863, npcName = "Azore Aldamort", questTitle = "Book of the Ancients", kind = "turnin", text = "Turn in: Book of the Ancients", detail = "Talk to Azore Aldamort.", index = 92},
    {id = "b0039g01", blockID = 39, sourceBlock = 39, sourceGoal = 1, blockTitle = "Sargeron", sourceKind = "kill", uiMapID = 1443, x = 0.7092, y = 0.1665, coordFrame = "era", continentID = 1, worldX = -47.070014, worldY = 1044.8882364, worldZ = 99.4, questID = 1434, objectiveIndex = 1, npcID = 4670, count = 7, questTitle = "Befouled by Satyr", kind = "complete", text = "Kill Hatefury Rogue ×7 — Befouled by Satyr", detail = "Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", index = 93},
    {id = "b0039g02", blockID = 39, sourceBlock = 39, sourceGoal = 2, blockTitle = "Sargeron", sourceKind = "kill", uiMapID = 1443, x = 0.7152, y = 0.2012, coordFrame = "era", continentID = 1, worldX = -151.0976992, worldY = 1017.9132384, worldZ = 91.3, questID = 1434, objectiveIndex = 2, npcID = 4672, count = 7, questTitle = "Befouled by Satyr", kind = "complete", text = "Kill Hatefury Felsworn ×7 — Befouled by Satyr", detail = "Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", index = 94},
    {id = "b0039g03", blockID = 39, sourceBlock = 39, sourceGoal = 3, blockTitle = "Sargeron", sourceKind = "kill", uiMapID = 1443, x = 0.7225, y = 0.1888, coordFrame = "era", continentID = 1, worldX = -113.9235408, worldY = 985.0936575, worldZ = 89.7, questID = 1434, objectiveIndex = 3, npcID = 4673, count = 7, questTitle = "Befouled by Satyr", kind = "complete", text = "Kill Hatefury Betrayer ×7 — Befouled by Satyr", detail = "Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", index = 95},
    {id = "b0039g04", blockID = 39, sourceBlock = 39, sourceGoal = 4, blockTitle = "Sargeron", sourceKind = "kill", uiMapID = 1443, x = 0.7228, y = 0.1919, coordFrame = "era", continentID = 1, worldX = -123.2170804, worldY = 983.7449076, worldZ = 90.2, questID = 1434, objectiveIndex = 4, npcID = 4675, count = 7, questTitle = "Befouled by Satyr", kind = "complete", text = "Kill Hatefury Hellcaller ×7 — Befouled by Satyr", detail = "Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them.", index = 96},
