    {id = "b0009g05", blockID = 9, sourceBlock = 9, sourceGoal = 5, blockTitle = "Nesingwary's Expedition: kill these as you meet them", sourceKind = "accept", questID = 635, itemID = 4614, itemName = "Pendant of Myzrael", minLevel = 30, optional = true, questTitle = "Crystal in the Mountains", kind = "accept", text = "Accept: Crystal in the Mountains", detail = "Use Pendant of Myzrael to start this quest.\n\nYoung Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it.\nHead west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A Pendant of Myzrael is a very rare drop from them: if one drops, read it.\nCareful: The troll camps have many patrolling mobs, so other trolls often join a fight.", index = 27},
    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "Booty Bay", sourceKind = "accept", uiMapID = 1434, x = 0.2829, y = 0.7759, coordFrame = "era", continentID = 0, worldX = -14469.5573994, worldY = 415.577375, worldZ = 25.5, questID = 575, npcID = 2495, npcName = "Drizzlik", minLevel = 26, questTitle = "Supply and Demand", kind = "accept", text = "Accept: Supply and Demand", detail = "Back to the road and follow it south all the way to Booty Bay at the southern tip of the vale, and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. Gringer, the Horde flight master, waits on the inn's upper deck.\n\nTalk to Drizzlik.\n\nFollow the road south to Booty Bay at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. Gringer, the Horde flight master, waits on the upper deck.\n\nDrizzlik, inside", index = 28},
