    {id = "b0018g01", blockID = 18, sourceBlock = 18, sourceGoal = 1, blockTitle = "Elder tigers and Lashtail raptors", sourceKind = "kill", uiMapID = 1434, x = 0.3402, y = 0.1757, coordFrame = "era", continentID = 0, worldX = -11916.2069662, worldY = 49.93175, worldZ = 17, questID = 187, objectiveIndex = 1, npcID = 1085, count = 10, questTitle = "Tiger Mastery", kind = "complete", text = "Kill Elder Stranglethorn Tiger ×10 — Tiger Mastery", detail = "The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\n\nThe Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards Grom'gol.\nCareful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.", index = 61},
    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Nesingwary's camp", sourceKind = "turnin", uiMapID = 1434, x = 0.3562, y = 0.1062, coordFrame = "era", continentID = 0, worldX = -11620.5424292, worldY = -52.16825, worldZ = 11.2, questID = 187, npcID = 717, npcName = "Ajeck Rouack", questTitle = "Tiger Mastery", kind = "turnin", text = "Turn in: Tiger Mastery", detail = "Talk to Ajeck Rouack.\n\nBack north to the camp.", index = 62},
    {id = "b0019g02", blockID = 19, sourceBlock = 19, sourceGoal = 2, blockTitle = "Nesingwary's camp", sourceKind = "accept", uiMapID = 1434, x = 0.3562, y = 0.1062, coordFrame = "era", continentID = 0, worldX = -11620.5424292, worldY = -52.16825, worldZ = 11.2, questID = 188, npcID = 717, npcName = "Ajeck Rouack", minLevel = 28, requiresAny = {187}, prerequisiteTitles = {["187"] = "Tiger Mastery"}, questTitle = "Tiger Mastery", kind = "accept", text = "Accept: Tiger Mastery", detail = "Talk to Ajeck Rouack.\n\nBack north to the camp.", index = 63},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "The Savage Coast: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.366, y = 0.0827, coordFrame = "era", continentID = 0, worldX = -11520.5695282, worldY = -114.7045, questID = 605, objectiveIndex = 1, itemID = 3918, itemName = "Singing Crystal Shard", count = 10, questTitle = "Singing Blue Shards", kind = "complete", text = "Collect Singing Crystal Shard ×10 — Singing Blue Shards", detail = "Sources: Stone Maw Basilisk, Crystal Spine Basilisk, Cold Eye Basilisk, Thrashtail Basilisk.\n\nWest past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nSin'Dall, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", index = 64},
    {id = "b0020g02", blockID = 20, sourceBlock = 20, sourceGoal = 2, blockTitle = "The Savage Coast: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.3426, y = 0.1457, coordFrame = "era", continentID = 0, worldX = -11788.5819862, worldY = 34.61675, questID = 189, objectiveIndex = 1, itemID = 1519, itemName = "Bloodscalp Ear", count = 15, questTitle = "Bloodscalp Ears", kind = "complete", text = "Collect Bloodscalp Ear ×15 — Bloodscalp Ears", detail = "Sources: Bloodscalp Warrior, Bloodscalp Axe Thrower, Bloodscalp Scavenger, Bloodscalp Shaman, Bloodscalp Mystic.\n\nWest past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nSin'Dall, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", index = 65},
    {id = "b0020g03", blockID = 20, sourceBlock = 20, sourceGoal = 3, blockTitle = "The Savage Coast: kill these as you meet them", sourceKind = "kill", uiMapID = 1434, x = 0.2779, y = 0.1432, coordFrame = "era", continentID = 0, worldX = -11777.9465712, worldY = 447.483625, worldZ = 48.8, questID = 194, objectiveIndex = 1, npcID = 685, count = 10, questTitle = "Raptor Mastery", kind = "complete", text = "Kill Stranglethorn Raptor ×10 — Raptor Mastery", detail = "West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nSin'Dall, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", index = 66},
    {id = "b0020g04", blockID = 20, sourceBlock = 20, sourceGoal = 4, blockTitle = "The Savage Coast: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.318, y = 0.164, coordFrame = "era", continentID = 0, worldX = -11866.433224, worldY = 191.5955, questID = 188, objectiveIndex = 1, itemID = 3879, itemName = "Paw of Sin'Dall", count = 1, questTitle = "Tiger Mastery", kind = "complete", text = "Collect Paw of Sin'Dall ×1 — Tiger Mastery", detail = "From Sin'Dall.\n\nWest past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nSin'Dall, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", index = 67},
    {id = "b0021g01", blockID = 21, sourceBlock = 21, sourceGoal = 1, blockTitle = "Nesingwary's camp", sourceKind = "turnin", uiMapID = 1434, x = 0.3566, y = 0.1081, coordFrame = "era", continentID = 0, worldX = -11628.6253446, worldY = -54.72075, worldZ = 11, questID = 194, npcID = 715, npcName = "Hemet Nesingwary", questTitle = "Raptor Mastery", kind = "turnin", text = "Turn in: Raptor Mastery", detail = "Talk to Hemet Nesingwary.", index = 68},
