    {id = "b0022g01", blockID = 22, sourceBlock = 22, sourceGoal = 1, blockTitle = "Level 35", sourceKind = "goto", uiMapID = 1434, x = 0.304, y = 0.236, coordFrame = "era", continentID = 0, worldX = -12172.733176, worldY = 280.933, conditions = {{k = "level", n = 35, op = "<"}}, kind = "goto", text = "Go to Lashtail Raptors", detail = "Booty Bay's and Grom'gol's next quests are 35-38. Below 35? The Lashtail Raptors (35) hunt the slopes south of the camp, on your way back to Grom'gol: kill them until level 35. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.", index = 71},
    {id = "b0022g02", blockID = 22, sourceBlock = 22, sourceGoal = 2, blockTitle = "Level 35", sourceKind = "level", conditions = {{k = "level", n = 35, op = "<"}}, kind = "level", level = 35, levelFraction = 0, text = "Reach level 35", detail = "Booty Bay's and Grom'gol's next quests are 35-38. Below 35? The Lashtail Raptors (35) hunt the slopes south of the camp, on your way back to Grom'gol: kill them until level 35. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.\n\ngrind on Lashtail Raptor", index = 72},
    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Fly to Booty Bay", sourceKind = "turnin", uiMapID = 1434, x = 0.2829, y = 0.7759, coordFrame = "era", continentID = 0, worldX = -14469.5573994, worldY = 415.577375, worldZ = 25.5, questID = 575, npcID = 2495, npcName = "Drizzlik", questTitle = "Supply and Demand", kind = "turnin", text = "Turn in: Supply and Demand", detail = "Drizzlik's shop is in the building east of the inn; Crank Fizzlebub is on the inn's bottom floor, Kebok and Krazek on its top floor beside the flight master.\n\nTalk to Drizzlik.\n\nHead south down the coast to Grom'gol and fly to Booty Bay.\n\nDrizzlik, inside", index = 73},
    {id = "b0023g02", blockID = 23, sourceBlock = 23, sourceGoal = 2, blockTitle = "Fly to Booty Bay", sourceKind = "accept", uiMapID = 1434, x = 0.2829, y = 0.7759, coordFrame = "era", continentID = 0, worldX = -14469.5573994, worldY = 415.577375, worldZ = 25.5, questID = 577, npcID = 2495, npcName = "Drizzlik", minLevel = 31, requiresAny = {575}, prerequisiteTitles = {["575"] = "Supply and Demand"}, questTitle = "Some Assembly Required", kind = "accept", text = "Accept: Some Assembly Required", detail = "Talk to Drizzlik.\n\nHead south down the coast to Grom'gol and fly to Booty Bay.", index = 74},
