    {id = "b0023g04", blockID = 23, sourceBlock = 23, sourceGoal = 4, blockTitle = "Fly to Booty Bay", sourceKind = "turnin", uiMapID = 1434, x = 0.2695, y = 0.7721, coordFrame = "era", continentID = 0, worldX = -14453.3915686, worldY = 501.086125, worldZ = 26.4, questID = 201, npcID = 773, npcName = "Krazek", questTitle = "Investigate the Camp", kind = "turnin", text = "Turn in: Investigate the Camp", detail = "Talk to Krazek.\n\nHead south down the coast to Grom'gol and fly to Booty Bay.\n\nKrazek, upstairs", index = 76},
    {id = "b0023g05", blockID = 23, sourceBlock = 23, sourceGoal = 5, blockTitle = "Fly to Booty Bay", sourceKind = "turnin", uiMapID = 1434, x = 0.27, y = 0.7713, coordFrame = "era", continentID = 0, worldX = -14449.9882358, worldY = 497.8955, worldZ = 26.4, questID = 189, npcID = 737, npcName = "Kebok", questTitle = "Bloodscalp Ears", kind = "turnin", text = "Turn in: Bloodscalp Ears", detail = "Talk to Kebok.\n\nHead south down the coast to Grom'gol and fly to Booty Bay.\n\nKebok, upstairs", index = 77},
