    {id = "b0024g03", blockID = 24, sourceBlock = 24, sourceGoal = 3, blockTitle = "Fly to Grom'gol", sourceKind = "accept", uiMapID = 1434, x = 0.3212, y = 0.2924, coordFrame = "era", continentID = 0, worldX = -12412.6681384, worldY = 171.1755, worldZ = 3.4, questID = 570, npcID = 2465, npcName = "Far Seer Mok'thardin", minLevel = 33, questTitle = "Mok'thardin's Enchantment", kind = "accept", text = "Accept: Mok'thardin's Enchantment", detail = "Talk to Far Seer Mok'thardin.\n\nFar Seer Mok'thardin, beside the flight master: the Shadowmaw and tigress parts come after the trolls", index = 80},
    {id = "b0025g01", blockID = 25, sourceBlock = 25, sourceGoal = 1, blockTitle = "Stranglethorn Vale: kill these as you meet them", sourceKind = "kill", uiMapID = 1434, x = 0.382, y = 0.205, coordFrame = "era", continentID = 0, worldX = -12040.85403, worldY = -216.8045, worldZ = 18, questID = 195, objectiveIndex = 1, npcID = 686, count = 10, questTitle = "Raptor Mastery", kind = "complete", text = "Kill Lashtail Raptor ×10 — Raptor Mastery", detail = "On your way back south to Grom'gol, the Lashtail Raptors (35-36) hunt the jungle between the camp and Grom'gol: they count for Hemet and for Commander Aggro'gosh.\n\nThe Lashtail Raptors (35-36) hunt the jungle just north-east of Grom'gol.", index = 81},
    {id = "b0025g02", blockID = 25, sourceBlock = 25, sourceGoal = 2, blockTitle = "Stranglethorn Vale: kill these as you meet them", sourceKind = "kill", uiMapID = 1434, x = 0.3824, y = 0.2049, coordFrame = "era", continentID = 0, worldX = -12040.4286134, worldY = -219.357, worldZ = 18, questID = 568, objectiveIndex = 1, npcID = 686, count = 15, questTitle = "The Defense of Grom'gol", kind = "complete", text = "Kill Lashtail Raptor ×15 — The Defense of Grom'gol", detail = "The Lashtail Raptors (35-36) hunt the jungle just north-east of Grom'gol.", index = 82},
    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "The Vile Reef", sourceKind = "collect", uiMapID = 1434, x = 0.248, y = 0.229, coordFrame = "era", continentID = 0, worldX = -12142.954014, worldY = 638.283, questID = 629, objectiveIndex = 1, itemID = 4094, itemName = "Tablet Shard", count = 1, questTitle = "The Vile Reef", kind = "complete", text = "Collect Tablet Shard ×1 — The Vile Reef", detail = "From Gri'lek the Wanderer.\n\nNorth-west of Grom'gol the Vile Reef lies under the water off the coast. The Tablet Shard rests on the sea floor by the sunken ruins; watch your breath and the murlocs.\n\nUnderwater", index = 83},
    {id = "b0027g01", blockID = 27, sourceBlock = 27, sourceGoal = 1, blockTitle = "Ruins of Zul'Kunda: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.2881, y = 0.1995, coordFrame = "era", continentID = 0, worldX = -12017.456117, worldY = 382.394875, questID = 596, objectiveIndex = 1, itemID = 3915, itemName = "Bloody Bone Necklace", count = 25, questTitle = "Bloody Bone Necklaces", kind = "complete", text = "Collect Bloody Bone Necklace ×25 — Bloody Bone Necklaces", detail = "Sources: Bloodscalp Axe Thrower, Bloodscalp Warrior, Bloodscalp Scout, Bloodscalp Hunter, Bloodscalp Berserker.\n\nThe Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a Bloody Bone Necklace. Keep looting pages of The Green Hills of Stranglethorn.", index = 84},
    {id = "b0027g02", blockID = 27, sourceBlock = 27, sourceGoal = 2, blockTitle = "Ruins of Zul'Kunda: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.2469, y = 0.1051, coordFrame = "era", continentID = 0, worldX = -11615.8628466, worldY = 645.302375, questID = 582, objectiveIndex = 1, itemID = 1532, itemName = "Shrunken Head", count = 20, questTitle = "Headhunting", kind = "complete", text = "Collect Shrunken Head ×20 — Headhunting", detail = "From Bloodscalp Headhunter.\n\nThe Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a Bloody Bone Necklace. Keep looting pages of The Green Hills of Stranglethorn.", index = 85},
    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Grom'gol", sourceKind = "turnin", uiMapID = 1434, x = 0.3216, y = 0.2772, coordFrame = "era", continentID = 0, worldX = -12348.0048152, worldY = 168.623, worldZ = 3.2, questID = 582, npcID = 2497, npcName = "Nimboya", questTitle = "Headhunting", kind = "turnin", text = "Turn in: Headhunting", detail = "Talk to Nimboya.", index = 86},
