    {id = "b0028g03", blockID = 28, sourceBlock = 28, sourceGoal = 3, blockTitle = "Grom'gol", sourceKind = "turnin", uiMapID = 1434, x = 0.3227, y = 0.2771, coordFrame = "era", continentID = 0, worldX = -12347.5793986, worldY = 161.603625, worldZ = 3.2, questID = 629, npcID = 2519, npcName = "Kin'weelay", questTitle = "The Vile Reef", kind = "turnin", text = "Turn in: The Vile Reef", detail = "Talk to Kin'weelay.", index = 88},
    {id = "b0028g04", blockID = 28, sourceBlock = 28, sourceGoal = 4, blockTitle = "Grom'gol", sourceKind = "turnin", uiMapID = 1434, x = 0.3217, y = 0.289, coordFrame = "era", continentID = 0, worldX = -12398.203974, worldY = 167.984875, worldZ = 3.1, questID = 568, npcID = 2464, npcName = "Commander Aggro'gosh", questTitle = "The Defense of Grom'gol", kind = "turnin", text = "Turn in: The Defense of Grom'gol", detail = "Commander Aggro'gosh stands in the middle of Grom'gol, Far Seer Mok'thardin beside the flight master.\n\nTalk to Commander Aggro'gosh.", index = 89},
    {id = "b0028g05", blockID = 28, sourceBlock = 28, sourceGoal = 5, blockTitle = "Grom'gol", sourceKind = "accept", uiMapID = 1434, x = 0.3217, y = 0.289, coordFrame = "era", continentID = 0, worldX = -12398.203974, worldY = 167.984875, worldZ = 3.1, questID = 569, npcID = 2464, npcName = "Commander Aggro'gosh", minLevel = 33, requiresAny = {568}, prerequisiteTitles = {["568"] = "The Defense of Grom'gol"}, questTitle = "The Defense of Grom'gol", kind = "accept", text = "Accept: The Defense of Grom'gol", detail = "Talk to Commander Aggro'gosh.", index = 90},
    {id = "b0028g06", blockID = 28, sourceBlock = 28, sourceGoal = 6, blockTitle = "Grom'gol", sourceKind = "vendor", kind = "vendor", mode = "supplies", text = "Sell unwanted items, repair and restock", manual = true, index = 91},
    {id = "b0029g01", blockID = 29, sourceBlock = 29, sourceGoal = 1, blockTitle = "Stranglethorn Vale: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.3603, y = 0.3395, coordFrame = "era", continentID = 0, worldX = -12613.039357, worldY = -78.331375, questID = 570, objectiveIndex = 1, itemID = 3838, itemName = "Shadowmaw Claw", count = 8, questTitle = "Mok'thardin's Enchantment", kind = "complete", text = "Collect Shadowmaw Claw ×8 — Mok'thardin's Enchantment", detail = "East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.\n\nFrom Shadowmaw Panther.\n\nEast of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik.\nCareful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.", index = 92},
    {id = "b0029g02", blockID = 29, sourceBlock = 29, sourceGoal = 2, blockTitle = "Stranglethorn Vale: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.3603, y = 0.3395, coordFrame = "era", continentID = 0, worldX = -12613.039357, worldY = -78.331375, questID = 570, objectiveIndex = 2, itemID = 3839, itemName = "Pristine Tigress Fang", count = 1, questTitle = "Mok'thardin's Enchantment", kind = "complete", text = "Collect Pristine Tigress Fang ×1 — Mok'thardin's Enchantment", detail = "From Stranglethorn Tigress.\n\nEast of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik.\nCareful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.", index = 93},
    {id = "b0029g03", blockID = 29, sourceBlock = 29, sourceGoal = 3, blockTitle = "Stranglethorn Vale: kill these as you meet them", sourceKind = "collect", uiMapID = 1434, x = 0.399, y = 0.284, coordFrame = "era", continentID = 0, worldX = -12376.933144, worldY = -325.28575, questID = 577, objectiveIndex = 1, itemID = 4104, itemName = "Snapjaw Crocolisk Skin", count = 5, questTitle = "Some Assembly Required", kind = "complete", text = "Collect Snapjaw Crocolisk Skin ×5 — Some Assembly Required", detail = "From Snapjaw Crocolisk.\n\nEast of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik.\nCareful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them.", index = 94},
