    {id = "b0031g01", blockID = 31, sourceBlock = 31, sourceGoal = 1, blockTitle = "Shadowmaw panthers", sourceKind = "kill", uiMapID = 1434, x = 0.387, y = 0.3286, coordFrame = "era", continentID = 0, worldX = -12566.6689476, worldY = -248.71075, worldZ = 17.4, questID = 192, objectiveIndex = 1, npcID = 684, count = 10, questTitle = "Panther Mastery", kind = "complete", text = "Kill Shadowmaw Panther ×10 — Panther Mastery", detail = "The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way.", index = 111},
    {id = "b0031g02", blockID = 31, sourceBlock = 31, sourceGoal = 2, blockTitle = "Shadowmaw panthers", sourceKind = "kill", uiMapID = 1434, x = 0.3734, y = 0.3133, coordFrame = "era", continentID = 0, worldX = -12501.5802078, worldY = -161.92575, worldZ = 12.5, questID = 569, objectiveIndex = 1, npcID = 1142, count = 10, questTitle = "The Defense of Grom'gol", kind = "complete", text = "Kill Mosh'Ogg Brute ×10 — The Defense of Grom'gol", detail = "The Mosh'Ogg ogres camp in the hills just east of Grom'gol, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time.\n\nThe Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way.", index = 112},
    {id = "b0032g01", blockID = 32, sourceBlock = 32, sourceGoal = 1, blockTitle = "Venture Co. camp", sourceKind = "collect", uiMapID = 1434, x = 0.4269, y = 0.2309, coordFrame = "era", continentID = 0, worldX = -12151.0369294, worldY = -503.322625, questID = 213, objectiveIndex = 1, itemID = 4106, itemName = "Tumbled Crystal", count = 8, questTitle = "Hostile Takeover", kind = "complete", text = "Collect Tumbled Crystal ×8 — Hostile Takeover", detail = "From Venture Co. Geologist.\n\nHead north to Lake Nazferiti, south-east of Nesingwary's camp: the Venture Co. Geologists (34-36) work the camps by the lake and carry the Tumbled Crystals.", index = 113},
    {id = "b0033g01", blockID = 33, sourceBlock = 33, sourceGoal = 1, blockTitle = "Mosh'Ogg camp", sourceKind = "kill", uiMapID = 1434, x = 0.3789, y = 0.3024, coordFrame = "era", continentID = 0, worldX = -12455.2097984, worldY = -197.022625, questID = 569, objectiveIndex = 1, npcID = 1142, count = 10, questTitle = "The Defense of Grom'gol", kind = "complete", text = "Kill Mosh'Ogg Brute ×10 — The Defense of Grom'gol", detail = "The Mosh'Ogg ogres camp in the hills just east of Grom'gol, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time.\n\nThe Mosh'Ogg ogres camp in the hills just east of Grom'gol. Kill one Brute and one Witch Doctor (36-37); pull them one at a time.", index = 114},
