    {id = "b0034g01", blockID = 34, sourceBlock = 34, sourceGoal = 1, blockTitle = "Level 36", sourceKind = "goto", uiMapID = 1434, x = 0.367, y = 0.319, coordFrame = "era", continentID = 0, worldX = -12525.828954, worldY = -121.08575, conditions = {{k = "level", n = 36, op = "<"}}, kind = "goto", text = "Go to Mosh'Ogg camp", detail = "Dustwallow's quests are 35-38. Below 36? Keep killing the Mosh'Ogg Brutes and Witch Doctors here until level 36; pull one at a time. Or, with a group, run the Scarlet Monastery dungeon (Armory) or the Razorfen Downs dungeon instead.", index = 116},
