    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Brackenwall Village: kill these as you meet them", sourceKind = "collect", uiMapID = 1445, x = 0.563, y = 0.238, coordFrame = "era", continentID = 1, worldX = -2866.333, worldY = -3930.75, questID = 1322, objectiveIndex = 1, itemID = 5959, itemName = "Acidic Venom Sac", count = 6, questTitle = "The Black Shield", kind = "complete", text = "Collect Acidic Venom Sac ×6 — The Black Shield", detail = "Sources: Darkfang Lurker, Darkfang Spider, Darkfang Venomspitter, Giant Darkfang Spider.\n\nHead west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", index = 35},
    {id = "b0015g02", blockID = 15, sourceBlock = 15, sourceGoal = 2, blockTitle = "Brackenwall Village: kill these as you meet them", sourceKind = "collect", uiMapID = 1445, x = 0.3573, y = 0.2105, coordFrame = "era", continentID = 1, worldX = -2770.083, worldY = -2850.825, questID = 1206, objectiveIndex = 1, itemID = 5884, itemName = "Unpopped Darkmist Eye", count = 40, questTitle = "Jarl Needs Eyes", kind = "complete", text = "Collect Unpopped Darkmist Eye ×40 — Jarl Needs Eyes", detail = "From Darkmist Spider.\n\nHead west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", index = 36},
    {id = "b0015g03", blockID = 15, sourceBlock = 15, sourceGoal = 3, blockTitle = "Brackenwall Village: kill these as you meet them", sourceKind = "kill", uiMapID = 1445, x = 0.3805, y = 0.2359, coordFrame = "era", continentID = 1, worldX = -2858.983, worldY = -2972.625, worldZ = 32.1, questID = 1201, objectiveIndex = 1, npcID = 4834, count = 9, questTitle = "Theramore Spies", kind = "complete", text = "Kill Theramore Infiltrator ×9 — Theramore Spies", detail = "Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", index = 37},
