    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "Portals of the Legion", sourceKind = "goto", uiMapID = 1443, x = 0.52, y = 0.78, coordFrame = "era", continentID = 1, worldX = -1886.29148, worldY = 1895.49984, kind = "goto", text = "Go to Mannoroc Coven", detail = "Head east to Mannoroc Coven. Use the Rod of Banishing by each demon portal to close six of them.\nCareful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.", index = 68},
    {id = "b0026g02", blockID = 26, sourceBlock = 26, sourceGoal = 2, blockTitle = "Portals of the Legion", sourceKind = "complete", questID = 5581, startItemID = 14547, startItemName = "Hand of Iruxos", questTitle = "Portals of the Legion", kind = "complete", text = "Complete: Portals of the Legion", detail = "Head east to Mannoroc Coven. With the Hand of Iruxos from Taiga in your bags, open a demon portal's ring: a Demon Portal Guardian (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.\n\nPortals Banished ×6.\n\nHead east to Mannoroc Coven. Use the Rod of Banishing by each demon portal to close six of them.\nCareful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake.", index = 69, objectiveTargets = {{kind = "complete", questID = 5581, questTitle = "Portals of the Legion", objectiveIndex = 1, blockTitle = "Portals of the Legion", sourceKind = "kill", npcID = 11937, text = "Quest target: Demon Portal Guardian x6", uiMapID = 1443, x = 0.509, y = 0.71, coordFrame = "era", continentID = 1, worldX = -1676.43736, worldY = 1944.9540029999998, navigationHint = "Recorded spawn or collection area. Search nearby; this marker does not track a moving NPC.", approximate = true}}},
    {id = "b0027g01", blockID = 27, sourceBlock = 27, sourceGoal = 1, blockTitle = "Ghost Walker Post", sourceKind = "accept", uiMapID = 1443, x = 0.5629, y = 0.5968, coordFrame = "era", continentID = 1, worldX = -1337.0732688, worldY = 1702.6286043, worldZ = 90, questID = 93225, npcID = 5412, npcName = "Gurda Wildmane", minLevel = 30, questTitle = "Carved Centaur Totems", kind = "accept", text = "Accept: Carved Centaur Totems", detail = "Talk to Gurda Wildmane.\n\nNorth to the post; Gurda Wildmane stands beside Felgur.", index = 70},
    {id = "b0028g01", blockID = 28, sourceBlock = 28, sourceGoal = 1, blockTitle = "Valley of Spears", sourceKind = "collect", uiMapID = 1443, x = 0.3971, y = 0.6141, coordFrame = "era", continentID = 1, worldX = -1388.9372156, worldY = 2448.0377157, questID = 93225, objectiveIndex = 1, itemID = 254432, itemName = "Carved Centaur Totem", count = 5, questTitle = "Carved Centaur Totems", kind = "complete", text = "Collect Carved Centaur Totem ×5 — Carved Centaur Totems", detail = "Sources: Maraudine Wrangler, Maraudine Scout, Maraudine Mauler, Maraudine Windchaser, Maraudine Marauder.\n\nWest of the post, the Maraudine centaurs hold the Valley of Spears. Every Maraudine can drop a Carved Centaur Totem and an ear for Felgur's Centaur Bounty.", index = 71},
