    {id = "b0015g01", blockID = 15, sourceBlock = 15, sourceGoal = 1, blockTitle = "Northfold Manor", sourceKind = "collect", uiMapID = 1417, x = 0.3178, y = 0.3298, coordFrame = "era", continentID = 0, worldX = -924.853, worldY = -2010.747, questID = 671, objectiveIndex = 1, itemID = 4495, itemName = "Bloodstone Amulet", count = 10, questTitle = "Foul Magics", kind = "complete", text = "Collect Bloodstone Amulet ×10 — Foul Magics", detail = "Sources: Syndicate Highwayman, Syndicate Pathstalker, Syndicate Mercenary.\n\nHead east out of Tarren Mill through Thoradin's Wall. The Syndicate hold the walled manor and its farm north of the road; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets.\nCareful: Highwaymen (level 30-31) can be in Sneak, so they may be hidden when you approach.", index = 27},
    {id = "b0016g01", blockID = 16, sourceBlock = 16, sourceGoal = 1, blockTitle = "The Shards of Myzrael", sourceKind = "turnin", uiMapID = 1417, x = 0.625, y = 0.3373, coordFrame = "era", continentID = 0, worldX = -942.853, worldY = -3116.667, worldZ = 48.4, questID = 635, objectID = 138492, objectName = "Shards of Myzrael", optional = true, questTitle = "Crystal in the Mountains", kind = "turnin", text = "Turn in: Crystal in the Mountains", detail = "Interact with Shards of Myzrael.\n\nFollow the road east. The violet shards glow just off the road a short way west of Hammerfall.", index = 28},
