    {id = "b0018g01", blockID = 18, sourceBlock = 18, sourceGoal = 1, blockTitle = "Stromgarde quests for a group", sourceKind = "accept", uiMapID = 1417, x = 0.738, y = 0.3396, coordFrame = "era", continentID = 0, worldX = -948.373, worldY = -3523.467, worldZ = 71, conditions = {{k = "group", q = 639}}, questID = 639, npcID = 2703, npcName = "Zengu", minLevel = 32, questTitle = "Sigil of Strom", kind = "accept", text = "Accept: Sigil of Strom", detail = "Talk to Zengu.\n\nZengu's Sigil of Strom drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle.", index = 35},
    {id = "b0019g01", blockID = 19, sourceBlock = 19, sourceGoal = 1, blockTitle = "Foul Magics with a group", sourceKind = "accept", uiMapID = 1417, x = 0.7472, y = 0.3629, coordFrame = "era", continentID = 0, worldX = -1004.293, worldY = -3556.587, worldZ = 57.3, conditions = {{k = "group", q = 673}}, questID = 673, npcID = 2706, npcName = "Tor'gan", minLevel = 35, requiresAny = {671}, prerequisiteTitles = {["671"] = "Foul Magics"}, questTitle = "Foul Magics", kind = "accept", text = "Accept: Foul Magics", detail = "Talk to Tor'gan.\n\nTor'gan's next Foul Magics is Marez Cowl, a level 40 elite warlock in Stromgarde's Syndicate quarter.", index = 36},
    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Drywhisker Gorge", sourceKind = "collect", uiMapID = 1417, x = 0.7752, y = 0.3564, coordFrame = "era", continentID = 0, worldX = -988.693, worldY = -3657.387, questID = 642, objectiveIndex = 1, itemID = 4435, itemName = "Mote of Myzrael", count = 12, questTitle = "The Princess Trapped", kind = "complete", text = "Collect Mote of Myzrael ×12 — The Princess Trapped", detail = "From Drywhisker Kobold.\n\nNorth-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", index = 37},
    {id = "b0021g01", blockID = 21, sourceBlock = 21, sourceGoal = 1, blockTitle = "Iridescent Shards", sourceKind = "turnin", uiMapID = 1417, x = 0.8431, y = 0.3095, coordFrame = "era", continentID = 0, worldX = -876.133, worldY = -3901.827, worldZ = 143.1, questID = 642, objectID = 2701, objectName = "Iridescent Shards", questTitle = "The Princess Trapped", kind = "turnin", text = "Turn in: The Princess Trapped", detail = "Interact with Iridescent Shards.\n\nThe Iridescent Shards lie at the far end of the gorge.\n\nBelow ground", index = 38},
    {id = "b0021g02", blockID = 21, sourceBlock = 21, sourceGoal = 2, blockTitle = "Iridescent Shards", sourceKind = "accept", uiMapID = 1417, x = 0.8431, y = 0.3095, coordFrame = "era", continentID = 0, worldX = -876.133, worldY = -3901.827, worldZ = 143.1, questID = 651, objectID = 2701, objectName = "Iridescent Shards", minLevel = 30, requiresAny = {642}, prerequisiteTitles = {["642"] = "The Princess Trapped"}, questTitle = "Stones of Binding", kind = "accept", text = "Accept: Stones of Binding", detail = "Interact with Iridescent Shards.\n\nThe Iridescent Shards lie at the far end of the gorge.", index = 39},
    {id = "b0022g01", blockID = 22, sourceBlock = 22, sourceGoal = 1, blockTitle = "The Stone of East Binding", sourceKind = "collect", uiMapID = 1417, x = 0.667, y = 0.2972, coordFrame = "era", continentID = 0, worldX = -846.613, worldY = -3267.867, questID = 651, objectiveIndex = 2, itemID = 4484, itemName = "Cresting Key", count = 1, questTitle = "Stones of Binding", kind = "complete", text = "Collect Cresting Key ×1 — Stones of Binding", detail = "From Stone of East Binding.\n\nEach Circle of Binding is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of Hammerfall.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", index = 40},
    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Boulderfist Hall", sourceKind = "kill", uiMapID = 1417, x = 0.5515, y = 0.7274, coordFrame = "era", continentID = 0, worldX = -1879.093, worldY = -2852.067, worldZ = 64.1, questID = 678, objectiveIndex = 1, npcID = 2566, count = 10, questTitle = "Call to Arms", kind = "complete", text = "Kill Boulderfist Brute ×10 — Call to Arms", detail = "The Boulderfist Brutes camp outside the ogres' hall, far south-west of Hammerfall; the Magus stand among them. Pull them one at a time.\n\nThe Boulderfist Brutes camp outside the ogres' hall south of Hammerfall; the Magus stand among them. Pull them one at a time.", index = 41},
    {id = "b0023g02", blockID = 23, sourceBlock = 23, sourceGoal = 2, blockTitle = "Boulderfist Hall", sourceKind = "kill", uiMapID = 1417, x = 0.5405, y = 0.7176, coordFrame = "era", continentID = 0, worldX = -1855.573, worldY = -2812.467, worldZ = 63, questID = 678, objectiveIndex = 2, npcID = 2567, count = 4, questTitle = "Call to Arms", kind = "complete", text = "Kill Boulderfist Magus ×4 — Call to Arms", detail = "The Boulderfist Brutes camp outside the ogres' hall south of Hammerfall; the Magus stand among them. Pull them one at a time.", index = 42},
    {id = "b0024g01", blockID = 24, sourceBlock = 24, sourceGoal = 1, blockTitle = "Fleshstalker raptors", sourceKind = "collect", uiMapID = 1417, x = 0.5309, y = 0.6878, coordFrame = "era", continentID = 0, worldX = -1784.053, worldY = -2777.907, questID = 701, objectiveIndex = 1, itemID = 4513, itemName = "Raptor Heart", count = 12, questTitle = "Guile of the Raptor", kind = "complete", text = "Collect Raptor Heart ×12 — Guile of the Raptor", detail = "From Highland Fleshstalker.\n\nHighland Fleshstalkers (36-37) hunt the southern highlands, a pack north of Boulderfist Hall and another on the plain to its west. Pull them one at a time.", index = 43},
    {id = "b0025g01", blockID = 25, sourceBlock = 25, sourceGoal = 1, blockTitle = "Go'shek Farm", sourceKind = "collect", uiMapID = 1417, x = 0.601, y = 0.593, coordFrame = "era", continentID = 0, worldX = -1556.533, worldY = -3030.267, questID = 92519, objectiveIndex = 1, itemID = 278462, itemName = "Packaged Tonics", count = 1, questTitle = "Ward Restocking", kind = "complete", text = "Collect Packaged Tonics ×1 — Ward Restocking", detail = "Apothecary Jorell's lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to Hammerfall; the case of Packaged Tonics is inside.\n\nApothecary Jorell's lab shack stands at Go'shek Farm, south-west of the raptors' plain; the case of Packaged Tonics is inside.", index = 44},
