    {id = "b0030g01", blockID = 30, sourceBlock = 30, sourceGoal = 1, blockTitle = "The Stone of Inner Binding", sourceKind = "turnin", uiMapID = 1417, x = 0.3623, y = 0.5738, coordFrame = "era", continentID = 0, worldX = -1510.453, worldY = -2170.947, worldZ = 17.3, questID = 651, objectID = 2702, objectName = "Stone of Inner Binding", questTitle = "Stones of Binding", kind = "turnin", text = "Turn in: Stones of Binding", detail = "Interact with Stone of Inner Binding.\n\nThe inner circle lies south of the western circle, east of Stromgarde.", index = 57},
