    {id = "b0004g06", blockID = 4, sourceBlock = 4, sourceGoal = 6, blockTitle = "Kargath", sourceKind = "vendor", kind = "vendor", mode = "supplies", text = "Sell unwanted items, repair and restock", manual = true, detail = "Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", index = 11},
    {id = "b0005g01", blockID = 5, sourceBlock = 5, sourceGoal = 1, blockTitle = "Lesser Rock Elementals", sourceKind = "collect", uiMapID = 1418, x = 0.1314, y = 0.392, coordFrame = "era", continentID = 0, worldX = -6539.649928, worldY = -2406.0245, questID = 710, objectiveIndex = 1, itemID = 4626, itemName = "Small Stone Shard", count = 10, questTitle = "Study of the Elements: Rock", kind = "complete", text = "Collect Small Stone Shard ×10 — Study of the Elements: Rock", detail = "From Lesser Rock Elemental.\n\nThe small elementals drift across the flats between Kargath and Lotwil's camp, on the road back east. Every rock elemental in the zone can drop Jarkal's Rock Elemental Shards.", index = 12},
