    {id = "b0007g01", blockID = 7, sourceBlock = 7, sourceGoal = 1, blockTitle = "Badlands: kill these as you meet them", sourceKind = "collect", uiMapID = 1418, x = 0.2825, y = 0.476, coordFrame = "era", continentID = 0, worldX = -6678.949984, worldY = -2781.88575, questID = 1419, objectiveIndex = 1, itemID = 6166, itemName = "Coyote Jawbone", count = 30, questTitle = "Coyote Thieves", kind = "complete", text = "Collect Coyote Jawbone ×30 — Coyote Thieves", detail = "From Crag Coyote.\n\nThe Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards.\nThe bigger Rock Elementals stand on the slopes north-west of the Dustbowl; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.", index = 16},
