    {id = "b0007g04", blockID = 7, sourceBlock = 7, sourceGoal = 4, blockTitle = "Badlands: kill these as you meet them", sourceKind = "collect", uiMapID = 1418, x = 0.3664, y = 0.7408, coordFrame = "era", continentID = 0, worldX = -7118.0768272, worldY = -2990.587, questID = 711, objectiveIndex = 1, itemID = 4627, itemName = "Large Stone Slab", count = 3, questTitle = "Study of the Elements: Rock", kind = "complete", text = "Collect Large Stone Slab ×3 — Study of the Elements: Rock", detail = "South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of Agmond's End; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.\n\nFrom Rock Elemental.\n\nThe Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards.\nThe bigger Rock Elementals stand on the slopes north-west of the Dustbowl; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.", index = 19},
    {id = "b0007g05", blockID = 7, sourceBlock = 7, sourceGoal = 5, blockTitle = "Badlands: kill these as you meet them", sourceKind = "collect", uiMapID = 1418, x = 0.3664, y = 0.7408, coordFrame = "era", continentID = 0, worldX = -7118.0768272, worldY = -2990.587, questID = 2258, objectiveIndex = 3, itemID = 7848, itemName = "Rock Elemental Shard", count = 5, questTitle = "Badlands Reagent Run", kind = "complete", text = "Collect Rock Elemental Shard ×5 — Badlands Reagent Run", detail = "Sources: Rock Elemental, Lesser Rock Elemental, Greater Rock Elemental, Enraged Rock Elemental, Rumbler.\n\nThe Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards.\nThe bigger Rock Elementals stand on the slopes north-west of the Dustbowl; each one drops a slab. Every rock elemental can drop Jarkal's Rock Elemental Shards.", index = 20},
    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Lotwil Veriatus", sourceKind = "turnin", uiMapID = 1418, x = 0.2595, y = 0.4487, coordFrame = "era", continentID = 0, worldX = -6633.6774658, worldY = -2724.67325, worldZ = 243.4, questID = 711, npcID = 2921, npcName = "Lotwil Veriatus", questTitle = "Study of the Elements: Rock", kind = "turnin", text = "Turn in: Study of the Elements: Rock", detail = "North-west across the basin to Lotwil's camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five.\n\nTalk to Lotwil Veriatus.", index = 21},
    {id = "b0008g02", blockID = 8, sourceBlock = 8, sourceGoal = 2, blockTitle = "Lotwil Veriatus", sourceKind = "accept", uiMapID = 1418, x = 0.2595, y = 0.4487, coordFrame = "era", continentID = 0, worldX = -6633.6774658, worldY = -2724.67325, worldZ = 243.4, questID = 712, npcID = 2921, npcName = "Lotwil Veriatus", minLevel = 35, optional = true, requiresAny = {711}, prerequisiteTitles = {["711"] = "Study of the Elements: Rock"}, questTitle = "Study of the Elements: Rock", kind = "accept", text = "Accept: Study of the Elements: Rock", detail = "Talk to Lotwil Veriatus.", index = 22},
    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "Agmond's End", sourceKind = "accept", uiMapID = 1418, x = 0.5139, y = 0.7687, coordFrame = "era", continentID = 0, worldX = -7164.3443458, worldY = -3357.49325, worldZ = 244.9, questID = 709, npcID = 2785, npcName = "Theldurin the Lost", minLevel = 30, questTitle = "Solution to Doom", kind = "accept", text = "Accept: Solution to Doom", detail = "Theldurin sits among the dwarven ruins at Agmond's End, just east of the elementals.\n\nTalk to Theldurin the Lost.\n\nTheldurin sits among the dwarven ruins at Agmond's End, south of the Valley of Fangs.", index = 23},
    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "Stonevault troggs", sourceKind = "collect", uiMapID = 1418, x = 0.5118, y = 0.7165, coordFrame = "era", continentID = 0, worldX = -7077.779311, worldY = -3352.2695, questID = 1108, objectiveIndex = 1, itemID = 5797, itemName = "Indurium Flake", count = 10, questTitle = "Indurium", kind = "complete", text = "Collect Indurium Flake ×10 — Indurium", detail = "The Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way north from Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.\n\nFrom Stonevault Bonesnapper.\n\nThe Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way to Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.", index = 24},
    {id = "b0010g02", blockID = 10, sourceBlock = 10, sourceGoal = 2, blockTitle = "Stonevault troggs", sourceKind = "collect", uiMapID = 1418, x = 0.5013, y = 0.7787, coordFrame = "era", continentID = 0, worldX = -7180.9276858, worldY = -3326.15075, questID = 703, objectiveIndex = 1, itemID = 3404, itemName = "Buzzard Wing", count = 4, questTitle = "Barbecued Buzzard Wings", kind = "complete", text = "Collect Buzzard Wing ×4 — Barbecued Buzzard Wings", detail = "Sources: Buzzard, Giant Buzzard, Starving Buzzard.\n\nThe Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way to Agmond's End; the Bonesnappers and Shamans drop the flakes. The Buzzards for Rigglefuzz's wings circle the hills between the Valley of Fangs and Agmond's End.", index = 25},
    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Valley of Fangs", sourceKind = "turnin", uiMapID = 1418, x = 0.4239, y = 0.5293, coordFrame = "era", continentID = 0, worldX = -6767.3391862, worldY = -3133.61825, worldZ = 240.7, questID = 703, npcID = 2817, npcName = "Rigglefuzz", questTitle = "Barbecued Buzzard Wings", kind = "turnin", text = "Turn in: Barbecued Buzzard Wings", detail = "Talk to Rigglefuzz.\n\nThe road north to Uldaman runs through the Valley of Fangs: Rigglefuzz and Martek take the wings and the flakes on the way.", index = 26},
    {id = "b0011g02", blockID = 11, sourceBlock = 11, sourceGoal = 2, blockTitle = "Valley of Fangs", sourceKind = "turnin", uiMapID = 1418, x = 0.4222, y = 0.5269, coordFrame = "era", continentID = 0, worldX = -6763.3591846, worldY = -3129.3895, worldZ = 241.4, questID = 1108, npcID = 4618, npcName = "Martek the Exiled", questTitle = "Indurium", kind = "turnin", text = "Turn in: Indurium", detail = "Talk to Martek the Exiled.\n\nThe road north to Uldaman runs through the Valley of Fangs: Rigglefuzz and Martek take the wings and the flakes on the way.", index = 27},
    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Ancient Chest", sourceKind = "collect", uiMapID = 1418, x = 0.3934, y = 0.1882, coordFrame = "era", continentID = 0, worldX = -6201.6814588, worldY = -3057.7495, questID = 709, objectiveIndex = 1, itemID = 4631, itemName = "Tablet of Ryun'eh", count = 1, questTitle = "Solution to Doom", kind = "complete", text = "Collect Tablet of Ryun'eh ×1 — Solution to Doom", detail = "From Ancient Chest.\n\nKeep north on the road; the chest lies in the Uldaman dig site, at the foot of the ruins north-west of the road.\n\nBelow ground", index = 28},
    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "Agmond's End", sourceKind = "turnin", uiMapID = 1418, x = 0.5139, y = 0.7687, coordFrame = "era", continentID = 0, worldX = -7164.3443458, worldY = -3357.49325, worldZ = 244.9, questID = 709, npcID = 2785, npcName = "Theldurin the Lost", questTitle = "Solution to Doom", kind = "turnin", text = "Turn in: Solution to Doom", detail = "Talk to Theldurin the Lost.\n\nHead back south down the road, past the Valley of Fangs.", index = 29},
    {id = "b0013g02", blockID = 13, sourceBlock = 13, sourceGoal = 2, blockTitle = "Agmond's End", sourceKind = "accept", uiMapID = 1418, x = 0.5139, y = 0.7687, coordFrame = "era", continentID = 0, worldX = -7164.3443458, worldY = -3357.49325, worldZ = 244.9, questID = 728, npcID = 2785, npcName = "Theldurin the Lost", minLevel = 30, requiresAny = {709}, prerequisiteTitles = {["709"] = "Solution to Doom"}, questTitle = "To the Undercity for Yagyin's Digest", kind = "accept", text = "Accept: To the Undercity for Yagyin's Digest", detail = "Talk to Theldurin the Lost.\n\nHead back south down the road, past the Valley of Fangs.", index = 30},
    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "The Dustbowl: kill these as you meet them", sourceKind = "collect", uiMapID = 1418, x = 0.1703, y = 0.843, coordFrame = "era", continentID = 0, worldX = -7287.558562, worldY = -2502.78825, questID = 712, objectiveIndex = 1, itemID = 4628, itemName = "Bracers of Rock Binding", count = 5, optional = true, questTitle = "Study of the Elements: Rock", kind = "complete", text = "Collect Bracers of Rock Binding ×5 — Study of the Elements: Rock", detail = "From Greater Rock Elemental.\n\nEvery rock elemental in the Badlands drops Jarkal's shards: the Lesser Rock Elementals (37) on the flats west of Lotwil's camp are the safe ones, about one kill in five. Only the Greater Rock Elementals (42-44, well above you) in the south-western gulches drop Lotwil's bracers, also about one kill in five: pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way.", index = 31},
