    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "The Bloodsail ships", sourceKind = "collect", uiMapID = 1434, x = 0.2919, y = 0.886, coordFrame = "era", continentID = 0, worldX = -14937.941076, worldY = 358.146125, itemID = 4056, itemName = "Cortello's Riddle", optional = true, kind = "note", manual = true, text = "Collect Cortello's Riddle ×1", detail = "Optional, and tough at 41: the scroll, Cortello's Riddle, lies on the decks of the three ships off the Wild Shore, crewed by pirates of 42-45 who come in pairs. Take it only if you can pull the crew to the rail one at a time, or with a friend; its chain runs on through the Swamp of Sorrows, Dustwallow Marsh and the Hinterlands.", index = 37},
    {id = "b0011g02", blockID = 11, sourceBlock = 11, sourceGoal = 2, blockTitle = "The Bloodsail ships", sourceKind = "accept", questID = 624, itemID = 4056, itemName = "Cortello's Riddle", minLevel = 35, optional = true, questTitle = "Cortello's Riddle", kind = "accept", text = "Accept: Cortello's Riddle", detail = "Use Cortello's Riddle to start this quest.\n\nOptional, and tough at 41: the scroll, Cortello's Riddle, lies on the decks of the three ships off the Wild Shore, crewed by pirates of 42-45 who come in pairs. Take it only if you can pull the crew to the rail one at a time, or with a friend; its chain runs on through the Swamp of Sorrows, Dustwallow Marsh and the Hinterlands.\n\nfor a later stop in the Swamp of Sorrows", index = 38},
    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Witch Doctor Unbagwa", sourceKind = "accept", uiMapID = 1434, x = 0.3527, y = 0.6041, coordFrame = "era", continentID = 0, worldX = -13738.6916806, worldY = -29.833875, worldZ = 44.6, questID = 349, npcID = 1449, npcName = "Witch Doctor Unbagwa", minLevel = 32, questTitle = "Stranglethorn Fever", kind = "accept", text = "Accept: Stranglethorn Fever", detail = "Talk to Witch Doctor Unbagwa.\n\nTake the road north out of Booty Bay; Unbagwa sits on a hill in Mistvale Valley, east of the road.\n\nInside Spirit Den", index = 39},
    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "Mistvale gorillas", sourceKind = "collect", uiMapID = 1434, x = 0.3509, y = 0.6075, coordFrame = "era", continentID = 0, worldX = -13753.155845, worldY = -18.347625, questID = 349, objectiveIndex = 1, itemID = 2799, itemName = "Gorilla Fang", count = 10, questTitle = "Stranglethorn Fever", kind = "complete", text = "Collect Gorilla Fang ×10 — Stranglethorn Fever", detail = "Sources: Enraged Silverback Gorilla, Jungle Thunderer, Mistvale Gorilla, Skymane Gorilla, Silverback Patriarch.\n\nThe gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang.", index = 40},
    {id = "b0013g02", blockID = 13, sourceBlock = 13, sourceGoal = 2, blockTitle = "Mistvale gorillas", sourceKind = "collect", uiMapID = 1434, x = 0.33, y = 0.661, coordFrame = "era", continentID = 0, worldX = -13980.753726, worldY = 115.0205, questID = 571, objectiveIndex = 1, itemID = 3862, itemName = "Aged Gorilla Sinew", count = 1, questTitle = "Mok'thardin's Enchantment", kind = "complete", text = "Collect Aged Gorilla Sinew ×1 — Mok'thardin's Enchantment", detail = "From Elder Mistvale Gorilla.\n\nThe gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang.", index = 41},
    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Witch Doctor Unbagwa", sourceKind = "turnin", uiMapID = 1434, x = 0.3527, y = 0.6041, coordFrame = "era", continentID = 0, worldX = -13738.6916806, worldY = -29.833875, worldZ = 44.6, questID = 349, npcID = 1449, npcName = "Witch Doctor Unbagwa", questTitle = "Stranglethorn Fever", kind = "turnin", text = "Turn in: Stranglethorn Fever", detail = "Talk to Witch Doctor Unbagwa.\n\nHand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then Mokk. Fight them one at a time.\n\nInside Spirit Den", index = 42},
    {id = "b0014g02", blockID = 14, sourceBlock = 14, sourceGoal = 2, blockTitle = "Witch Doctor Unbagwa", sourceKind = "collect", uiMapID = 1434, x = 0.3505, y = 0.6088, coordFrame = "era", continentID = 0, worldX = -13758.6862608, worldY = -15.795125, questID = 348, objectiveIndex = 1, itemID = 2797, itemName = "Heart of Mokk", count = 1, questTitle = "Stranglethorn Fever", kind = "complete", text = "Collect Heart of Mokk ×1 — Stranglethorn Fever", detail = "From Mokk the Savage.\n\nHand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then Mokk. Fight them one at a time.", index = 43},
