    {id = "b0020g01", blockID = 20, sourceBlock = 20, sourceGoal = 1, blockTitle = "Zul'Kunda", sourceKind = "collect", uiMapID = 1434, x = 0.2344, y = 0.0812, coordFrame = "era", continentID = 0, worldX = -11514.1882792, worldY = 725.068, questID = 584, objectiveIndex = 1, itemID = 3904, itemName = "Gan'zulah's Head", count = 1, questTitle = "Bloodscalp Clan Heads", kind = "complete", text = "Collect Gan'zulah's Head ×1 — Bloodscalp Clan Heads", detail = "From Gan'zulah.\n\nWest of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the Uldaman dungeon instead.", index = 58},
    {id = "b0020g02", blockID = 20, sourceBlock = 20, sourceGoal = 2, blockTitle = "Zul'Kunda", sourceKind = "collect", uiMapID = 1434, x = 0.2352, y = 0.0953, coordFrame = "era", continentID = 0, worldX = -11574.1720198, worldY = 719.963, questID = 584, objectiveIndex = 2, itemID = 3905, itemName = "Nezzliok's Head", count = 1, questTitle = "Bloodscalp Clan Heads", kind = "complete", text = "Collect Nezzliok's Head ×1 — Bloodscalp Clan Heads", detail = "From Nezzliok the Dire.\n\nWest of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the Uldaman dungeon instead.", index = 59},
    {id = "b0020g03", blockID = 20, sourceBlock = 20, sourceGoal = 3, blockTitle = "Zul'Kunda", sourceKind = "level", kind = "level", level = 41, levelFraction = 0, text = "Reach level 41", detail = "West of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the Uldaman dungeon instead.\n\ngrind on the Bloodscalps here: Speaking with Gan'zulah, at the cauldron next, sends you to Skullsplitters of 41-43", index = 60},
