    {id = "b0006g01", blockID = 6, sourceBlock = 6, sourceGoal = 1, blockTitle = "Riding at 40", sourceKind = "train", races = {"Orc"}, uiMapID = 1454, x = 0.6941, y = 0.131, coordFrame = "era", continentID = 1, worldX = 2151.337504, worldY = -4654.1491305, worldZ = 50.1, conditions = {{k = "level", n = 40, op = ">="}}, npcID = 4752, npcName = "Kildar", optional = true, kind = "train", text = "Train available abilities", manual = true, detail = "Riding needs level 40 and costs 100 gold; learning it gives you a mount. Kildar teaches Orcs in the Valley of Honor, by Ogunaro Wolfrunner's kennel. Skyborne learn it from Genn Fairweather at the Fairweather Stables in Valanaar on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each.\n\nKildar, riding trainer", index = 8},
