    {id = "b0026g01", blockID = 26, sourceBlock = 26, sourceGoal = 1, blockTitle = "Waterspring Field: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.6521, y = 0.3997, coordFrame = "era", continentID = 1, worldX = -7713.62, worldY = -4718.24, worldZ = 9.6, questID = 1691, objectiveIndex = 3, npcID = 5617, count = 10, questTitle = "More Wastewander Justice", kind = "complete", text = "Kill Wastewander Shadow Mage ×10 — More Wastewander Justice", detail = "The shadow mages, rogues and assassins camp south-east of Gadgetzan.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; Caliph stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them.", index = 64},
