    {id = "b0041g01", blockID = 41, sourceBlock = 41, sourceGoal = 1, blockTitle = "Ruins of Isildien: kill these as you meet them", sourceKind = "kill", uiMapID = 1444, x = 0.6178, y = 0.5465, coordFrame = "era", continentID = 1, worldX = -4898.7834845, worldY = 1147.957, worldZ = 81.3, questID = 2980, objectiveIndex = 3, npcID = 5234, count = 5, questTitle = "The Ogres of Feralas", kind = "complete", text = "Kill Gordunni Mauler ×5 — The Ogres of Feralas", detail = "Ride west from the hive to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.\n\nGordunni Mauler walks around Ruins of Isildien: look inside the circle on the map", index = 122},
    {id = "b0041g02", blockID = 41, sourceBlock = 41, sourceGoal = 2, blockTitle = "Ruins of Isildien: kill these as you meet them", sourceKind = "kill", uiMapID = 1444, x = 0.6183, y = 0.5567, coordFrame = "era", continentID = 1, worldX = -4946.0434811, worldY = 1144.482, worldZ = 76.8, questID = 2980, objectiveIndex = 2, npcID = 5240, count = 10, questTitle = "The Ogres of Feralas", kind = "complete", text = "Kill Gordunni Warlock ×10 — The Ogres of Feralas", detail = "Ride west from the hive to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.", index = 123},
