    {id = "b0041g04", blockID = 41, sourceBlock = 41, sourceGoal = 4, blockTitle = "Ruins of Isildien: kill these as you meet them", sourceKind = "collect", uiMapID = 1444, x = 0.6027, y = 0.6724, coordFrame = "era", continentID = 1, worldX = -5482.1201092, worldY = 1252.902, questID = 2979, objectiveIndex = 1, itemID = 9371, itemName = "Gordunni Orb", count = 1, questTitle = "Dark Ceremony", kind = "complete", text = "Collect Gordunni Orb ×1 — Dark Ceremony", detail = "From Gordunni Mage-Lord.\n\nRide west from the hive to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.", index = 125},
    {id = "b0042g01", blockID = 42, sourceBlock = 42, sourceGoal = 1, blockTitle = "Feral Scar Vale yetis", sourceKind = "collect", uiMapID = 1444, x = 0.5588, y = 0.5881, coordFrame = "era", continentID = 1, worldX = -5091.5301373, worldY = 1558.007, questID = 2822, objectiveIndex = 1, itemID = 8973, itemName = "Thick Yeti Hide", count = 10, questTitle = "The Mark of Quality", kind = "complete", text = "Collect Thick Yeti Hide ×10 — The Mark of Quality", detail = "From Feral Scar Yeti.\n\nNorth-west of the ruins, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide.", index = 126},
    {id = "b0043g01", blockID = 43, sourceBlock = 43, sourceGoal = 1, blockTitle = "Homing Robot OOX-22/FE", sourceKind = "collect", uiMapID = 1444, x = 0.5529, y = 0.5376, coordFrame = "era", continentID = 1, worldX = -4857.5468208, worldY = 1599.012, itemID = 8705, itemName = "OOX-22/FE Distress Beacon", optional = true, kind = "note", manual = true, text = "Collect OOX-22/FE Distress Beacon ×1", detail = "Only with the distress beacon: any beast, gnoll or ogre in Feralas can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of Feral Scar Vale, just north-west of the ruins. Escort it to the dock on the Forgotten Coast; yetis and gorillas ambush you on the way. Its reward waits in Booty Bay for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock.", index = 127},
