    {id = "b0008g01", blockID = 8, sourceBlock = 8, sourceGoal = 1, blockTitle = "Broken Pillar: kill these as you meet them", sourceKind = "collect", uiMapID = 1446, x = 0.523, y = 0.453, coordFrame = "era", continentID = 1, worldX = -7958.8, worldY = -3827.45, questID = 3161, objectiveIndex = 1, itemID = 8443, itemName = "Gahz'ridian Ornament", count = 30, questTitle = "Gahz'ridian", kind = "complete", text = "Collect Gahz'ridian Ornament ×30 — Gahz'ridian", detail = "From Gahz'ridian.\n\nSouth of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", index = 17},
    {id = "b0008g02", blockID = 8, sourceBlock = 8, sourceGoal = 2, blockTitle = "Broken Pillar: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.4268, y = 0.5315, coordFrame = "era", continentID = 1, worldX = -8319.9, worldY = -3163.67, worldZ = 13.4, questID = 5863, objectiveIndex = 1, npcID = 5474, count = 10, questTitle = "The Dunemaul Compound", kind = "complete", text = "Kill Dunemaul Brute ×10 — The Dunemaul Compound", detail = "South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", index = 18},
