    {id = "b0008g04", blockID = 8, sourceBlock = 8, sourceGoal = 4, blockTitle = "Broken Pillar: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.415, y = 0.578, coordFrame = "era", continentID = 1, worldX = -8533.8, worldY = -3082.25, worldZ = 8.8, questID = 5863, objectiveIndex = 3, npcID = 12046, count = 1, questTitle = "The Dunemaul Compound", kind = "complete", text = "Kill Gor'marok the Ravager ×1 — The Dunemaul Compound", detail = "South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.\n\nBelow ground", index = 20},
    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "The Noxious Lair", sourceKind = "collect", uiMapID = 1446, x = 0.3509, y = 0.4842, coordFrame = "era", continentID = 1, worldX = -8102.32, worldY = -2639.96, questID = 82, objectiveIndex = 1, itemID = 8587, itemName = "Centipaar Insect Parts", count = 5, questTitle = "Noxious Lair Investigation", kind = "complete", text = "Collect Centipaar Insect Parts ×5 — Noxious Lair Investigation", detail = "From Centipaar Worker.\n\nWest, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you.", index = 21},
    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "Thistleshrub Valley: kill these as you meet them", sourceKind = "kill", uiMapID = 1446, x = 0.2934, y = 0.6244, coordFrame = "era", continentID = 1, worldX = -8747.24, worldY = -2243.21, worldZ = 9, questID = 3362, objectiveIndex = 1, npcID = 5490, count = 8, questTitle = "Thistleshrub Valley", kind = "complete", text = "Kill Gnarled Thistleshrub ×8 — Thistleshrub Valley", detail = "West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in Tanaris can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs.", index = 22},
