    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Tooga's escort", sourceKind = "accept", uiMapID = 1446, x = 0.3, y = 0.65, coordFrame = "era", continentID = 1, worldX = -8865.0, worldY = -2288.75, questID = 1560, npcID = 5955, npcName = "Tooga", minLevel = 40, escort = true, questTitle = "Tooga's Quest", kind = "accept", text = "Accept: Tooga's Quest", detail = "Talk to Tooga.\n\nTooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too.", index = 26},
