    {id = "b0017g01", blockID = 17, sourceBlock = 17, sourceGoal = 1, blockTitle = "Scrimshank's gear", sourceKind = "collect", uiMapID = 1446, x = 0.56, y = 0.712, coordFrame = "era", continentID = 1, worldX = -9150.2, worldY = -4082.75, questID = 10, objectiveIndex = 1, itemID = 8593, itemName = "Scrimshank's Surveying Gear", count = 1, questTitle = "The Scrimshank Redemption", kind = "complete", text = "Collect Scrimshank's Surveying Gear ×1 — The Scrimshank Redemption", detail = "From Scrimshank's Surveying Gear.\n\nFurther south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds.\n\nBelow ground", index = 41},
