    {id = "b0008g03", blockID = 8, sourceBlock = 8, sourceGoal = 3, blockTitle = "Revantusk Village", sourceKind = "accept", uiMapID = 1425, x = 0.782, y = 0.8118, coordFrame = "era", continentID = 0, worldX = -616.9532706, worldY = -4585.7, worldZ = 27.8, conditions = {{k = "group", q = 7849}}, questID = 7850, npcID = 14736, npcName = "Primal Torntusk", minLevel = 46, questTitle = "Dark Vessels", kind = "accept", text = "Accept: Dark Vessels", detail = "Talk to Primal Torntusk.\n\nSeparation Anxiety, Kidnapped Elder Torntusk! and Dark Vessels are group quests: they send you into Jintha'Alor, whose trolls are elite (46-50). Take them with a group of three or more; skip them if you are alone, the route has you grind the experience back.\nPrimal Torntusk stands up on top of the inn, above Lard: go up, the arrow cannot tell the levels apart.", index = 25},
    {id = "b0009g01", blockID = 9, sourceBlock = 9, sourceGoal = 1, blockTitle = "The Overlook Cliffs: kill these as you meet them", sourceKind = "kill", uiMapID = 1425, x = 0.7617, y = 0.8397, coordFrame = "era", continentID = 0, worldX = -688.5632799, worldY = -4507.545, worldZ = 10.3, questID = 7815, objectiveIndex = 1, npcID = 2505, count = 15, questTitle = "Snapjaws, Mon!", kind = "complete", text = "Kill Saltwater Snapjaw ×15 — Snapjaws, Mon!", detail = "The big turtles crawl along the beaches north of the village. Whiskey Slim's port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.", index = 26},
    {id = "b0009g02", blockID = 9, sourceBlock = 9, sourceGoal = 2, blockTitle = "The Overlook Cliffs: kill these as you meet them", sourceKind = "collect", uiMapID = 1425, x = 0.6933, y = 0.624, coordFrame = "era", continentID = 0, worldX = -134.933208, worldY = -4244.205, itemID = 8704, itemName = "OOX-09/HL Distress Beacon", optional = true, kind = "note", manual = true, text = "Collect OOX-09/HL Distress Beacon ×1", detail = "The big turtles crawl along the beaches north of the village. Whiskey Slim's port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.\n\nOOX-09/HL Distress Beacon, a rare drop", index = 27},
    {id = "b0010g01", blockID = 10, sourceBlock = 10, sourceGoal = 1, blockTitle = "The Overlook Cliffs: kill these as you meet them", sourceKind = "collect", uiMapID = 1425, x = 0.804, y = 0.582, coordFrame = "era", continentID = 0, worldX = -27.133194, worldY = -4670.4, conditions = {{k = "group", q = 7816}}, questID = 7816, objectiveIndex = 1, itemID = 19023, itemName = "Katoom's Best Lure", count = 1, group = {kind = "elite", rank = 1}, questTitle = "Gammerita, Mon!", kind = "complete", text = "Collect Katoom's Best Lure ×1 — Gammerita, Mon!", detail = "From Gammerita.\n\nThese are elite mobs: grouping up is encouraged, look for people to do it with. Gammerita is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.", index = 28},
    {id = "b0011g01", blockID = 11, sourceBlock = 11, sourceGoal = 1, blockTitle = "Rin'ji's Secret", sourceKind = "turnin", uiMapID = 1425, x = 0.863, y = 0.5901, coordFrame = "era", continentID = 0, worldX = -47.9231967, worldY = -4897.55, worldZ = 20.1, questID = 2742, objectID = 142127, objectName = "Rin'ji's Secret", questTitle = "Rin'ji is Trapped!", kind = "turnin", text = "Turn in: Rin'ji is Trapped!", detail = "Interact with Rin'ji's Secret.\n\nThe secret lies on the Overlook Cliffs, above the beach.", index = 29, objectiveTargets = {{kind = "complete", questID = 2742, questTitle = "Rin'ji is Trapped!", objectiveIndex = 1, blockTitle = "Highvale", sourceKind = "event", text = "Complete: Rin'ji is Trapped!", uiMapID = 1425, x = 0.34600000000000003, y = 0.563, coordFrame = "era", continentID = 0, worldX = 21.63347900000008, worldY = -2907.1000000000004, navigationHint = "Recorded event/objective point. For an escort, stay with the NPC; do not run ahead to this marker."}}},
