    {id = "b0012g01", blockID = 12, sourceBlock = 12, sourceGoal = 1, blockTitle = "Lard's lunch", sourceKind = "collect", uiMapID = 1425, x = 0.845, y = 0.412, coordFrame = "era", continentID = 0, worldX = 409.200196, worldY = -4828.25, questID = 7840, objectiveIndex = 1, itemID = 19034, itemName = "Lard's Lunch", count = 1, questTitle = "Lard Lost His Lunch", kind = "complete", text = "Collect Lard's Lunch ×1 — Lard Lost His Lunch", detail = "From Vilebranch Kidnapper.\n\nNorth along the coast, Lard's picnic basket is on the small island; a Vilebranch Kidnapper guards it.", index = 31},
    {id = "b0013g01", blockID = 13, sourceBlock = 13, sourceGoal = 1, blockTitle = "Cortello's Riddle", sourceKind = "turnin", uiMapID = 1425, x = 0.8079, y = 0.4682, coordFrame = "era", continentID = 0, worldX = 264.9535106, worldY = -4685.415, worldZ = -8.6, conditions = {{k = "onquest", q = {626}}}, questID = 626, objectID = 2556, objectName = "Cortello's Treasure", questTitle = "Cortello's Riddle", kind = "turnin", text = "Turn in: Cortello's Riddle", detail = "Interact with Cortello's Treasure.\n\nUnderwater", index = 32},
    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Shaol'watha: kill these as you meet them", sourceKind = "kill", uiMapID = 1425, x = 0.7805, y = 0.5222, coordFrame = "era", continentID = 0, worldX = 126.3534926, worldY = -4579.925, worldZ = 119.3, questID = 7828, objectiveIndex = 1, npcID = 2926, count = 15, questTitle = "Stalking the Stalkers", kind = "complete", text = "Kill Silvermane Stalker ×15 — Stalking the Stalkers", detail = "West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use Infected Bite. When a Silvermane Howler falls to 50% health or lower, it calls for help from anything within 25 yd.", index = 33},
