    {id = "b0022g02", blockID = 22, sourceBlock = 22, sourceGoal = 2, blockTitle = "Gorillas", sourceKind = "note", kind = "note", manual = true, text = "A-Me 01 then wants a Mithril Casing, an Engineering item. Skip it unless you have one.", detail = "The gorillas live on the north-east plateau. Stay out of the deepest cave: U'cha lives there.", index = 63},
    {id = "b0023g01", blockID = 23, sourceBlock = 23, sourceGoal = 1, blockTitle = "Level 52", sourceKind = "goto", uiMapID = 1449, x = 0.658, y = 0.315, coordFrame = "era", continentID = 1, worldX = -6743.66679, worldY = -1901.267, conditions = {{k = "level", n = 52, op = "<"}}, kind = "goto", text = "Go to Bloodpetal Lasher", detail = "Top up here to level 52: The Rise of the Machines at Kargath needs it, and the Plaguelands quests at the end of this guide are level 55. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", index = 64},
