    {id = "b0037g02", blockID = 37, sourceBlock = 37, sourceGoal = 2, blockTitle = "Flame Crest", sourceKind = "accept", uiMapID = 1428, x = 0.6515, y = 0.2391, coordFrame = "era", continentID = 0, worldX = -7497.9930453, worldY = -2175.018649, worldZ = 165.6, questID = 4296, npcID = 9536, npcName = "Maxwort Uberglint", minLevel = 50, questTitle = "Tablet of the Seven", kind = "accept", text = "Accept: Tablet of the Seven", detail = "Talk to Maxwort Uberglint.\n\nThe mountain lets you out beside Blackrock Stronghold, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at Flame Crest.", index = 92},
