    {id = "b0039g01", blockID = 39, sourceBlock = 39, sourceGoal = 1, blockTitle = "Krom'Grul", sourceKind = "collect", uiMapID = 1428, x = 0.7966, y = 0.4743, coordFrame = "era", continentID = 0, worldX = -7957.1229669, worldY = -2600.0406356, questID = 3822, objectiveIndex = 1, itemID = 11058, itemName = "Sha'ni's Nose-Ring", count = 1, questTitle = "Krom'Grul", kind = "complete", text = "Collect Sha'ni's Nose-Ring ×1 — Krom'Grul", detail = "From Krom'Grul.\n\nKrom'Grul walks the caves and mine tunnels of Dreadmaul Rock; if he isn't home, clear the ogres around the entrances until he comes back.\n\nBelow ground", index = 96},
    {id = "b0040g01", blockID = 40, sourceBlock = 40, sourceGoal = 1, blockTitle = "Ruins of Thaurissan: kill these as you meet them", sourceKind = "collect", uiMapID = 1428, x = 0.8581, y = 0.5707, coordFrame = "era", continentID = 0, worldX = -8145.3037681, worldY = -2780.1843446, questID = 4061, objectiveIndex = 1, itemID = 11266, itemName = "Fractured Elemental Shard", count = 10, questTitle = "The Rise of the Machines", kind = "complete", text = "Collect Fractured Elemental Shard ×10 — The Rise of the Machines", detail = "From Greater Obsidian Elemental.\n\nRide west to the dig site. War Reaver golems (53) stomp around it and drop the shards often; the Tablet of the Seven stands in its middle among the Thaurissan dwarves. Copy it.\nBlack Broodlings nest in the hills just east of Flame Crest. Use Tinkee's Draco-Incarcinatrix 900 on a broodling when it is almost dead to capture its essence.", index = 97},
