    {id = "b0013g04", blockID = 13, sourceBlock = 13, sourceGoal = 4, blockTitle = "Pathstrider", sourceKind = "collect", uiMapID = 1423, x = 0.4527, y = 0.127, coordFrame = "live", questID = 6133, objectiveIndex = 4, itemID = 15847, itemName = "Quel'Thalas Registry", count = 1, questTitle = "The Ranger Lord's Behest", kind = "complete", text = "Collect Quel'Thalas Registry ×1 — The Ranger Lord's Behest", detail = "From Quel'Thalas Registry.", index = 43},
    {id = "b0014g01", blockID = 14, sourceBlock = 14, sourceGoal = 1, blockTitle = "Corin's Crossing", sourceKind = "goto", uiMapID = 1423, x = 0.523, y = 0.582, coordFrame = "live", kind = "goto", text = "Go to Corin's Crossing", detail = "Ride south from the lodge to Corin's Crossing, on the road. Living Rot spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the Mortar and Pestle at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with Greater Invisibility. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.", index = 44},
