    {id = "b0054g01", blockID = 54, sourceBlock = 54, sourceGoal = 1, blockTitle = "Radley and Durgen", sourceKind = "kill", uiMapID = 1422, x = 0.5783, y = 0.361, coordFrame = "era", continentID = 0, worldX = 2331.800213, worldY = -2070.023, worldZ = 168.5, questID = 6023, objectiveIndex = 1, npcID = 11613, count = 1, questTitle = "Unfinished Business", kind = "complete", text = "Kill Huntsman Radley ×1 — Unfinished Business", detail = "Huntsman Radley stands east of the lumber camp; Cavalier Durgen guards the road north-east of Kirsta, toward Hearthglen.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight.", index = 118},
