    {id = "b0034g01", blockID = 34, sourceBlock = 34, sourceGoal = 1, blockTitle = "Gordo", sourceKind = "collect", races = {"Scourge"}, uiMapID = 1420, x = 0.538, y = 0.531, coordFrame = "era", continentID = 0, worldX = 2237.8625, worldY = 602.2455, questID = 99141, objectiveIndex = 3, npcID = 10666, npcName = "Gordo", itemID = 286202, itemName = "Gordo's Report", count = 1, questTitle = "Patience", kind = "complete", text = "Collect Gordo's Report ×1 — Patience", detail = "Gordo walks the long road west of Brill, past Cold Hearth Manor, and back: the arrow follows his road west until you meet him.\n\nAsk Gordo for his report", index = 109},
