    {id = "b0036g01", blockID = 36, sourceBlock = 36, sourceGoal = 1, blockTitle = "Crusader's Outpost", sourceKind = "kill", races = {"Scourge"}, uiMapID = 1420, x = 0.3414, y = 0.514, coordFrame = "era", continentID = 0, worldX = 2289.075, worldY = 1490.63175, worldZ = 32.9, questID = 427, objectiveIndex = 1, npcID = 1535, count = 10, questTitle = "At War With The Scarlet Crusade", kind = "complete", text = "Kill Scarlet Warrior ×10 — At War With The Scarlet Crusade", detail = "Scarlet Warriors guard the outpost north-west of the pumpkin fields. Bareth Dawnstone is held inside: talk to him and stay with him until he is out.\nCareful: Scarlet Warriors are level 6-7 and not elite. Once their health falls to 15% they run off to bring help, so more of them may join the fight.", index = 113},
