    {id = "b0037g14", blockID = 37, sourceBlock = 37, sourceGoal = 14, blockTitle = "Brill", sourceKind = "accept", races = {"Scourge"}, uiMapID = 1420, x = 0.6189, y = 0.5273, coordFrame = "era", continentID = 0, worldX = 2249.00875, worldY = 236.678625, worldZ = 41.3, questID = 375, npcID = 1521, npcName = "Gretchen Dedmar", minLevel = 7, questTitle = "The Chill of Death", kind = "accept", text = "Accept: The Chill of Death", detail = "Talk to Gretchen Dedmar.\n\nBack east along the road to Brill. Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.\n\nGretchen Dedmar, upstairs", index = 130},
    {id = "b0037g15", blockID = 37, sourceBlock = 37, sourceGoal = 15, blockTitle = "Brill", sourceKind = "train", races = {"Scourge"}, kind = "train", text = "Train your class abilities", manual = true, detail = "Back east along the road to Brill. Cain Firesong (mages), Dark Cleric Beryl (priests), Rupert Boch (warlocks) and Marion Call (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", index = 131},
    {id = "b0038g01", blockID = 38, sourceBlock = 38, sourceGoal = 1, blockTitle = "Tirisfal Glades: kill these as you meet them", sourceKind = "collect", races = {"Scourge"}, uiMapID = 1420, x = 0.6222, y = 0.5657, coordFrame = "era", continentID = 0, worldX = 2133.32875, worldY = 221.76675, questID = 375, objectiveIndex = 1, itemID = 2876, itemName = "Duskbat Pelt", count = 5, questTitle = "The Chill of Death", kind = "complete", text = "Collect Duskbat Pelt ×5 — The Chill of Death", detail = "Sources: Greater Duskbat, Vampiric Duskbat.\n\nGreater Duskbats fly over the fields around Brill and along the road north: Gretchen wants their pelts, Shelene their wings.\nThe Doom Weed grows in the graveyard fields just north of Brill, where the Rot Hide Graverobbers dig; all the Rot Hides drop the ichor.\nThe Rot Hide Mongrels hold the hills further north. Maggot Eye (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first.\nCareful: Gnoll guards stand outside the hut and can join the fight. If you slip past them and fight him inside, he fights alone.\nThe Vile Fin murlocs line the north shore: they all drop the scales, and the Minor Oracles and Muckdwellers the skins for Shelene.", index = 132},
